    def tr(self, message):
        return QCoreApplication.translate('WindSuitability', message)

    def _log_core_raster_state(self, prefix):
        """Debug snapshot for core rasters that must never be replaced by spatial filtering."""
        QgsMessageLog.logMessage(
            "[DEBUG] {} core rasters: wind_result_path='{}', depth_result_path='{}', clipped_dem_path='{}', prospect_result_path='{}', wind_master_path='{}'".format(
                prefix,
                getattr(self, "wind_result_path", None),
                getattr(self, "depth_result_path", None),
                getattr(self, "clipped_dem_path", None),
                getattr(self, "prospect_result_path", None),
                getattr(self, "wind_master_path", None),
            ),
            "WindSuitability",
            Qgis.Info,
        )

    def _aoi_audit_fields(self):
        """AOI extent, area, WKT hash, and analysis CRS for clip forensics."""
        aoi_layer = self.get_user_aoi_layer()
        wkt = ""
        if self.current_aoi and not self.current_aoi.isEmpty():
            try:
                wkt = self.current_aoi.asWkt()
            except Exception:
                try:
                    wkt = self.current_aoi.exportToWkt()
                except Exception:
                    wkt = ""
        wkt_hash = hashlib.sha256(wkt.encode("utf-8")).hexdigest() if wkt else ""
        extent_str = self.aoi_extent.toString() if self.aoi_extent else ""
        area_m2 = self.calculate_layer_area(aoi_layer) if aoi_layer else 0.0
        crs_id = ""
        if self.analysis_crs and self.analysis_crs.isValid():
            crs_id = self.analysis_crs.authid()
        return extent_str, area_m2, wkt_hash, crs_id

    def _output_raster_audit_fields(self, output_path):
        """Extent, dimensions, and min/max read from the file on disk."""
        path = self._normalize_path(output_path) if output_path else ""
        if not path or not os.path.exists(path):
            return "", None, None, None, None
        lyr = QgsRasterLayer(path, "clip_audit", "gdal")
        if not lyr.isValid():
            return "", None, None, None, None
        ext_str = lyr.extent().toString()
        width = lyr.width()
        height = lyr.height()
        rmin = rmax = None
        try:
            stats = lyr.dataProvider().bandStatistics(
                1, QgsRasterBandStats.All, lyr.extent(), 0
            )
            rmin = float(stats.minimumValue)
            rmax = float(stats.maximumValue)
        except Exception as _be_exc:
            _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L649")
        return ext_str, width, height, rmin, rmax

    def _log_clip_audit_record(self, record):
        """Print one clip audit block to QgsMessageLog and Python stdout."""
        lines = [
            "",
            "=" * 60,
            "CLIP AUDIT — {operation} @ {timestamp}".format(
                operation=record.get("operation", "?"),
                timestamp=record.get("timestamp", ""),
            ),
            "=" * 60,
            "1. Resolved wind source raster path: {0}".format(record.get("resolved_wind_source")),
            "2. Resolved DEM source raster path:  {0}".format(record.get("resolved_dem_source")),
            "3. AOI extent:                      {0}".format(record.get("aoi_extent")),
            "4. AOI area (m²):                   {0}".format(record.get("aoi_area_m2")),
            "5. AOI WKT hash (SHA-256):          {0}".format(record.get("aoi_wkt_hash")),
            "6. CRS:                             {0}".format(record.get("crs")),
            "7. Clip branch:                      {0}".format(record.get("clip_branch")),
            "   Source path used for this clip:   {0}".format(record.get("source_path_used")),
            "   Output raster path:               {0}".format(record.get("output_path")),
            "8. Output raster extent:            {0}".format(record.get("output_extent")),
            "9. Output raster width:             {0}".format(record.get("output_width")),
            "10. Output raster height:           {0}".format(record.get("output_height")),
            "11. Output raster min/max:          {0} / {1}".format(
                record.get("output_min"), record.get("output_max")
            ),
            "=" * 60,
        ]
        block = "\n".join(lines)
        QgsMessageLog.logMessage(block, "WindSuitability", Qgis.Info)
        print(block)

    def _clip_audit_compare_value(self, field, val_a, val_b):
        """Format comparison cell; floats compared with tolerance."""
        if val_a == val_b:
            return "SAME", val_a, val_b
        if isinstance(val_a, float) or isinstance(val_b, float):
            try:
                fa = float(val_a) if val_a is not None else None
                fb = float(val_b) if val_b is not None else None
                if fa is not None and fb is not None and math.isclose(fa, fb, rel_tol=0.0, abs_tol=1e-9):
                    return "SAME", val_a, val_b
            except (TypeError, ValueError) as _be_exc:
                _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L694")
        return "CHANGED", val_a, val_b

    def _log_clip_audit_comparison(self, run_a, run_b, label_a="Run A", label_b="Run B"):
        """Side-by-side comparison of two clip audit records; log fields that changed."""
        fields = [
            ("resolved_wind_source", "Wind source raster"),
            ("resolved_dem_source", "DEM source raster"),
            ("aoi_extent", "AOI extent"),
            ("aoi_area_m2", "AOI area (m²)"),
            ("aoi_wkt_hash", "AOI WKT hash"),
            ("crs", "CRS"),
            ("clip_branch", "Clip branch"),
            ("output_extent", "Output raster extent"),
            ("output_width", "Output raster width"),
            ("output_height", "Output raster height"),
            ("output_min", "Output raster min"),
            ("output_max", "Output raster max"),
        ]
        changed = []
        rows = []
        for key, title in fields:
            status, va, vb = self._clip_audit_compare_value(key, run_a.get(key), run_b.get(key))
            rows.append((title, status, va, vb))
            if status == "CHANGED":
                changed.append(title)

        lines = [
            "",
            "#" * 60,
            "CLIP AUDIT COMPARISON — {op}".format(op=run_b.get("operation", "?")),
            "  {0}: {1}  ->  {2}".format(label_a, run_a.get("output_path"), run_a.get("timestamp")),
            "  {0}: {1}  ->  {2}".format(label_b, run_b.get("output_path"), run_b.get("timestamp")),
            "#" * 60,
            "{0:<28} {1:<10} {2}".format("Field", label_a, label_b),
            "-" * 60,
        ]
        for title, status, va, vb in rows:
            marker = " *" if status == "CHANGED" else ""
            lines.append("{0:<28} {1:<22} {2}{3}".format(title, va, vb, marker))
        lines.append("-" * 60)
        if changed:
            lines.append("CHANGED fields: {0}".format(", ".join(changed)))
        else:
            lines.append("All compared fields are SAME (min/max difference is NOT explained by these inputs).")
        lines.append("#" * 60)
        block = "\n".join(lines)
        QgsMessageLog.logMessage(block, "WindSuitability", Qgis.Info)
        print(block)
        return changed

    def _record_and_log_clip_audit(self, operation, source_path_used, output_path):
        """Capture pre/post clip forensics and compare with the previous same-operation clip."""
        extent_str, area_m2, wkt_hash, crs_id = self._aoi_audit_fields()
        out_extent, width, height, rmin, rmax = self._output_raster_audit_fields(output_path)
        wind_src = self._resolve_wind_input_raster_path()
        dem_src = self._resolve_dem_input_raster_path()
        record = {
            "operation": operation,
            "timestamp": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "resolved_wind_source": self._normalize_path(wind_src) if wind_src else None,
            "resolved_dem_source": self._normalize_path(dem_src) if dem_src else None,
            "source_path_used": self._normalize_path(source_path_used) if source_path_used else None,
            "aoi_extent": extent_str,
            "aoi_area_m2": area_m2,
            "aoi_wkt_hash": wkt_hash,
            "crs": crs_id,
            "clip_branch": self._last_clip_branch or "unknown",
            "output_path": self._normalize_path(output_path),
            "output_extent": out_extent,
            "output_width": width,
            "output_height": height,
            "output_min": rmin,
            "output_max": rmax,
        }
        self._clip_audit_history.append(record)
        self._log_clip_audit_record(record)

        same_op = [r for r in self._clip_audit_history if r.get("operation") == operation]
        if len(same_op) >= 2:
            self._log_clip_audit_comparison(
                same_op[-2], same_op[-1],
                label_a="Run {}".format(len(same_op) - 1),
                label_b="Run {}".format(len(same_op)),
            )

        try:
            audit_dir = self.get_plugin_results_dir()
            if audit_dir and os.path.isdir(audit_dir):
                audit_file = os.path.join(audit_dir, "clip_audit_history.json")
                with open(audit_file, "w", encoding="utf-8") as fh:
                    json.dump(self._clip_audit_history, fh, indent=2)
        except Exception as _be_exc:
            _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L787")

        return record

    def initGui(self):
        icon_path = ':/plugins/wind_suitability/icon.png'
        self.action = QAction(QIcon(icon_path), self.tr("Wind Site Select"), self.iface.mainWindow())
        self.action.setToolTip(self.tr("Wind Site Select"))
        self.action.setStatusTip(self.tr("GIS-based Wind Energy Site Selection"))
        self.action.setWhatsThis(self.tr(
            "Wind Site Select — GIS-based wind energy site suitability, spatial filtering, and MCA."
        ))
        self.action.triggered.connect(self.run)
        self.iface.addPluginToMenu(self.tr("&Wind Site Select"), self.action)
        self.iface.addToolBarIcon(self.action)

    def unload(self):
        try:
            if self.tool_rectangle and self.canvas.mapTool() == self.tool_rectangle:
                self.canvas.unsetMapTool(self.tool_rectangle)
        except Exception as _be_exc:
            _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L808")
        try:
            if self.tool_polygon and self.canvas.mapTool() == self.tool_polygon:
                self.canvas.unsetMapTool(self.tool_polygon)
        except Exception as _be_exc:
            _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L813")
        self.clear_rubber_band()
        self._last_rubber_band = None
        # Clean up temporary files when plugin is unloaded
        self.cleanup_temp_files()
        self.iface.removePluginMenu(self.tr("&Wind Site Select"), self.action)
        self.iface.removeToolBarIcon(self.action)

    def clear_rubber_band(self):
        if self._last_rubber_band:
            try:
                if self.canvas and hasattr(self.canvas, 'scene') and self.canvas.scene():
                    self._last_rubber_band.reset(QgsWkbTypes.PolygonGeometry)
                    self.canvas.scene().removeItem(self._last_rubber_band)
            except Exception as _be_exc:
                _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L828")
            self._last_rubber_band = None

    # Fixed output filenames: only results/ and temp/, no nested subfolders
    PROSPECT_AREA_GPKG = "prospect_area.gpkg"
    PROSPECT_RASTER_TIF = "prospect_area.tif"
    WIND_ANALYSIS_TIF = "wind_analysis.tif"
    DEPTH_ANALYSIS_TIF = "depth_analysis.tif"
    SPATIAL_FILTERED_TIF = "spatial_filtered.tif"
    MERGED_EXCLUDE_MASK_TIF = "merged_exclude_mask.tif"
    INCLUDE_MASK_TIF = "include_mask.tif"
    RASTER_INPUT_FILE_FILTER = (
        "Raster files (*.tif *.tiff *.TIF *.TIFF *.vrt *.VRT *.img *.IMG);;"
        "All files (*.*)"
    )


    def _coerce_canonical_results_root(self, path):
        """
        Normalize any path under the project output tree to the durable .../results directory.

        Prevents nested trees such as:
          .../results/runs/.../results/runs/.../results
        by walking out of runs/, run-id folders, spatial/mca/staging/temp, and nested results.
        """
        if not path:
            return None
        p = self._normalize_path(path)
        if not p:
            return None
        if os.path.isfile(p):
            p = os.path.dirname(p)
        run_like_prefixes = ("run_", "spatial_", "mca_")
        structural = {"temp", "staging", "spatial", "mca", "vector_criteria", "runs"}
        for _ in range(64):
            base = os.path.basename(p).lower() if p else ""
            parent = os.path.dirname(p) if p else ""
            if not p or parent == p:
                break
            if base in structural:
                p = parent
                continue
            if any(base.startswith(pref) for pref in run_like_prefixes) and os.path.basename(parent).lower() == "runs":
                p = parent
                continue
            if base == "results":
                walk = parent
                nested_under_runs = False
                while walk and os.path.basename(walk):
                    wb = os.path.basename(walk).lower()
                    if wb == "runs":
                        nested_under_runs = True
                        break
                    if wb == "results":
                        break
                    nxt = os.path.dirname(walk)
                    if nxt == walk:
                        break
                    walk = nxt
                if nested_under_runs:
                    p = parent
                    continue
                return self._normalize_path(p)
            break
        if not p:
            return None
        if os.path.basename(p).lower() == "results":
            return self._normalize_path(p)
        return self._normalize_path(os.path.join(p, "results"))

    def ensure_output_dirs(self, base_path):
        """
        Set output root and create results/temp subdirs. User-selected directory is the root (no extra folder).
        Creates ONLY: output_dir/results and output_dir/temp. No nested subfolders (no wind/, bathymetry/, spatial/, etc.).
        - If base_path is a directory: use it as output_dir.
        - If base_path is a file: use its parent directory as output_dir.
        - If that directory is named "results", "temp", "runs", or a run subfolder, go up to the true root.
        """
        if not base_path or not str(base_path).strip():
            return
        base_path = os.path.abspath(str(base_path).strip())
        looks_like_file = base_path.lower().endswith(('.tif', '.tiff', '.gpkg', '.shp', '.geojson', '.json', '.nc', '.img'))
        if os.path.isfile(base_path) or looks_like_file:
            root = os.path.dirname(base_path)
        else:
            root = base_path
        root = os.path.abspath(root)
        results_root = self._coerce_canonical_results_root(root)
        if not results_root:
            return
        if os.path.basename(results_root).lower() == "results":
            root = os.path.dirname(results_root)
        else:
            root = results_root
            results_root = self._normalize_path(os.path.join(root, "results"))
        if not root:
            return
        try:
            os.makedirs(root, exist_ok=True)
        except Exception:
            return
        self.output_dir = self._normalize_path(root)
        self.results_dir = self._normalize_path(results_root)
        self.temp_dir = self._normalize_path(os.path.join(root, "temp"))
        try:
            os.makedirs(self.results_dir, exist_ok=True)
            os.makedirs(self.temp_dir, exist_ok=True)
            _rl.ensure_results_layout(self.results_dir)
        except Exception as _be_exc:
            _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L937")
        self._remember_results_root()

    def _remember_results_root(self):
        """Persist the durable results/ directory so MCA can resolve the current spatial run after UI resets."""
        root = getattr(self, "results_dir", None)
        if not root or not os.path.isdir(root):
            return
        try:
            QSettings().setValue("wind_site_select/last_results_root", self._normalize_path(root))
        except Exception as _be_exc:
            _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L948")

    def _restore_results_root_from_settings(self):
        """
        Recover results_dir/output_dir when in-memory paths were cleared (dialog reopen/reset).
        Does not invent spatial rasters — only restores where to look for the current-run manifest.
        """
        if self.results_dir and os.path.isdir(self.results_dir):
            return self._normalize_path(self.results_dir)
        try:
            remembered = QSettings().value("wind_site_select/last_results_root", "", type=str)
        except Exception:
            remembered = ""
        remembered = self._normalize_path(remembered) if remembered else None
        if remembered and os.path.isdir(remembered):
            coerced = self._coerce_canonical_results_root(remembered) or remembered
            self.results_dir = coerced
            parent = os.path.dirname(coerced)
            if os.path.basename(coerced).lower() == "results" and parent:
                self.output_dir = self._normalize_path(parent)
                temp_candidate = self._normalize_path(os.path.join(parent, "temp"))
                if os.path.isdir(temp_candidate) or parent:
                    self.temp_dir = temp_candidate
                    try:
                        os.makedirs(self.temp_dir, exist_ok=True)
                    except Exception as _be_exc:
                        _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L974")
            return coerced
        return None

    # ------------------------------------------------------------------
    # Phase 1.4.3 – canonical results root, manifest, safe publication
    # ------------------------------------------------------------------

    def get_canonical_results_root(self):
        """Durable results root (output_dir/results). Prefer user output folder; never home UUID dirs."""
        if not (self.results_dir and os.path.isdir(self.results_dir)):
            self._restore_results_root_from_settings()
        seed = None
        if self.results_dir and os.path.isdir(self.results_dir):
            seed = self.results_dir
        else:
            seed = self.get_plugin_results_dir()
        results = self._coerce_canonical_results_root(seed) if seed else None
        if results:
            try:
                os.makedirs(results, exist_ok=True)
                _rl.ensure_results_layout(results)
            except Exception as _be_exc:
                _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L997")
            self.results_dir = self._normalize_path(results)
            parent = os.path.dirname(results)
            if parent and os.path.basename(results).lower() == "results":
                self.output_dir = self._normalize_path(parent)
                temp_candidate = self._normalize_path(os.path.join(parent, "temp"))
                self.temp_dir = temp_candidate
                try:
                    os.makedirs(self.temp_dir, exist_ok=True)
                except Exception as _be_exc:
                    _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L1007")
            return self._normalize_path(results)
        # Fallback: plugin data/results under plugin_dir (stable, project-agnostic)
        fallback = self._normalize_path(os.path.join(self.plugin_dir, "data", "results"))
        try:
            os.makedirs(fallback, exist_ok=True)
            _rl.ensure_results_layout(fallback)
            if not self.results_dir:
                self.results_dir = fallback
            if not self.output_dir:
                self.output_dir = self._normalize_path(os.path.join(self.plugin_dir, "data"))
            if not self.temp_dir:
                self.temp_dir = self._normalize_path(os.path.join(self.plugin_dir, "data", "temp"))
                os.makedirs(self.temp_dir, exist_ok=True)
        except Exception as _be_exc:
            _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L1022")
        return fallback

    def _manifest_path(self):
        root = self.get_canonical_results_root()
        return self._normalize_path(os.path.join(root, _rl.CURRENT_RUN_MANIFEST_NAME))

    def _load_current_run_manifest(self):
        path = self._manifest_path()
        data, err = _rl.load_manifest(path)
        if data is None:
            self._current_run_manifest = None
            return None, err or "Manifest unavailable"
        self._current_run_manifest = data
        self._current_run_id = data.get("run_id") or None
        sf = data.get("spatial_filter") or {}
        self._current_spatial_run_id = sf.get("run_id") or None
        mca = data.get("mca") or {}
        self._current_mca_run_id = mca.get("run_id") or None
        return data, ""

    def _save_current_run_manifest(self, manifest):
        path = self._manifest_path()
        ok, err = _rl.save_manifest_atomic(path, manifest)
        if ok:
            self._current_run_manifest = manifest
            self._current_run_id = manifest.get("run_id")
            sf = manifest.get("spatial_filter") or {}
            self._current_spatial_run_id = sf.get("run_id")
            mca = manifest.get("mca") or {}
            self._current_mca_run_id = mca.get("run_id")
        return ok, err

    def _begin_run_directories(self, kind="run"):
        root = self.get_canonical_results_root()
        dirs = _rl.create_run_directories(root)
        self._active_run_dirs = dirs
        self._current_run_id = dirs["run_id"]
        return dirs

    def _protected_manifest_paths(self):
        root = self.get_canonical_results_root()
        data, _err = self._load_current_run_manifest()
        if not data:
            return []
        return _rl.referenced_paths_from_manifest(data, root)

    def _validate_byte_suitability_raster(self, path, reference_path=None):
        """Validate Byte suitability GeoTIFF (dims/CRS/transform/NoData=255)."""
        path_n = self._normalize_path(path)
        if not path_n or not os.path.isfile(path_n):
            return False, "Raster missing: {}".format(path)
        try:
            if os.path.getsize(path_n) <= 0:
                return False, "Raster empty: {}".format(path_n)
        except OSError as e:
            return False, str(e)
        if not _GDAL_AVAILABLE:
            # Fallback: QGIS-only check
            lyr = QgsRasterLayer(path_n, "validate", "gdal")
            if not lyr.isValid() or lyr.width() < 1 or lyr.height() < 1:
                return False, "Invalid raster: {}".format(path_n)
            return True, ""
        try:
            ds = gdal.Open(path_n, gdal.GA_ReadOnly)
            if not ds:
                return False, "GDAL cannot open: {}".format(path_n)
            band = ds.GetRasterBand(1)
            dt = band.DataType
            nd = band.GetNoDataValue()
            w, h = ds.RasterXSize, ds.RasterYSize
            gt = ds.GetGeoTransform()
            proj = ds.GetProjection() or ""
            ds = None
            if dt != gdal.GDT_Byte:
                return False, "Expected Byte raster, got datatype {}".format(dt)
            if nd is None or int(nd) != int(BINARY_BYTE_NODATA):
                return False, "Expected NoData={}, got {}".format(BINARY_BYTE_NODATA, nd)
            if w < 1 or h < 1:
                return False, "Invalid raster dimensions"
            if reference_path and os.path.isfile(reference_path):
                ds_ref = gdal.Open(self._normalize_path(reference_path), gdal.GA_ReadOnly)
                if ds_ref:
                    if ds_ref.RasterXSize != w or ds_ref.RasterYSize != h:
                        ds_ref = None
                        return False, "Raster dimensions do not match reference"
                    gt_ref = ds_ref.GetGeoTransform()
                    ds_ref = None
                    if gt_ref and gt:
                        for i in range(6):
                            if abs(float(gt_ref[i]) - float(gt[i])) > 1e-6:
                                return False, "Geotransform does not match reference"
            if not proj.strip() and not gt:
                return False, "Raster missing CRS/geotransform"
            return True, ""
        except Exception as e:
            return False, "Raster validation failed: {}".format(e)

    def _validate_gpkg_output(self, path, min_features=0, require_layer=True, expected_layers=None):
        path_n = self._normalize_path(path)
        if not path_n or not os.path.isfile(path_n):
            return False, "GPKG missing: {}".format(path)
        try:
            if os.path.getsize(path_n) <= 0:
                return False, "GPKG empty: {}".format(path_n)
        except OSError as e:
            return False, str(e)
        # Prefer sqlite structural validation (integrity + optional layer names)
        ok_sql, err_sql = _rl.validate_gpkg_sqlite(
            path_n,
            expected_layers=expected_layers,
            min_features=min_features if min_features else None,
        )
        if not ok_sql:
            return False, err_sql
        layer = QgsVectorLayer(path_n, "validate_gpkg", "ogr")
        if require_layer and not layer.isValid():
            return False, "GPKG not readable via OGR: {}".format(path_n)
        if min_features is not None and layer.isValid():
            fc = layer.featureCount()
            if fc >= 0 and fc < int(min_features):
                return False, "GPKG feature count {} < required {}".format(fc, min_features)
        return True, ""

    def _publish_raster_to_path(self, staging_path, final_path, reference_path=None, byte_suitability=True):
        """Publish raster: prefer _replace_raster_atomically; validate staging first."""
        staging = self._normalize_path(staging_path)
        final = self._normalize_path(final_path)
        if byte_suitability:
            ok, err = self._validate_byte_suitability_raster(staging, reference_path=reference_path)
            if not ok:
                return False, err
        else:
            if not staging or not os.path.isfile(staging):
                return False, "Staging raster missing"
        # Close handles before replace
        try:
            self._release_path_handles(staging)
        except Exception as _be_exc:
            _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L1161")
        try:
            self._release_path_handles(final)
        except Exception as _be_exc:
            _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L1165")
        return self._replace_raster_atomically(staging, final)

    def _publish_gpkg_to_path(
        self,
        staging_path,
        final_path,
        min_features=0,
        expected_layers=None,
        is_compatibility_alias=False,
    ):
        """
        Publish staged GPKG to final path with WAL checkpoint + sqlite validation.
        Never deletes destination before success. Aborts if destination has -wal/-shm.
        For compatibility aliases, failure leaves the canonical run output intact.
        """
        staging = self._normalize_path(staging_path)
        final = self._normalize_path(final_path)

        def _validate(p):
            return self._validate_gpkg_output(
                p, min_features=min_features, expected_layers=expected_layers
            )

        try:
            self._release_path_handles(staging)
            self._release_path_handles(final)
        except Exception as _be_exc:
            _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L1193")

        # After staging is valid, release plugin-owned layers on the destination path
        # so Windows can replace. Removing TOC layers does not guarantee every lock is gone.
        try:
            self._remove_vector_layers_for_disk_path(final)
        except Exception as _be_exc:
            _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L1200")
        try:
            self._release_path_handles(final)
        except Exception as _be_exc:
            _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L1204")

        ok, err = _rl.publish_gpkg_atomic(
            staging,
            final,
            validate_fn=_validate,
            expected_layers=expected_layers,
            min_features=min_features if min_features else None,
            allow_destination_sidecars=False,
        )
        if not ok and is_compatibility_alias:
            return False, (
                "Compatibility alias not updated (canonical run output unchanged): {}"
            ).format(err)
        return ok, err

    def _release_path_handles(self, path):
        """Best-effort close of GDAL/QGIS handles for a disk path (does not remove project layers)."""
        if not path:
            return
        path_n = self._normalize_path(path)
        if _GDAL_AVAILABLE:
            try:
                # Drop GDAL dataset cache entries for this path without deleting the file.
                if hasattr(gdal, "InvalidateCache"):
                    gdal.InvalidateCache()
            except Exception as _be_exc:
                _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L1231")
            try:
                ds = gdal.OpenEx(path_n, gdal.OF_READONLY)
                ds = None
            except Exception as _be_exc:
                _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L1236")

    def _publish_spatial_run_outputs(
        self,
        staging_raster,
        staging_polygons,
        staging_exclude=None,
        reference_path=None,
        input_refs=None,
        run_dirs=None,
    ):
        """
        Validate staging spatial outputs, copy into durable run dir, update manifest,
        then atomically refresh legacy convenience aliases under results/.
        Failed runs leave previous manifest and aliases unchanged.
        """
        dirs = run_dirs or self._active_run_dirs or self._begin_run_directories("spatial")
        results_root = dirs["results_root"]
        spatial_dir = dirs["spatial_dir"]
        run_id = dirs["run_id"]

        durable_raster = self._normalize_path(os.path.join(spatial_dir, self.SPATIAL_FILTERED_TIF))
        durable_poly = self._normalize_path(os.path.join(spatial_dir, "spatial_final_polygons.gpkg"))
        durable_excl = None
        if staging_exclude and os.path.isfile(staging_exclude):
            durable_excl = self._normalize_path(os.path.join(spatial_dir, self.MERGED_EXCLUDE_MASK_TIF))

        # Publish into run directory (new paths — no prior file to preserve inside this run dir)
        ok, err = self._publish_raster_to_path(
            staging_raster, durable_raster, reference_path=reference_path, byte_suitability=True
        )
        if not ok:
            return False, err, None
        ok, err = self._publish_gpkg_to_path(staging_polygons, durable_poly, min_features=0)
        if not ok:
            return False, err, None
        if durable_excl:
            ok, err = self._publish_raster_to_path(
                staging_exclude, durable_excl, reference_path=reference_path, byte_suitability=True
            )
            if not ok:
                return False, err, None

        # Update manifest first (publication boundary). Aliases refreshed after.
        existing, _ = self._load_current_run_manifest()
        spatial_section = _rl.build_spatial_section(
            results_root,
            run_id,
            durable_raster,
            durable_poly,
            exclude_mask=durable_excl,
            input_refs=input_refs or {},
        )
        new_manifest = _rl.update_manifest_after_spatial(existing, results_root, spatial_section)
        ok, err = self._save_current_run_manifest(new_manifest)
        if not ok:
            return False, "Manifest update failed (run outputs kept under {}): {}".format(spatial_dir, err), None

        # Convenience aliases for older resolvers (atomic; failure does not roll back run dir)
        alias_raster = self._normalize_path(os.path.join(results_root, self.SPATIAL_FILTERED_TIF))
        alias_poly = self._normalize_path(os.path.join(results_root, "spatial_final_polygons.gpkg"))
        alias_notes = []
        ok_a, err_a = self._publish_raster_to_path(
            durable_raster, alias_raster, reference_path=reference_path, byte_suitability=True
        )
        if not ok_a:
            alias_notes.append("Alias raster not updated: {}".format(err_a))
        ok_p, err_p = self._publish_gpkg_to_path(
            durable_poly, alias_poly, min_features=0, is_compatibility_alias=True
        )
        if not ok_p:
            alias_notes.append("Alias polygons not updated: {}".format(err_p))

        self.spatial_filter_result_path = durable_raster
        self.spatial_filter_polygons_path = durable_poly
        if durable_excl:
            self.spatial_filter_exclude_mask_path = durable_excl
        self._current_spatial_run_id = run_id
        self._spatial_stale_after_aoi_change = False

        info = {
            "run_id": run_id,
            "raster": durable_raster,
            "polygons": durable_poly,
            "exclude_mask": durable_excl,
            "alias_notes": alias_notes,
            "manifest_path": dirs["manifest_path"],
        }
        return True, "", info

    def _apply_manifest_paths_to_session(self):
        """Restore session path pointers from current_run.json when files exist."""
        # Recover durable results root before loading the manifest (UI reset clears in-memory dirs).
        self._restore_results_root_from_settings()
        data, err = self._load_current_run_manifest()
        if not data:
            return False, err or "No current-run manifest"
        root = self.get_canonical_results_root()
        ok_files, missing = _rl.manifest_paths_exist(data, root)
        sf = data.get("spatial_filter") or {}
        raster = _rl.path_abs_from_root(root, sf.get("raster_output")) if sf else None
        polys = _rl.path_abs_from_root(root, sf.get("polygons_output")) if sf else None
        excl = _rl.path_abs_from_root(root, sf.get("exclude_mask")) if sf else None
        restored = []
        refs = sf.get("input_refs") if isinstance(sf.get("input_refs"), dict) else {}
        # Do not restore a previous AOI's master as the current session master.
        aoi = self.get_user_aoi_layer()
        stored_aoi = refs.get("aoi_identity")
        current_aoi = self._aoi_identity_token(aoi) if aoi else None
        spatial_ok_for_current_aoi = True
        if aoi and aoi.isValid() and aoi.featureCount() > 0 and raster and os.path.isfile(raster):
            spatial_ok_for_current_aoi = self._spatial_raster_belongs_to_current_aoi(
                raster, manifest=data, aoi_layer=aoi
            )
        elif stored_aoi and current_aoi and stored_aoi != current_aoi:
            spatial_ok_for_current_aoi = False
        if not spatial_ok_for_current_aoi:
            self._spatial_stale_after_aoi_change = True
            self.spatial_filter_result_path = None
            self.spatial_filter_polygons_path = None
            self.spatial_filter_exclude_mask_path = None
            QgsMessageLog.logMessage(
                "[WindSuitability] Manifest spatial outputs not restored: AOI mismatch "
                "(stored={0}, current={1}).".format(stored_aoi, current_aoi),
                "WindSuitability",
                Qgis.Warning,
            )
        if spatial_ok_for_current_aoi and raster and os.path.isfile(raster):
            self.spatial_filter_result_path = raster
            restored.append("spatial_filter_result_path")
        if spatial_ok_for_current_aoi and polys and os.path.isfile(polys):
            self.spatial_filter_polygons_path = polys
            restored.append("spatial_filter_polygons_path")
        if spatial_ok_for_current_aoi and excl and os.path.isfile(excl):
            self.spatial_filter_exclude_mask_path = excl
        # Restore analysis master paths from spatial input_refs when present
        for key, attr in (
            ("wind_master", "wind_master_path"),
            ("wind_result", "wind_result_path"),
            ("prospect", "prospect_result_path"),
            ("prospect_raster", "prospect_result_path"),
        ):
            rel_or_abs = refs.get(key)
            if not rel_or_abs:
                continue
            cand = _rl.path_abs_from_root(root, rel_or_abs, confine=False)
            if not cand:
                cand = self._normalize_path(rel_or_abs)
            if cand and os.path.isfile(cand) and not getattr(self, attr, None):
                setattr(self, attr, cand)
                restored.append(attr)
        mca = data.get("mca") or {}
        grid = _rl.path_abs_from_root(root, mca.get("grid_scores")) if mca else None
        smap = _rl.path_abs_from_root(root, mca.get("suitability_map")) if mca else None
        if grid and os.path.isfile(grid):
            self.mca_grid_scores_path = grid
            restored.append("mca_grid_scores_path")
        if smap and os.path.isfile(smap):
            self.mca_suitability_map_path = smap
            restored.append("mca_suitability_map_path")
        if mca.get("run_id"):
            # Point MCA output dir at the durable MCA run folder when present
            if grid:
                self.mca_output_dir = self._normalize_path(os.path.dirname(grid))
        if sf.get("run_id"):
            self._current_spatial_run_id = sf.get("run_id")
        msg = "Restored: {}".format(", ".join(restored) if restored else "(none)")
        if missing:
            msg += "; missing referenced files: {}".format(", ".join(str(m) for m in missing[:5]))
        return True, msg

    def _remove_raster_sidecars(self, path):
        """
        Remove GDAL PAM / overview sidecars that survive .tif overwrite.
        Stale .aux.xml makes QGIS legend min/max disagree with actual pixel values.
        """
        if not path:
            return
        norm = self._normalize_path(path)
        for suffix in (".aux.xml", ".ovr"):
            sidecar = norm + suffix
            if os.path.isfile(sidecar):
                try:
                    os.remove(sidecar)
                except Exception as _be_exc:
                    _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L1421")

    def _release_and_remove_path(self, path):
        """Release QGIS layers using this path and remove file so it can be overwritten. Returns True if safe to write."""
        if not path:
            return True
        norm = self._normalize_path(path)
        if norm.lower().endswith((".tif", ".tiff", ".gtiff", ".geotiff")):
            self._remove_raster_sidecars(norm)
        for layer in list(QgsProject.instance().mapLayers().values()):
            try:
                src = (layer.dataProvider().dataSourceUri() if getattr(layer, "dataProvider", None) else None) or getattr(layer, "source", None) or (layer.source() if hasattr(layer, "source") else None)
                if not src:
                    continue
                src_path = (src.split("|")[0] if "|" in src else src).strip()
                src_norm = self._normalize_path(src_path)
                if src_norm == norm or norm in src_norm or src_norm in norm:
                    QgsProject.instance().removeMapLayer(layer.id())
                    break
            except Exception as _be_exc:
                _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L1441")
        if os.path.exists(norm):
            try:
                os.remove(norm)
                if norm.lower().endswith((".tif", ".tiff", ".gtiff", ".geotiff")):
                    self._remove_raster_sidecars(norm)
                return True
            except Exception:
                return False
        return True

    def _add_fresh_raster_layer_from_disk(self, output_path, output_name):
        """
        Add a raster layer after clip/write: purge stale sidecars, reload provider, refresh map.
        """
        if not output_path or not os.path.exists(output_path):
            return None
        norm = self._normalize_path(output_path)
        self._remove_raster_sidecars(norm)
        self._remove_raster_layers_for_disk_path(norm)
        display_name = self._unique_map_layer_name(output_name)
        clipped_layer = QgsRasterLayer(norm, display_name)
        if not clipped_layer.isValid():
            return None
        try:
            clipped_layer.dataProvider().reloadData()
        except Exception as _be_exc:
            _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L1468")
        QgsProject.instance().addMapLayer(clipped_layer)
        self._refresh_map_after_raster_layer_added(clipped_layer)
        return clipped_layer

    def _remove_raster_layers_for_disk_path(self, path):
        """Remove QgsRasterLayer instances using this file so re-add reads fresh data from disk (avoids stale cache)."""
        if not path:
            return
        try:
            norm = self._normalize_path(path)
            abs_target = os.path.normcase(os.path.abspath(norm.replace("/", os.sep)))
        except Exception:
            try:
                abs_target = os.path.normcase(os.path.abspath(path))
            except Exception:
                return
        for lid in list(QgsProject.instance().mapLayers().keys()):
            lyr = QgsProject.instance().mapLayer(lid)
            if not isinstance(lyr, QgsRasterLayer):
                continue
            try:
                src = lyr.source() or ""
                src_path = (src.split("|")[0]).strip().strip('"')
                abs_src = os.path.normcase(os.path.abspath(self._normalize_path(src_path).replace("/", os.sep)))
                if abs_src == abs_target:
                    QgsProject.instance().removeMapLayer(lid)
            except Exception as _be_exc:
                _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L1496")
                continue
        try:
            QCoreApplication.processEvents()
        except Exception as _be_exc:
            _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L1500")

    def _remove_vector_layers_for_disk_path(self, path):
        """Remove QgsVectorLayer instances whose primary source path matches disk path."""
        if not path:
            return
        try:
            abs_target = os.path.normcase(os.path.abspath(self._normalize_path(path).replace("/", os.sep)))
        except Exception:
            return
        for lid in list(QgsProject.instance().mapLayers().keys()):
            lyr = QgsProject.instance().mapLayer(lid)
            if not isinstance(lyr, QgsVectorLayer):
                continue
            try:
                src = self._layer_source_path(lyr)
                if not src:
                    continue
                abs_src = os.path.normcase(os.path.abspath(src.replace("/", os.sep)))
                if abs_src == abs_target:
                    QgsProject.instance().removeMapLayer(lid)
            except Exception as _be_exc:
                _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L1522")
                continue
        try:
            QCoreApplication.processEvents()
        except Exception as _be_exc:
            _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L1526")

    def _refresh_map_after_raster_layer_added(self, raster_layer):
        try:
            if raster_layer:
                raster_layer.triggerRepaint()
            if getattr(self, "iface", None) and self.iface.mapCanvas():
                self.iface.mapCanvas().refresh()
        except Exception as _be_exc:
            _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L1535")

    def get_plugin_temp_dir(self):
        """Return plugin temp directory for intermediate files; fallback to system temp."""
        if self.temp_dir and os.path.isdir(self.temp_dir):
            return self._normalize_path(self.temp_dir)
        return self._normalize_path(tempfile.gettempdir())

    def get_plugin_results_dir(self):
        """Return plugin results directory for final outputs; fallback to output_dir or temp."""
        if self.results_dir and os.path.isdir(self.results_dir):
            return self._normalize_path(self.results_dir)
        if self.output_dir and os.path.isdir(self.output_dir):
            return self._normalize_path(self.output_dir)
        return self.get_plugin_temp_dir()

    def _output_timestamp(self):
        return time.strftime("%Y%m%d_%H%M%S")

    def _safe_to_float(self, value):
        """Convert QVariant/locale-formatted numeric to float, or None on failure."""
        if value is None:
            return None
        try:
            if isinstance(value, QVariant):
                if value.isNull():
                    return None
                if value.canConvert(QVariant.Double):
                    return float(value.toDouble()[0])
                value = str(value)
            if isinstance(value, str):
                s = value.strip()
                if not s:
                    return None
                s = s.replace(",", ".")
                return float(s)
            return float(value)
        except Exception:
            return None

    def _unique_map_layer_name(self, base_name):
        """Display name for new map layers — avoids TOC clashes (timestamp suffix)."""
        return self.tr("{0} ({1})").format(base_name, self._output_timestamp())

    def _resolve_output_raster_path(self, user_text, default_stem, suffix=".tif"):
        """
        Respect user path from line edit when provided.
        If empty, use results (or temp) with a timestamped default name.
        If user_text is a directory, place default_stem_TIMESTAMP.tif inside it.
        """
        v = (user_text or "").strip()
        self.ensure_output_dirs(self.output_dir or self.get_plugin_temp_dir())
        base_dir = self.get_plugin_results_dir()
        if not v:
            return self._normalize_path(os.path.join(base_dir, f"{default_stem}_{self._output_timestamp()}{suffix}"))
        v = self._normalize_path(v)
        if os.path.isdir(v):
            return self._normalize_path(os.path.join(v, f"{default_stem}_{self._output_timestamp()}{suffix}"))
        d = os.path.dirname(v)
        if d and not os.path.exists(d):
            try:
                os.makedirs(d, exist_ok=True)
            except OSError as _be_exc:
                _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L1598")
        return v

    def _log_plugin_session_reset(self, mca_criteria_count=0):
        """Debug log for session reset (QgsMessageLog + stdout)."""
        lines = [
            "[PLUGIN SESSION RESET]",
            "old project state cleared",
            "AOI=None",
            "wind=None",
            "DEM=None",
            "MCA criteria={}".format(mca_criteria_count),
            "previous outputs removed from memory",
        ]
        msg = "\n".join(lines)
        try:
            QgsMessageLog.logMessage(msg, "WindSuitability", Qgis.Info)
        except Exception as _be_exc:
            _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L1616")
        print(msg)

    def _unset_aoi_map_tools(self):
        """Release rectangle/polygon map tools so a new session does not reuse stale tools."""
        try:
            if self.tool_rectangle and self.canvas.mapTool() == self.tool_rectangle:
                self.canvas.unsetMapTool(self.tool_rectangle)
        except Exception as _be_exc:
            _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L1625")
        try:
            if self.tool_polygon and self.canvas.mapTool() == self.tool_polygon:
                self.canvas.unsetMapTool(self.tool_polygon)
        except Exception as _be_exc:
            _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L1630")
        self.tool_rectangle = None
        self.tool_polygon = None

    def _clear_final_output_layer_markers(self):
        """Remove wind_plugin_final_output markers from project layers (in-memory refs cleared separately)."""
        try:
            for layer in QgsProject.instance().mapLayers().values():
                if isinstance(layer, QgsVectorLayer) and layer.customProperty("wind_plugin_final_output"):
                    layer.removeCustomProperty("wind_plugin_final_output")
        except Exception as _be_exc:
            _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L1641")

    def _reset_spatial_filter_ui(self):
        """Remove all spatial-filter rows from the dialog and leave one empty default row."""
        if not self.dlg:
            return
        for row_info in list(self.spatial_filter_rows):
            try:
                self.remove_excluded_layer_row(row_info)
            except Exception as _be_exc:
                _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L1651")
        for row_info in list(self.preferred_layer_rows):
            try:
                self.remove_preferred_layer_row(row_info)
            except Exception as _be_exc:
                _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L1656")
        self.spatial_filter_rows = []
        self.excluded_layer_rows = []
        self.preferred_layer_rows = []
        if hasattr(self.dlg, "layout_excluded_layers"):
            try:
                self.add_excluded_layer_row()
            except Exception as _be_exc:
                _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L1664")

    def _reset_dialog_ui_to_defaults(self):
        """Reset workflow-specific UI fields; bundled sample paths and layout structure are unchanged."""
        if not self.dlg:
            return
        d = self.dlg
        for name in (
            "lineEditWindPath",
            "lineEditBathymetryPath",
            "lineEditWindAnalysisPath",
            "lineEditDepthAnalysisPath",
            "lineEditProspectPath",
            "lineEdit_wind_input",
            "lineEdit_dem_input",
            "lineEditSlopeDemPath",
        ):
            w = getattr(d, name, None)
            if w is not None:
                w.clear()
        for name in ("txtMinWindSpeed", "txtMaxWindSpeed", "txtMinDepth", "txtMaxDepth"):
            w = getattr(d, name, None)
            if w is not None:
                w.clear()
        combo_aoi = getattr(d, "combo_aoi_source", None)
        if combo_aoi is not None:
            try:
                combo_aoi.blockSignals(True)
                combo_aoi.setCurrentIndex(0)
            finally:
                combo_aoi.blockSignals(False)
            try:
                self._on_aoi_source_changed(0)
            except Exception as _be_exc:
                _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L1698")
        spin_grid = getattr(d, "spin_grid_size", None)
        if spin_grid is not None:
            spin_grid.setValue(int(MCA_RESOLUTION))
        for spin_name, val in (
            ("spinSlopeGood", GOOD_SLOPE_THRESHOLD),
            ("spinSlopeModerate", MODERATE_SLOPE_THRESHOLD),
            ("spinSlopeMax", MAX_SLOPE_THRESHOLD),
        ):
            w = getattr(d, spin_name, None)
            if w is not None:
                w.setValue(float(val))
        combo_grid_method = getattr(d, "combo_grid_value_method", None)
        if combo_grid_method is not None and isinstance(combo_grid_method, QComboBox):
            try:
                combo_grid_method.blockSignals(True)
                combo_grid_method.setCurrentIndex(0)
            finally:
                combo_grid_method.blockSignals(False)
        self.grid_sampling_method = "mean"
        for chk_name in ("chk_export_ranked_grid", "chk_export_ranked_polygons", "chk_export_mca_csv"):
            chk = getattr(d, chk_name, None)
            if chk is not None:
                chk.setChecked(False)
        if hasattr(d, "txt_validation_output"):
            d.txt_validation_output.clear()
        if hasattr(d, "txt_mca_log"):
            d.txt_mca_log.clear()
        lbl_grid = getattr(d, "lbl_grid_info", None)
        if lbl_grid is not None:
            lbl_grid.setText(
                self.tr("Grid info will appear here after generating the grid.")
            )
        if hasattr(d, "tbl_weights"):
            table = d.tbl_weights
            try:
                table.blockSignals(True)
                table.setRowCount(0)
            finally:
                table.blockSignals(False)
        self._reset_spatial_filter_ui()
        self.update_mca_progress(0, 100)

    def reset_plugin_state(self, reset_ui=True, show_user_message=False):
        """
        Central reset: clear all project-specific workflow state for a fresh plugin session.
        Does not reset bundled sample raster paths (germany_wind_path, bathymetry_path) or DEBUG_SPATIAL.
        Does not delete files on disk.
        """
        mca_criteria_before = len(self.decision_making_layers or [])

        self._unset_aoi_map_tools()
        self._remove_user_aoi_layers_from_project()
        self._clear_transient_proximity_state(remove_layers=True)
        self._clear_final_output_layer_markers()
        self.clear_rubber_band()

        self.current_aoi = None
        self.user_aoi_layer = None
        self.user_aoi_layer_id = None
        self.aoi_extent = None
        self.analysis_crs = None
        self.final_aoi_layer = None
        self.prospect_polygon_cache = None
        self.aoi_master_layer = None

        self.wind_result_path = None
        self.wind_master_path = None
        self.depth_result_path = None
