    def get_decision_making_settings(self):
        """Get the current state of Decision Making tab settings"""
        # Note: Checkboxes for apply_on_prospect_only and use_continuous_criteria removed from UI
        # These settings are now always False (default behavior)
        settings = {
            'apply_on_prospect_only': False,
            'use_continuous_criteria': False,
            'criteria': []
        }
        
        # Helper: safely resolve a valid raster layer from project by id/name
        def _resolve_raster(layer_id, layer_name):
            proj = QgsProject.instance()
            lyr = None
            if layer_id:
                lyr = proj.mapLayer(layer_id)
            if (not lyr) and layer_name:
                # exact name match
                for pl in proj.mapLayers().values():
                    if pl.name() == layer_name:
                        lyr = pl
                        break
                # partial name match
                if not lyr:
                    for pl in proj.mapLayers().values():
                        if layer_name.lower() in pl.name().lower():
                            lyr = pl
                            break
            if lyr and isinstance(lyr, QgsRasterLayer) and lyr.isValid():
                return lyr
            return None

        criteria_list = []
        
        if not hasattr(self.dlg, 'tbl_weights'):
            return criteria_list
        
        table = self.dlg.tbl_weights
        
        for row in range(table.rowCount()):
            save_widget = table.cellWidget(row, 0)
            layer_item = table.item(row, 1)
            weight_item = table.item(row, 2)
            role_widget = table.cellWidget(row, 3)
            include_widget = table.cellWidget(row, 4)
            
            if not layer_item:
                continue
            
            layer_name = layer_item.text()
            
            # Extract save status
            save = True
            if save_widget and isinstance(save_widget, QCheckBox):
                save = save_widget.isChecked()
            
            # Extract weight
            weight = 0.0
            if weight_item:
                try:
                    weight = float(weight_item.text())
                except ValueError:
                    weight = 0.0
            
            # Extract role
            role = "Beneficial"
            if role_widget and isinstance(role_widget, QComboBox):
                role = role_widget.currentText()
            
            # Extract include status
            include = True
            if include_widget and isinstance(include_widget, QCheckBox):
                include = include_widget.isChecked()
            
            # Try to resolve layer from stored references first
            layer = None
            if hasattr(self, 'decision_making_layers'):
                for item in self.decision_making_layers:
                    if item.get('row') == row:
                        layer = item.get('layer')
                        break
            
            # If not found in stored references, try to find by name
            if not layer:
                layer = _resolve_raster(None, layer_name)
            
            if layer and layer.isValid():
                criteria_list.append({
                    'layer': layer,
                    'layer_name': layer_name,
                    'weight': weight,
                    'role': role,
                    'include': include,
                    'save': save
                })
        
        settings['criteria'] = criteria_list
        return settings

