    def extract_criteria_data(self):
        """
        Extract all rows from tbl_weights into a structured list of dictionaries.
        Returns list of criteria with layer name, weight, role, include state, and layer info.
        """
        # Helper: safely resolve a valid raster layer from project by id/name
        def _resolve_raster(layer_id, layer_name):
            proj = QgsProject.instance()
            lyr = None
            if layer_id:
                lyr = proj.mapLayer(layer_id)
            if (not lyr) and layer_name:
                # exact name match
                for pl in proj.mapLayers().values():
                    if pl.name() == layer_name:
                        lyr = pl
                        break
                # partial name match
                if not lyr:
                    for pl in proj.mapLayers().values():
                        if layer_name.lower() in pl.name().lower():
                            lyr = pl
                            break
            if lyr and isinstance(lyr, QgsRasterLayer) and lyr.isValid():
                return lyr
            return None

        criteria_list = []
        
        if not hasattr(self.dlg, 'tbl_weights'):
            return criteria_list
        
        table = self.dlg.tbl_weights
        
        for row in range(table.rowCount()):
            save_widget = table.cellWidget(row, 0)
            layer_item = table.item(row, 1)
            weight_item = table.item(row, 2)
            role_widget = table.cellWidget(row, 3)
            include_widget = table.cellWidget(row, 4)
            
            if not layer_item:
                continue
            
            layer_name = layer_item.text()
            
            # Extract save state (include in export when saving results)
            save = True
            if save_widget and isinstance(save_widget, QCheckBox):
                save = save_widget.isChecked()
            
            # Extract weight
            weight = 0.0
            if weight_item:
                try:
                    weight = float(weight_item.text())
                except ValueError:
                    weight = 0.0
            
            # Extract role
            role = "Beneficial"
            if role_widget and isinstance(role_widget, QComboBox):
                role = role_widget.currentText()
            
            # Extract include state
            include = True
            if include_widget and isinstance(include_widget, QCheckBox):
                include = include_widget.isChecked()
            
            # Find the stored layer reference for this table row.
            # Prefer explicit row mapping; fall back to name/id, then positional index.
            layer_obj = None
            layer_path = None
            layer_id = None
            matched_item = None

            for item in (self.decision_making_layers or []):
                if item.get("row") == row:
                    matched_item = item
                    break
            if matched_item is None:
                for item in (self.decision_making_layers or []):
                    if item.get("layer_name") == layer_name:
                        matched_item = item
                        break
            if matched_item is None and 0 <= row < len(self.decision_making_layers or []):
                matched_item = self.decision_making_layers[row]

            if matched_item is not None:
                layer_obj = matched_item.get("layer")
                layer_id = matched_item.get("layer_id")
                layer_path = matched_item.get("layer_path")
                # Keep mapping healthy for subsequent remove/restore operations
                matched_item["row"] = row

            # Prefer a fresh project layer; keep the stored valid raster if project lookup fails
            resolved = _resolve_raster(layer_id, layer_name)
            if resolved is not None:
                layer_obj = resolved
            elif not (
                layer_obj
                and isinstance(layer_obj, QgsRasterLayer)
                and layer_obj.isValid()
            ):
                layer_obj = None

            if layer_obj:
                layer_id = layer_obj.id()
                if hasattr(layer_obj, "source"):
                    layer_path = layer_obj.source()
                elif hasattr(layer_obj, "dataProvider") and hasattr(
                    layer_obj.dataProvider(), "dataSourceUri"
                ):
                    layer_path = layer_obj.dataProvider().dataSourceUri()
                if matched_item is not None:
                    matched_item["layer"] = layer_obj
                    matched_item["layer_id"] = layer_id
                    matched_item["layer_path"] = layer_path

            entry = {
                'layer_name': layer_name,
                'weight': weight,
                'role': role,
                'include': include,
                'save': save,
                'layer': layer_obj,
                'layer_id': layer_id,
                'layer_path': layer_path,
                'row_index': row,
                'source_type': (matched_item or {}).get('source_type') or 'raster',
            }
            if matched_item is not None:
                for key in (
                    "analysis_mode",
                    "geometry_type",
                    "source_vector_path",
                    "source_vector_id",
                    "source_vector_name",
                    "derived_raster_path",
                    "processing_params",
                ):
                    if matched_item.get(key) is not None:
                        entry[key] = matched_item.get(key)
            criteria_list.append(entry)
        
        return criteria_list

    # ============================================================================
    # Decision Making Tab - Phase 2 Methods (Criteria Setup & Validation)
    # ============================================================================


    # ============================================================================
    # Decision Making Tab - Phase 2 Methods (Criteria Setup & Validation)
    # ============================================================================

    def validate_criteria(self, show_messages=True):
        """
        Validate all criteria and display results in txt_validation_output.
        Checks: weight validity, role validity, at least one included, layer existence, raster type, CRS validity.
        """
        if not hasattr(self.dlg, 'tbl_weights'):
            QMessageBox.warning(self.dlg, "Error", "Weights table not found in dialog.")
            return False
        
        if not hasattr(self.dlg, 'txt_validation_output'):
            QMessageBox.warning(self.dlg, "Error", "Validation output text area not found in dialog.")
            return False
        
        # Extract criteria data
        criteria_list = self.extract_criteria_data()
        
        if not criteria_list:
            validation_text = "No criteria found in the table. Please add at least one layer."
            self.dlg.txt_validation_output.setPlainText(validation_text)
            if show_messages:
                QMessageBox.information(
                    self.dlg,
                    "No Criteria",
                    "No criteria found in the table. Please add at least one layer."
                )
            return False
        
        # Initialize validation messages
        validation_messages = []
        validation_errors = []
        validation_warnings = []
        
        # Track if at least one criterion is included
        included_count = 0
        
        # Validate each criterion
        for idx, criterion in enumerate(criteria_list):
            row_num = idx + 1
            layer_name = criterion['layer_name']
            weight = criterion['weight']
            role = criterion['role']
            include = criterion['include']
            layer_obj = criterion['layer']
            
            # Check if included
            if include:
                included_count += 1
            
            # Validate weight
            if not isinstance(weight, (int, float)):
                validation_errors.append(f"Row {row_num} ({layer_name}): Weight is not numeric (value: {weight})")
            elif weight < 0:
                validation_errors.append(f"Row {row_num} ({layer_name}): Weight must be >= 0 (current: {weight})")
            
            # Validate role
            if role not in ["Beneficial", "Penalizing"]:
                validation_errors.append(f"Row {row_num} ({layer_name}): Role must be 'Beneficial' or 'Penalizing' (current: {role})")
            
            # Validate layer existence
            if not layer_obj:
                validation_errors.append(f"Row {row_num} ({layer_name}): Layer not found in project")
            else:
                # Validate layer type (must be raster)
                if not isinstance(layer_obj, QgsRasterLayer):
                    validation_errors.append(f"Row {row_num} ({layer_name}): Layer is not a raster layer (type: {type(layer_obj).__name__})")
                else:
                    # Validate layer validity
                    if not layer_obj.isValid():
                        validation_errors.append(f"Row {row_num} ({layer_name}): Layer is not valid")
                    else:
                        # Validate CRS
                        crs = layer_obj.crs()
                        if not crs.isValid():
                            validation_errors.append(f"Row {row_num} ({layer_name}): Layer has invalid or missing CRS")
                        else:
                            # Success message for valid criterion
                            if include:
                                validation_messages.append(f"Row {row_num} ({layer_name}): ✓ Valid (Weight: {weight:.2f}%, Role: {role}, CRS: {crs.authid()})")
        
        # Check if at least one criterion is included
        if included_count == 0:
            validation_errors.append("No criteria are marked as 'Include=True'. Please include at least one criterion.")
        
        # Prepare validation output text
        output_lines = []
        output_lines.append("=" * 50)
        output_lines.append("CRITERIA VALIDATION RESULTS")
        output_lines.append("=" * 50)
        output_lines.append(f"Total criteria: {len(criteria_list)}")
        output_lines.append(f"Included criteria: {included_count}")
        output_lines.append("")
        
        if validation_errors:
            output_lines.append(f"❌ ERRORS ({len(validation_errors)}):")
            for error in validation_errors:
                output_lines.append(f"  • {error}")
            output_lines.append("")
        
        if validation_warnings:
            output_lines.append(f"⚠️ WARNINGS ({len(validation_warnings)}):")
            for warning in validation_warnings:
                output_lines.append(f"  • {warning}")
            output_lines.append("")
        
        if validation_messages:
            output_lines.append(f"✓ VALID CRITERIA ({len(validation_messages)}):")
            for msg in validation_messages:
                output_lines.append(f"  {msg}")
            output_lines.append("")
        
        # Note: Checkboxes removed from UI, using default values
        apply_on_prospect_only = False
        use_continuous = False
        
        output_lines.append("SETTINGS:")
        output_lines.append(f"  Apply on prospect only: {apply_on_prospect_only}")
        output_lines.append(f"  Use continuous criteria: {use_continuous}")
        
        # Set the validation output
        validation_text = "\n".join(output_lines)
        self.dlg.txt_validation_output.setPlainText(validation_text)
        
        # Show message box with summary (optional)
        if show_messages:
            if validation_errors:
                QMessageBox.warning(
                    self.dlg,
                    "Validation Failed",
                    f"Found {len(validation_errors)} error(s).\nPlease check the validation output for details."
                )
            else:
                QMessageBox.information(
                    self.dlg,
                    "Validation Successful",
                    f"All {len(criteria_list)} criteria validated successfully.\nReady for Phase 3."
                )
        
        # Return True if validation passed, False otherwise
        return len(validation_errors) == 0

    def _serialize_criteria_for_persistence(self):
        """Build a validated criteria payload from the current weights table (no layer objects)."""
        criteria_list = self.extract_criteria_data() if hasattr(self, "extract_criteria_data") else []
        serializable = []
        for criterion in criteria_list or []:
            item = {
                "layer_name": criterion.get("layer_name"),
                "weight": criterion.get("weight"),
                "role": criterion.get("role"),
                "include": criterion.get("include"),
                "save": criterion.get("save", True),
                "layer_id": criterion.get("layer_id"),
                "layer_path": criterion.get("layer_path"),
                "source_type": criterion.get("source_type") or "raster",
            }
            for key in (
                "analysis_mode",
                "geometry_type",
                "source_vector_path",
                "source_vector_id",
                "source_vector_name",
                "derived_raster_path",
                "processing_params",
            ):
                if criterion.get(key) is not None:
                    item[key] = criterion.get(key)
            layer = criterion.get("layer")
            if layer is not None and isinstance(layer, QgsRasterLayer) and self._layer_cpp_alive(layer):
                crs = layer.crs()
                if crs.isValid():
                    item["crs"] = {"authid": crs.authid(), "description": crs.description()}
                src = self._layer_source_path(layer)
                if src and not item.get("layer_path"):
                    item["layer_path"] = src
                if item.get("source_type") == "vector" and src and not item.get("derived_raster_path"):
                    item["derived_raster_path"] = src
            serializable.append(item)
        return _rl.build_criteria_export_payload(serializable)

    def export_criteria_json(self):
        """Export validated criteria data to a JSON file (atomic publish)."""
        if not hasattr(self.dlg, 'tbl_weights'):
            QMessageBox.warning(self.dlg, "Error", "Weights table not found in dialog.")
            return
        
        export_data = self._serialize_criteria_for_persistence()
        if not export_data.get("criteria"):
            QMessageBox.information(self.dlg, "No Data", "No criteria found in the table. Please add criteria first.")
            return

        ok, err, normalized = _rl.validate_criteria_payload(export_data)
        if not ok:
            QMessageBox.warning(self.dlg, "Export Failed", "Current criteria failed validation:\n{}".format(err))
            return
        
        filename, _ = QFileDialog.getSaveFileName(
            self.dlg,
            self.tr("Save Criteria Setup"),
            "",
            "JSON Files (*.json);;All Files (*)"
        )
        
        if not filename:
            return
        
        if not filename.lower().endswith('.json'):
            filename += '.json'

        staging_dir = _rl.create_staging_directory(self.get_canonical_results_root(), kind="criteria")
        staging = os.path.join(staging_dir, "criteria.json")
        try:
            with open(staging, "w", encoding="utf-8") as f:
                json.dump(normalized, f, indent=2, ensure_ascii=False)
            pub_ok, pub_err = _rl.publish_file_atomic(staging, filename)
            if not pub_ok:
                raise RuntimeError(pub_err)
            self._persist_criteria_to_project_settings(normalized)
            QMessageBox.information(
                self.dlg,
                self.tr("Criteria Setup Saved"),
                self.tr("Criteria setup saved to:\n{}\n\nSaved {} criteria.").format(
                    filename, len(normalized["criteria"])
                ),
            )
        except Exception as e:
            QMessageBox.critical(
                self.dlg,
                self.tr("Save Failed"),
                self.tr("Failed to save criteria setup:\n{}").format(e),
            )
        finally:
            _rl.safe_remove_tree(staging_dir, protected_paths=self._protected_manifest_paths())

    def import_criteria_json(self):
        """Load a saved MCA criteria setup from JSON after full validation (no partial overwrite)."""
        if not hasattr(self.dlg, "tbl_weights"):
            QMessageBox.warning(self.dlg, "Error", "Weights table not found in dialog.")
            return
        filename, _ = QFileDialog.getOpenFileName(
            self.dlg,
            self.tr("Load Criteria Setup"),
            "",
            "JSON Files (*.json);;All Files (*)",
        )
        if not filename:
            return
        ok, err, payload = _rl.load_and_validate_criteria_file(filename)
        if not ok:
            QMessageBox.warning(
                self.dlg,
                self.tr("Load Failed"),
                self.tr(
                    "Criteria setup rejected; current configuration left unchanged.\n{}"
                ).format(err),
            )
            return
        applied, apply_err = self._apply_criteria_payload(payload, show_messages=True)
        if not applied:
            QMessageBox.warning(
                self.dlg,
                self.tr("Load Failed"),
                self.tr(
                    "Could not apply criteria setup; current configuration left unchanged.\n{}"
                ).format(apply_err),
            )
            return
        self._persist_criteria_to_project_settings(payload)
        QMessageBox.information(
            self.dlg,
            self.tr("Criteria Setup Loaded"),
            self.tr("Loaded {} criteria from:\n{}").format(len(payload["criteria"]), filename),
        )

    def _project_qsettings_scope(self):
        """Return (scope_key, is_saved_project). Unsaved projects have no durable project scope."""
        try:
            proj_path = QgsProject.instance().fileName() or ""
        except Exception:
            proj_path = ""
        key = _rl.project_settings_key(proj_path) if proj_path else None
        return key, bool(key)

    def _persist_criteria_to_project_settings(self, payload):
        scope, saved = self._project_qsettings_scope()
        if not saved:
            return False
        try:
            # Empty criteria (cleared table) is persistable; non-empty must validate.
            criteria = (payload or {}).get("criteria") if isinstance(payload, dict) else None
            if isinstance(criteria, list) and len(criteria) == 0:
                normalized = {
                    "schema_version": _rl.CRITERIA_SCHEMA_VERSION,
                    "metadata": (payload or {}).get("metadata") or {},
                    "settings": (payload or {}).get("settings") or {},
                    "criteria": [],
                }
            else:
                ok, err, normalized = _rl.validate_criteria_payload(payload)
                if not ok:
                    QgsMessageLog.logMessage(
                        "[WindSuitability] MCA criteria not persisted (invalid): {}".format(err),
                        "WindSuitability",
                        Qgis.Warning,
                    )
                    return False
            settings = QSettings()
            settings.setValue(
                "WinSuitability/mca_criteria/{}".format(scope),
                json.dumps(normalized, ensure_ascii=False),
            )
            return True
        except Exception as e:
            QgsMessageLog.logMessage(
                "[WindSuitability] MCA criteria persistence failed: {}".format(e),
                "WindSuitability",
                Qgis.Warning,
            )
            return False

    def _persist_current_mca_criteria_if_possible(self, reason=""):
        """
        Persist structurally valid criteria after meaningful UI edits.
        Skips when restoring / suppressing signals, or when project is unsaved.
        Does not persist the MCA score matrix.
        """
        if getattr(self, "_suppress_weight_cell_signals", False):
            return False
        if not hasattr(self, "dlg") or self.dlg is None:
            return False
        if not hasattr(self.dlg, "tbl_weights"):
            return False
        scope, saved = self._project_qsettings_scope()
        if not saved:
            return False
        try:
            payload = self._serialize_criteria_for_persistence()
            if not payload.get("criteria"):
                # Empty table is a valid "cleared" configuration — still persist
                payload = _rl.build_criteria_export_payload([])
            ok = self._persist_criteria_to_project_settings(payload)
            if ok and reason:
                QgsMessageLog.logMessage(
                    "[WindSuitability] MCA criteria persisted ({})".format(reason),
                    "WindSuitability",
                    Qgis.Info,
                )
            return ok
        except Exception as e:
            QgsMessageLog.logMessage(
                "[WindSuitability] MCA criteria persist skipped: {}".format(e),
                "WindSuitability",
                Qgis.Warning,
            )
            return False

    def _wire_mca_criteria_persistence_signals(self):
        """Connect dialog-close persistence once (cell/add/remove call persist directly)."""
        if getattr(self, "_mca_persist_signals_wired", False):
            return
        if not self.dlg:
            return
        try:
            # finished(int) fires on accept/reject/close for QDialog
            self.dlg.finished.connect(self._on_mca_dialog_finished_persist)
            self._mca_persist_signals_wired = True
        except Exception as _be_exc:
            _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L15874")

    def _on_mca_dialog_finished_persist(self, _result=0):
        self._persist_current_mca_criteria_if_possible(reason="dialog close")

    def _load_criteria_from_project_settings(self):
        scope, saved = self._project_qsettings_scope()
        if not saved:
            return None, "Project is unsaved; use JSON export/import for criteria persistence."
        try:
            settings = QSettings()
            raw = settings.value("WinSuitability/mca_criteria/{}".format(scope), "")
            if not raw:
                return None, "No saved criteria for this project"
            data = json.loads(raw) if isinstance(raw, str) else raw
            if isinstance(data, dict) and isinstance(data.get("criteria"), list) and len(data.get("criteria")) == 0:
                return {
                    "schema_version": _rl.CRITERIA_SCHEMA_VERSION,
                    "metadata": data.get("metadata") or {},
                    "settings": data.get("settings") or {},
                    "criteria": [],
                }, ""
            ok, err, payload = _rl.validate_criteria_payload(data)
            if not ok:
                return None, err
            return payload, ""
        except Exception as e:
            return None, str(e)

    def _apply_criteria_payload(self, payload, show_messages=False, _rollback=False):
        """
        Replace weights table from a validated payload.
        Does not partially mutate on failure. Restores the prior criteria snapshot on error.
        """
        if not hasattr(self.dlg, "tbl_weights"):
            return False, "Weights table missing"
        ok, err, normalized = _rl.validate_criteria_payload(payload)
        if not ok:
            return False, err

        table = self.dlg.tbl_weights
        previous_snapshot = None
        if not _rollback:
            try:
                previous_snapshot = self._serialize_criteria_for_persistence()
            except Exception:
                previous_snapshot = None
        try:
            self._suppress_weight_cell_signals = True
            # Clear table completely first
            table.setRowCount(0)
            self.decision_making_layers = []
            warnings = []
            for item in normalized["criteria"]:
                item = dict(item)
                layer_path = item.get("derived_raster_path") or item.get("layer_path")
                layer = None
                if item.get("source_type") == "vector":
                    # Prefer existing derived raster; never invent a substitute raster.
                    derived = item.get("derived_raster_path") or item.get("layer_path")
                    src_vec = item.get("source_vector_path")
                    if derived and os.path.isfile(derived):
                        layer_path = derived
                    elif src_vec and os.path.isfile(str(src_vec).split("|")[0].strip().strip('"')):
                        # Re-run historical Binary/Proximity conversion from the source vector.
                        regenerated, regen_err = self._regenerate_vector_criterion_raster(item)
                        if regenerated:
                            layer_path = regenerated
                            item["derived_raster_path"] = regenerated
                            item["layer_path"] = regenerated
                        else:
                            warnings.append(
                                "Vector criterion '{}': derived raster missing and could not be regenerated ({}). "
                                "Source: {}".format(item.get("layer_name"), regen_err or "unknown error", src_vec)
                            )
                            layer_path = None
                    else:
                        warnings.append(
                            "Vector criterion '{}': missing derived raster and source vector path; "
                            "not restored as a scoring layer.".format(item.get("layer_name"))
                        )
                        layer_path = None
                if layer_path and os.path.isfile(layer_path):
                    layer = QgsRasterLayer(layer_path, item.get("layer_name") or "criterion", "gdal")
                    if not layer.isValid():
                        layer = None
                        warnings.append("Could not open layer for '{}': {}".format(item.get("layer_name"), layer_path))
                    else:
                        # Register in the project so MCA can resolve layers by id/name
                        try:
                            QgsProject.instance().addMapLayer(layer, False)
                        except Exception as _be_exc:
                            _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L15966")
                        item["layer_id"] = layer.id()
                        item["layer_path"] = layer_path
                elif layer_path:
                    warnings.append("Missing layer file for '{}': {}".format(item.get("layer_name"), layer_path))
                # Reuse existing add-row helpers when possible via decision_making_layers + table API
                self._append_weights_table_row_from_criterion(item, layer)
            self._reindex_decision_making_layers()
            self._suppress_weight_cell_signals = False
            if show_messages and warnings:
                try:
                    self.iface.messageBar().pushWarning(
                        "Wind Site Select",
                        "Criteria imported with {} layer warning(s). Check the log.".format(len(warnings)),
                    )
                except Exception as _be_exc:
                    _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L15982")
                for w in warnings:
                    self.log_mca_message("  " + w)
            return True, ""
        except Exception as e:
            self._suppress_weight_cell_signals = False
            # Restore prior criteria so failed import/restore does not wipe the table
            if not _rollback and previous_snapshot and previous_snapshot.get("criteria"):
                restored, _restore_err = self._apply_criteria_payload(
                    previous_snapshot, show_messages=False, _rollback=True
                )
                if not restored:
                    try:
                        table.setRowCount(0)
                        self.decision_making_layers = []
                    except Exception as _be_exc:
                        _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L15998")
            else:
                try:
                    table.setRowCount(0)
                    self.decision_making_layers = []
                except Exception as _be_exc:
                    _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L16004")
            return False, str(e)

    def _reindex_decision_making_layers(self):
        """
        Keep decision_making_layers[].row aligned with tbl_weights row indices.
        Matches interactive Add Layer semantics used by remove/extract helpers.
        """
        if not hasattr(self, "decision_making_layers") or self.decision_making_layers is None:
            self.decision_making_layers = []
        table = getattr(getattr(self, "dlg", None), "tbl_weights", None)
        if table is None:
            return
        entries = list(self.decision_making_layers)
        rebuilt = []
        used = set()
        for row in range(table.rowCount()):
            name_item = table.item(row, 1)
            name = name_item.text() if name_item else None
            match_idx = None
            if name:
                for i, ent in enumerate(entries):
                    if i in used:
                        continue
                    if ent.get("layer_name") == name:
                        match_idx = i
                        break
            if match_idx is None:
                for i, ent in enumerate(entries):
                    if i in used:
                        continue
                    if ent.get("row") == row:
                        match_idx = i
                        break
            if match_idx is None:
                for i, ent in enumerate(entries):
                    if i not in used:
                        match_idx = i
                        break
            if match_idx is None:
                continue
            used.add(match_idx)
            ent = entries[match_idx]
            ent["row"] = row
            if name:
                ent["layer_name"] = name
            rebuilt.append(ent)
        self.decision_making_layers = rebuilt

    def _append_weights_table_row_from_criterion(self, item, layer):
        """Insert one weights-table row from a validated criterion dict.
        Columns: Save?, Layer, Weight (%), Role, Include.

        Stores the same row-mapping contract as interactive Add Layer:
        decision_making_layers entries include {'layer', 'row', ...}.
        """
        table = self.dlg.tbl_weights
        row = table.rowCount()
        table.insertRow(row)

        save_cb = QCheckBox()
        save_cb.setChecked(bool(item.get("save", True)))
        table.setCellWidget(row, 0, save_cb)

        name_item = QTableWidgetItem(str(item.get("layer_name") or ""))
        table.setItem(row, 1, name_item)

        weight_item = QTableWidgetItem(str(item.get("weight", 0)))
        table.setItem(row, 2, weight_item)

        role_combo = QComboBox()
        role_combo.addItems(["Beneficial", "Penalizing"])
        role = str(item.get("role") or "Beneficial")
        role_l = role.lower()
        role_combo.setCurrentIndex(0 if role_l.startswith("b") or "benefit" in role_l else 1)
        table.setCellWidget(row, 3, role_combo)

        include_cb = QCheckBox()
        include_cb.setChecked(bool(item.get("include", True)))
        table.setCellWidget(row, 4, include_cb)

        layer_id = item.get("layer_id")
        layer_path = item.get("layer_path")
        if layer is not None and getattr(layer, "isValid", lambda: False)():
            try:
                layer_id = layer.id()
            except Exception as _be_exc:
                _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L16091")
            try:
                layer_path = layer.source() if hasattr(layer, "source") else layer_path
            except Exception as _be_exc:
                _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L16095")

        entry = {
            "layer_name": item.get("layer_name"),
            "weight": float(item.get("weight", 0)),
            "role": role,
            "include": bool(item.get("include", True)),
            "save": bool(item.get("save", True)),
            "layer_id": layer_id,
            "layer_path": layer_path,
            "layer": layer,
            "row": row,
            "source_type": item.get("source_type") or "raster",
        }
        for key in (
            "analysis_mode",
            "geometry_type",
            "source_vector_path",
            "source_vector_id",
            "source_vector_name",
            "derived_raster_path",
            "processing_params",
        ):
            if item.get(key) is not None:
                entry[key] = item.get(key)
        self.decision_making_layers.append(entry)
        self._reindex_decision_making_layers()

    def _update_manifest_after_successful_mca(self):
        root = self.get_canonical_results_root()
        existing, _ = self._load_current_run_manifest()
        spatial_run_id = None
        if existing and existing.get("spatial_filter"):
            spatial_run_id = (existing.get("spatial_filter") or {}).get("run_id")
        spatial_run_id = spatial_run_id or self._current_spatial_run_id
        mca_run_id = self._current_mca_run_id or (self._active_run_dirs or {}).get("run_id") or _rl.new_run_id("mca")
        grid = self._mca_grid_scores_disk_path()
        smap = self._mca_suitability_map_disk_path()
        section = _rl.build_mca_section(
            root,
            mca_run_id,
            spatial_run_id,
            grid_scores=grid if grid and os.path.isfile(grid) else None,
            suitability_map=smap if smap and os.path.isfile(smap) else None,
        )
        new_manifest = _rl.update_manifest_after_mca(existing, section)
        ok, err = self._save_current_run_manifest(new_manifest)
        if not ok:
            raise RuntimeError(err or "manifest save failed")
        self._current_mca_run_id = mca_run_id

    def start_new_mca_analysis(self):
        """Explicit user action: clear MCA criteria/results session (disk files kept)."""
        yes = QMessageBox.StandardButton.Yes if hasattr(QMessageBox, "StandardButton") else QMessageBox.Yes
        no = QMessageBox.StandardButton.No if hasattr(QMessageBox, "StandardButton") else QMessageBox.No
        reply = QMessageBox.question(
            self.dlg,
            self.tr("New MCA Analysis"),
            self.tr(
                "Clear the current MCA criteria configuration and in-memory scores?\n\n"
                "This cannot be undone unless you previously used Save Criteria Setup.\n"
                "Files already saved on disk will not be deleted."
            ),
            yes | no,
            no,
        )
        if reply != yes:
            # Cancel: leave table, decision_making_layers, and persistence unchanged
            return False
        self.decision_making_layers = []
        self.mca_data_matrix = []
        self.mca_grid_layer = None
        self.mca_grid_layer_id = None
        self.mca_suitability_map_layer = None
        self.mca_suitability_map_layer_id = None
        if hasattr(self.dlg, "tbl_weights"):
            self._suppress_weight_cell_signals = True
            self.dlg.tbl_weights.setRowCount(0)
            self._suppress_weight_cell_signals = False
        self._persist_current_mca_criteria_if_possible(reason="new MCA analysis")
        try:
            self.iface.messageBar().pushMessage(
                "Wind Site Select",
                self.tr(
                    "MCA criteria cleared. Use Load Criteria Setup or add criteria to start a new analysis."
                ),
                level=Qgis.Info,
                duration=5,
            )
        except Exception as _be_exc:
            _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L16185")
        return True

    def remove_layer_from_weights_table(self):
        """Remove selected row(s) from the weights table"""
        if not hasattr(self.dlg, 'tbl_weights'):
            QMessageBox.warning(self.dlg, "Error", "Weights table not found in dialog.")
            return
        
        table = self.dlg.tbl_weights
        selected_rows = table.selectionModel().selectedRows()
        
        if not selected_rows:
            QMessageBox.information(self.dlg, "No Selection", 
                                  "Please select one or more rows to remove.")
            return
        
        # Get row indices (in reverse order to avoid index shifting issues)
        row_indices = sorted([index.row() for index in selected_rows], reverse=True)
        
        # Confirm removal
        yes = QMessageBox.StandardButton.Yes if hasattr(QMessageBox, "StandardButton") else QMessageBox.Yes
        no = QMessageBox.StandardButton.No if hasattr(QMessageBox, "StandardButton") else QMessageBox.No
        if len(row_indices) == 1:
            layer_name = table.item(row_indices[0], 1).text() if table.item(row_indices[0], 1) else "selected layer"
            reply = QMessageBox.question(
                self.dlg,
                "Confirm Removal",
                f"Remove '{layer_name}' from the weights table?",
                yes | no,
                no
            )
        else:
            reply = QMessageBox.question(
                self.dlg,
                "Confirm Removal",
                f"Remove {len(row_indices)} selected layers from the weights table?",
                yes | no,
                no
            )
        
        if reply == yes:
            # Remove rows
            for row in row_indices:
                table.removeRow(row)
                # Update stored layer references (tolerate missing row keys from older sessions)
                self.decision_making_layers = [
                    item for item in self.decision_making_layers 
                    if item.get('row') != row
                ]
            # Rebuild row indices from the live table so restore/import/add stay consistent
            self._reindex_decision_making_layers()
            
            QMessageBox.information(self.dlg, "Removed", 
                                  f"Removed {len(row_indices)} layer(s) from the table.")
            self._persist_current_mca_criteria_if_possible(reason="remove criteria layer")

    def validate_weight_cell(self, row, column):
        """Validate weight input when a cell is changed (only for Weight column)"""
        if getattr(self, "_suppress_weight_cell_signals", False):
            return
        if not hasattr(self.dlg, 'tbl_weights'):
            return
        
        # Only validate the Weight column (column 2)
        if column != 2:
            return
        
        table = self.dlg.tbl_weights
        item = table.item(row, column)
        
        if not item:
            return
        
        weight_text = item.text().strip()
        
        # Try to convert to float
        try:
            weight_value = float(weight_text)
            
            # Check if >= 0
            if weight_value < 0:
                QMessageBox.warning(
                    self.dlg,
                    "Invalid Weight",
                    f"Weight must be a number >= 0.\n"
                    f"Current value: {weight_text}\n"
                    f"Please enter a valid weight."
                )
                # Reset to 0
                item.setText("0")
                return
            
            # If valid, format to 2 decimal places
            item.setText(f"{weight_value:.2f}")
            self._persist_current_mca_criteria_if_possible(reason="weight cell edit")
            
        except ValueError:
            # Not a valid number — keep previous persisted config; reset UI cell only
            QMessageBox.warning(
                self.dlg,
                "Invalid Weight",
                f"Weight must be a numeric value.\n"
                f"Current value: '{weight_text}'\n"
                f"Please enter a valid number."
            )
            # Reset to 0
            item.setText("0")

    # ============================================================================
    # Decision Making Tab - Phase 2 Methods (Criteria Setup & Validation)
    # ============================================================================

    def validate_criteria(self, show_messages=True):
        """
        Validate all criteria and display results in txt_validation_output.
        Checks: weight validity, role validity, at least one included, layer existence, raster type, CRS validity.
        """
        if not hasattr(self.dlg, 'tbl_weights'):
            QMessageBox.warning(self.dlg, "Error", "Weights table not found in dialog.")
            return False
        
        if not hasattr(self.dlg, 'txt_validation_output'):
            QMessageBox.warning(self.dlg, "Error", "Validation output text area not found in dialog.")
            return False
        
        # Extract criteria data
        criteria_list = self.extract_criteria_data()
        
        if not criteria_list:
            validation_text = "No criteria found in the table. Please add at least one layer."
            self.dlg.txt_validation_output.setPlainText(validation_text)
            if show_messages:
                QMessageBox.information(
                    self.dlg,
                    "No Criteria",
                    "No criteria found in the table. Please add at least one layer."
                )
            return False
        
        # Initialize validation messages
        validation_messages = []
        validation_errors = []
        validation_warnings = []
        
        # Track if at least one criterion is included
        included_count = 0
        
        # Validate each criterion
        for idx, criterion in enumerate(criteria_list):
            row_num = idx + 1
            layer_name = criterion['layer_name']
            weight = criterion['weight']
            role = criterion['role']
            include = criterion['include']
            layer_obj = criterion['layer']
            
            # Check if included
            if include:
                included_count += 1
            
            # Validate weight
            if not isinstance(weight, (int, float)):
                validation_errors.append(f"Row {row_num} ({layer_name}): Weight is not numeric (value: {weight})")
            elif weight < 0:
                validation_errors.append(f"Row {row_num} ({layer_name}): Weight must be >= 0 (current: {weight})")
            
            # Validate role
            if role not in ["Beneficial", "Penalizing"]:
                validation_errors.append(f"Row {row_num} ({layer_name}): Role must be 'Beneficial' or 'Penalizing' (current: {role})")
            
            # Validate layer existence
            if not layer_obj:
                validation_errors.append(f"Row {row_num} ({layer_name}): Layer not found in project")
            else:
                # Validate layer type (must be raster)
                if not isinstance(layer_obj, QgsRasterLayer):
                    validation_errors.append(f"Row {row_num} ({layer_name}): Layer is not a raster layer (type: {type(layer_obj).__name__})")
                else:
                    # Validate layer validity
                    if not layer_obj.isValid():
                        validation_errors.append(f"Row {row_num} ({layer_name}): Layer is not valid")
                    else:
                        # Validate CRS
                        crs = layer_obj.crs()
                        if not crs.isValid():
                            validation_errors.append(f"Row {row_num} ({layer_name}): Layer has invalid or missing CRS")
                        else:
                            # Success message for valid criterion
                            if include:
                                validation_messages.append(f"Row {row_num} ({layer_name}): ✓ Valid (Weight: {weight:.2f}%, Role: {role}, CRS: {crs.authid()})")
        
        # Check if at least one criterion is included
        if included_count == 0:
            validation_errors.append("At least one criterion must be included (Include checkbox checked)")
        
        # Build final validation output
        output_lines = []
        
        if validation_errors:
            output_lines.append("=== VALIDATION ERRORS ===")
            output_lines.append("")
            for error in validation_errors:
                output_lines.append(f"❌ {error}")
            output_lines.append("")
        
        if validation_warnings:
            output_lines.append("=== VALIDATION WARNINGS ===")
            output_lines.append("")
            for warning in validation_warnings:
                output_lines.append(f"⚠️ {warning}")
            output_lines.append("")
        
        if validation_messages:
            output_lines.append("=== VALIDATION RESULTS ===")
            output_lines.append("")
            for msg in validation_messages:
                output_lines.append(msg)
            output_lines.append("")
        
        # Final summary
        if validation_errors:
            output_lines.append("❌ Validation FAILED. Please fix the errors above before proceeding.")
        else:
            output_lines.append("✅ Criteria validated successfully. Ready for Phase 3.")
            output_lines.append("")
            output_lines.append(f"Summary:")
            output_lines.append(f"  - Total criteria: {len(criteria_list)}")
            output_lines.append(f"  - Included criteria: {included_count}")
            output_lines.append(f"  - Excluded criteria: {len(criteria_list) - included_count}")
            
            # Get checkbox states
            # Note: Checkboxes removed from UI, using default values
            apply_on_prospect = False
            use_continuous = False
            
            output_lines.append(f"  - Apply on prospect only: {apply_on_prospect}")
            output_lines.append(f"  - Use continuous criteria: {use_continuous}")
        
        # Set the validation output
        validation_text = "\n".join(output_lines)
        self.dlg.txt_validation_output.setPlainText(validation_text)
        
        # Show message box with summary (optional)
        if show_messages:
            if validation_errors:
                QMessageBox.warning(
                    self.dlg,
                    "Validation Failed",
                    f"Found {len(validation_errors)} error(s).\nPlease check the validation output for details."
                )
            else:
                QMessageBox.information(
                    self.dlg,
                    "Validation Successful",
                    f"All {len(criteria_list)} criteria validated successfully.\nReady for Phase 3."
                )

        # Return True if validation passed, False otherwise
        return len(validation_errors) == 0

    # ============================================================================
    # Decision Making Tab - Phase 3 Methods (Raster Scoring & Normalization)
    # ============================================================================

    def on_tab_changed(self, index):
        """
        Handle tab change event.
        
        Behaviours:
        - Automatically validate criteria when entering relevant tabs
        - Populate scoring layers list when Raster Scoring tab is opened
        """
        try:
            # UI file uses tabWidget_EXC, try both names for compatibility
            tab_widget = getattr(self.dlg, 'tabWidget_EXC', None) or getattr(self.dlg, 'tabWidget', None)
            if not tab_widget:
                return
            current_widget = tab_widget.widget(index)
            if not current_widget:
                return
            
            tab_text = tab_widget.tabText(index).strip().lower()
            
            # Auto-validate criteria when entering Criteria Setup or MCA Evaluation
            if tab_text in ["criteria setup", "mca evaluation"]:
                # Run validation silently (no popups), but update txt_validation_output
                self.validate_criteria(show_messages=False)
            
            # Reset MCA progress bar to 0 when MCA Evaluation tab is opened (before running analysis)
            if tab_text == "mca evaluation" and hasattr(self.dlg, 'progress_mca'):
                self.update_mca_progress(0, 100)
                print("MCA progress bar reset to 0%")

            # Phase 2: When opening Decision Making tab, pre-fill slope DEM path from workflow if available
            if tab_text == "decision making" and hasattr(self.dlg, 'lineEditSlopeDemPath'):
                if self.clipped_dem_path and os.path.exists(self.clipped_dem_path):
                    if not (self.dlg.lineEditSlopeDemPath.text() or "").strip():
                        self.dlg.lineEditSlopeDemPath.setText(self.clipped_dem_path)
                        print(f"  [Slope] Pre-filled DEM from workflow (clipped): {self.clipped_dem_path}")
        
        except Exception as e:
            # Fail silently to avoid breaking tab switching
            print(f"Error in on_tab_changed: {e}")

    # ============================================================================
    # Decision Making Tab - Phase 4 Methods (Grid-based MCA Evaluation)
    # ============================================================================

    def get_final_polygon_layer(self):
        """
        Find the most recently generated final polygon layer by checking for
        the custom property 'wind_plugin_final_output = True'.
        
        This function searches all vector layers in the project and returns
        the one marked as the final output from exclusion/inclusion processing.
        
        Returns:
            QgsVectorLayer or None: The final polygon layer, or None if not found
        """
        final_layers = []
        
        # Search all layers in the project
        for layer_id, layer in QgsProject.instance().mapLayers().items():
            if isinstance(layer, QgsVectorLayer):
                # Check if it's a polygon layer
                if layer.geometryType() == QgsWkbTypes.PolygonGeometry:
                    # Check for the custom property
                    custom_prop = layer.customProperty('wind_plugin_final_output')
                    if custom_prop is True or custom_prop == 'True' or custom_prop == 'true':
                        final_layers.append(layer)
        
        if not final_layers:
            return None
        
        # If multiple layers found, prefer the most recently added one
        # (QGIS typically adds layers in order, so the last one is most recent)
        # We can also check modification time if available
        if len(final_layers) == 1:
            return final_layers[0]
        
        # Return the last one (most recently added)
        # In the future, we could sort by timestamp if we add that property
        return final_layers[-1]
    
    def mark_layer_as_final_output(self, layer):
        """
        Mark a layer as the final output by setting the custom property.
        This also removes the marker from any previously marked layers.
        
        Args:
            layer: QgsVectorLayer to mark as final output
        """
        if not layer or not isinstance(layer, QgsVectorLayer):
            return
        
        # Remove marker from all other layers first
        for layer_id, other_layer in QgsProject.instance().mapLayers().items():
            if isinstance(other_layer, QgsVectorLayer) and other_layer != layer:
                if other_layer.customProperty('wind_plugin_final_output'):
                    other_layer.removeCustomProperty('wind_plugin_final_output')
        
        # Mark this layer as final output
        layer.setCustomProperty('wind_plugin_final_output', True)
        
        # Also store in instance variable for quick access
        self.final_aoi_layer = layer
        self.prospect_polygon_cache = None
        
        # Log message if log_mca_message method exists (Phase 4)
        if hasattr(self, 'log_mca_message'):
            self.log_mca_message(f"Marked layer '{layer.name()}' as final output polygon for MCA operations.")
        else:
            print(f"Marked layer '{layer.name()}' as final output polygon for MCA operations.")

    def get_prospect_polygon_layer(self):
        """
        Get the final prospect polygon layer from previous analysis steps (exclusion / pipeline result).
        User-drawn AOI is separate: use get_user_aoi_layer() or self.current_aoi.
        
        Priority order:
        1. Layer marked with wind_plugin_final_output=True (most recent final output)
        2. self.final_aoi_layer (if set and valid; MCA / validated final polygon)
        3. Common layer names (e.g., "Prospect Without Protected Areas", "Prospect Minus All Exclusions")
        4. prospect_area.gpkg next to prospect_result_path if available
        
        This layer represents the prospect polygon that will be
        divided into grid cells for MCA analysis.
        
        Returns:
            QgsVectorLayer or None: The prospect polygon layer, or None if not found
        """
        # Priority 1: Get layer marked as final output (most recent)
        final_layer = self.get_final_polygon_layer()
        if final_layer and final_layer.isValid():
            self.log_mca_message(f"Using final output layer: '{final_layer.name()}'")
            self.final_aoi_layer = final_layer
            return final_layer
        
        # Priority 2: Use final_aoi_layer if available and valid
        if self.final_aoi_layer and isinstance(self.final_aoi_layer, QgsVectorLayer):
            if self.final_aoi_layer.isValid():
                # Safety check: Verify layer still exists in project
                layer_id = self.final_aoi_layer.id()
                if QgsProject.instance().mapLayer(layer_id):
                    self.log_mca_message(f"Using stored final AOI layer: '{self.final_aoi_layer.name()}'")
                    return self.final_aoi_layer
                else:
                    # Layer was removed from project, try to reload by name
                    self.log_mca_message("Final AOI layer removed from project, attempting to reload...")
                    layers_by_name = QgsProject.instance().mapLayersByName("Final AOI (Validated)")
                    if layers_by_name:
                        self.final_aoi_layer = layers_by_name[0]
                        return self.final_aoi_layer
        
        # Priority 2: Try to find prospect polygon layer in the project
        project_layers = QgsProject.instance().mapLayers().values()
        
        # Look for common prospect layer names (including "Prospect Minus" pattern for exclusion results)
        prospect_names = [
            "Prospect Minus",  # Highest priority - this is the pattern for final exclusion results
            "Prospect Without Protected Areas",
            "prospect_without_protected_areas",
            "Prospect Area",
            "prospect_area",
            "Final Suitable Areas",
            "final_suitable_areas",
            "Prospect Minus All Exclusions"
        ]
        
        # First, look for layers containing "Prospect Minus" (most likely to be final exclusion result)
        for layer in project_layers:
            if isinstance(layer, QgsVectorLayer) and layer.geometryType() == QgsWkbTypes.PolygonGeometry:
                layer_name = layer.name()
                # Prioritize "Prospect Minus" pattern but exclude intermediate layers
                if "Prospect Minus" in layer_name and "Final AOI" not in layer_name and "Validated" not in layer_name:
                    if layer.featureCount() > 0:  # Ensure it has features
                        self.prospect_polygon_cache = layer
                        self.log_mca_message(f"Found final exclusion result layer: '{layer_name}'")
                        return layer
        
        # Then look for other common prospect layer names
        for layer in project_layers:
            if isinstance(layer, QgsVectorLayer) and layer.geometryType() == QgsWkbTypes.PolygonGeometry:
                layer_name = layer.name()
                # Skip intermediate processing layers
                if "Final AOI" in layer_name or "Validated" in layer_name or "intermediate" in layer_name.lower():
                    continue
                if any(name.lower() in layer_name.lower() for name in prospect_names):
                    if layer.featureCount() > 0:  # Ensure it has features
                        self.prospect_polygon_cache = layer
                        return layer
        
        # Priority 3: Load prospect polygon from results (prospect_area.gpkg); prospect_result_path is the raster (prospect_area.tif)
        if self.prospect_result_path and os.path.exists(self.prospect_result_path):
            prospect_dir = os.path.dirname(self.prospect_result_path)
            polygon_path = os.path.join(prospect_dir, self.PROSPECT_AREA_GPKG)
            if os.path.exists(polygon_path):
                layer = QgsVectorLayer(polygon_path, "Prospect Area", "ogr")
                if layer.isValid():
                    self.prospect_polygon_cache = layer
                    return layer
        
        return None

    def log_mca_message(self, message):
        """Add a message to the MCA log text area"""
        if not hasattr(self.dlg, 'txt_mca_log'):
            return
        
        current_text = self.dlg.txt_mca_log.toPlainText()
        new_text = f"{current_text}\n{message}" if current_text else message
        self.dlg.txt_mca_log.setPlainText(new_text)
        
        # Auto-scroll to bottom
        cursor = self.dlg.txt_mca_log.textCursor()
        cursor.movePosition(cursor.MoveOperation.End)
        self.dlg.txt_mca_log.setTextCursor(cursor)

    def update_mca_progress(self, value, maximum=100):
        """Update the MCA progress bar"""
        if hasattr(self.dlg, 'progress_mca'):
            self.dlg.progress_mca.setMaximum(maximum)
            self.dlg.progress_mca.setValue(value)
            QCoreApplication.processEvents()  # Update UI

    def get_mca_output_directory(self):
        """
        Durable MCA output directory under the canonical results root:
          results/runs/<run_id>/mca/

        Prefers the current spatial run's mca/ folder so MCA stays linked to the
        spatial analysis that produced the mask. Does not create home UUID folders.
        """
        if self.mca_output_dir and os.path.isdir(self.mca_output_dir):
            return self._normalize_path(self.mca_output_dir)
        root = self.get_canonical_results_root()
        # Reuse MCA dir from current manifest when present
        try:
            data, _ = self._load_current_run_manifest()
            if data:
                mca = data.get("mca") or {}
                grid = _rl.path_abs_from_root(root, mca.get("grid_scores"))
                if grid and os.path.isdir(os.path.dirname(grid)):
                    self.mca_output_dir = self._normalize_path(os.path.dirname(grid))
                    return self.mca_output_dir
                sf = data.get("spatial_filter") or {}
                spatial_run = sf.get("run_id")
                if spatial_run:
                    mca_dir = self._normalize_path(
                        os.path.join(root, _rl.RUNS_SUBDIR, spatial_run, _rl.MCA_SUBDIR)
                    )
                    os.makedirs(mca_dir, exist_ok=True)
                    self.mca_output_dir = mca_dir
                    self._current_mca_run_id = spatial_run
                    self._current_spatial_run_id = spatial_run
                    self.log_mca_message("MCA output directory (linked to spatial run): {}".format(mca_dir))
                    return self.mca_output_dir
        except Exception as _be_exc:
            _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L16704")
        if self._current_spatial_run_id:
            mca_dir = self._normalize_path(
                os.path.join(root, _rl.RUNS_SUBDIR, self._current_spatial_run_id, _rl.MCA_SUBDIR)
            )
            os.makedirs(mca_dir, exist_ok=True)
            self.mca_output_dir = mca_dir
            self._current_mca_run_id = self._current_spatial_run_id
            return self.mca_output_dir
        dirs = self._begin_run_directories("mca")
        self.mca_output_dir = dirs["mca_dir"]
        self._current_mca_run_id = dirs["run_id"]
        self.log_mca_message("MCA output directory: {}".format(self.mca_output_dir))
        return self.mca_output_dir

    def save_and_reload_layer(self, layer, layer_name, output_filename=None, hide_from_toc=False):
        """
        Save a layer to disk and reload it as a new QgsVectorLayer.

        Phase 1.4.3: write to a unique staging GPKG, validate, then publish via
        atomic replace. Never deletes the previous valid GPKG before success.
        """
        if not self._layer_cpp_alive(layer):
            self.log_mca_message(f"  ERROR: Invalid layer provided for save/reload")
            return None
        
        try:
            output_dir = self.get_mca_output_directory()
            if not output_filename:
                output_filename = f"{layer_name.lower().replace(' ', '_')}_{uuid.uuid4().hex[:8]}.gpkg"
            output_path = self._normalize_path(os.path.join(output_dir, output_filename))

            staging_dir = _rl.create_staging_directory(self.get_canonical_results_root(), kind="gpkg")
            staging_path = self._normalize_path(
                os.path.join(staging_dir, "{}_{}".format(uuid.uuid4().hex[:8], os.path.basename(output_path)))
            )

            result = processing.run("native:savefeatures", {
                'INPUT': layer,
                'OUTPUT': staging_path
            })

            staged = None
            if isinstance(result, dict) and result.get('OUTPUT'):
                staged = self._normalize_path(str(result['OUTPUT']))
            if not staged or not os.path.exists(staged):
                staged = staging_path if os.path.exists(staging_path) else None
            if not staged:
                self.log_mca_message(f"  ERROR: Failed to stage layer to {staging_path}")
                _rl.safe_remove_tree(staging_dir, protected_paths=self._protected_manifest_paths())
                return None

            ok, err = self._publish_gpkg_to_path(staged, output_path, min_features=0)
            if not ok:
                self.log_mca_message(
                    "  ERROR: GPKG publication failed (previous file left unchanged): {}".format(err)
                )
                _rl.safe_remove_tree(staging_dir, protected_paths=self._protected_manifest_paths())
                return None

            try:
                _rl.safe_remove_tree(staging_dir, protected_paths=self._protected_manifest_paths())
            except Exception as _be_exc:
                _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L16767")

            # After successful publish, refresh path-matched project layers (not before).
            try:
                for existing_layer in list(QgsProject.instance().mapLayers().values()):
                    if not isinstance(existing_layer, QgsVectorLayer):
                        continue
                    src = self._layer_source_path(existing_layer)
                    if src and os.path.normpath(src) == os.path.normpath(output_path):
                        QgsProject.instance().removeMapLayer(existing_layer.id())
            except Exception as _be_exc:
                _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L16778")

            display_name = layer_name
            if not hide_from_toc and layer_name in (
                MCA_GRID_SCORE_MAP_LAYER_NAME,
                MCA_SUITABILITY_MAP_LAYER_NAME,
                MCA_CLIPPED_EXPORT_LAYER_NAME,
            ):
                display_name = self._unique_map_layer_name(layer_name)

            reloaded_layer = QgsVectorLayer(output_path, display_name, "ogr")
            if not reloaded_layer.isValid():
                self.log_mca_message(f"  ERROR: Failed to reload layer from {output_path}")
                return None
            
            is_intermediate = hide_from_toc or any(
                keyword in layer_name.lower()
                for keyword in ["sampled", "intermediate", "centroid", "zonal stats", "mca grid (clipped)", "aoi reprojected", "aoi fixed"]
            )
            QgsProject.instance().addMapLayer(reloaded_layer, addToLegend=not is_intermediate)
            if is_intermediate:
                reloaded_layer.setCustomProperty('wind_plugin_hidden', True)
                reloaded_layer.setCustomProperty('wind_plugin_intermediate', True)
                self.log_mca_message(f"  → Intermediate layer '{layer_name}' not added to Table of Contents")
            
            self.log_mca_message(f"  ✓ Layer saved and reloaded: {output_path}")
            return reloaded_layer
        
        except Exception as e:
            self.log_mca_message(f"  ERROR in save_and_reload_layer: {str(e)}")
            return None

    def reload_layer_from_path(self, layer_path, layer_name, hide_from_toc=False):
        """
        Reload a layer from a file path and add it to the project.
        
        Args:
            layer_path (str): Path to layer file
            layer_name (str): Name for the layer
            hide_from_toc (bool): If True, add layer but hide it from Table of Contents
            
        Returns:
            QgsVectorLayer or None: Reloaded layer, or None if reload failed
        """
        if not os.path.exists(layer_path):
            self.log_mca_message(f"  ERROR: Layer path does not exist: {layer_path}")
            return None
        
        try:
            layer = QgsVectorLayer(layer_path, layer_name, "ogr")
            if not layer.isValid():
                self.log_mca_message(f"  ERROR: Invalid layer at path: {layer_path}")
                return None
            
            # Add to project. Use addToLegend=False so intermediate layers don't clutter the TOC.
            QgsProject.instance().addMapLayer(layer, addToLegend=not hide_from_toc)
            if hide_from_toc:
                layer.setCustomProperty('wind_plugin_hidden', True)
            
            return layer
        
        except Exception as e:
            self.log_mca_message(f"  ERROR reloading layer: {str(e)}")
            return None

    def _resolve_analysis_crs_for_aoi_layer(self, aoi_layer):
        """
        Choose the metric analysis CRS for an AOI layer (same policy as create_aoi_layer_from_geometry).

        Returns:
            tuple: (QgsCoordinateReferenceSystem or None, error_message or None)
        """
        if not aoi_layer or not aoi_layer.isValid():
            return None, "AOI layer is invalid"

        feat = next(aoi_layer.getFeatures(), None)
        if not feat or not feat.geometry() or feat.geometry().isEmpty():
            return None, "AOI layer has no valid geometry for CRS selection"

        geom = normalize_polygon_aoi_geometry(QgsGeometry(feat.geometry()))
        if geom.isEmpty():
            return None, "AOI geometry is empty after normalization"

        source_crs = aoi_layer.crs()
        if not source_crs or not source_crs.isValid():
            return None, "AOI layer has an invalid CRS"

        try:
            return get_analysis_crs_for_geometry(geom, source_crs), None
        except ValueError as e:
            return None, str(e)

    @staticmethod
    def _geometry_exterior_ring(geometry):
        """Return exterior ring vertices from a polygon geometry, or empty list."""
        if not geometry or geometry.isEmpty():
            return []
        # Use QgsGeometry API (not constGet()) — QGIS 4 concrete types lack isMultipart().
        try:
            if geometry.isMultipart():
                polys = geometry.asMultiPolygon()
                if polys and polys[0] and polys[0][0]:
                    return polys[0][0]
            else:
                poly = geometry.asPolygon()
                if poly and poly[0]:
                    return poly[0]
        except Exception as _be_exc:
            _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L16886")
        return []

    @staticmethod
    def _edge_angles_deg_from_ring(ring, max_edges=4):
        """Compute edge bearing angles (0–180°) for the first max_edges segments of a ring."""
        angles = []
        if not ring or len(ring) < 2:
            return angles
        for i in range(min(max_edges, len(ring) - 1)):
            p0, p1 = ring[i], ring[i + 1]
            dx = p1.x() - p0.x()
            dy = p1.y() - p0.y()
            if dx == 0.0 and dy == 0.0:
                continue
            angles.append(math.degrees(math.atan2(dy, dx)) % 180.0)
        return angles

    @staticmethod
    def _format_edge_angles(angles):
        if not angles:
            return "n/a"
        return ", ".join(f"{a:.4f}°" for a in angles)

    @staticmethod
    def _deviation_from_cardinal(angle_deg):
        """Degrees from nearest axis (0° or 90°) in native CRS."""
        a = angle_deg % 180.0
        return min(a, 180.0 - a, abs(a - 90.0))

    @staticmethod
    def _is_near_cardinal(angle_deg, tolerance=1.5):
        """True if angle is within tolerance of 0° or 90° (treats 179° as ~0°)."""
        return WindSuitability._deviation_from_cardinal(angle_deg) <= tolerance

    def _find_interior_grid_cell_feature(self, grid_layer):
        """
        Return a full (unclipped) grid cell for angle diagnostics.
        Clipped boundary cells inherit AOI edge angles and are not representative.
        """
        if not grid_layer or not grid_layer.isValid():
            return None

        best_feat = None
        best_area = -1.0
        fallback_feat = None

        for feat in grid_layer.getFeatures():
            geom = feat.geometry()
            if not geom or geom.isEmpty():
                continue
            if fallback_feat is None:
                fallback_feat = feat
            angles = self._edge_angles_deg_from_ring(self._geometry_exterior_ring(geom))
            if len(angles) != 4:
                continue
            if not all(self._deviation_from_cardinal(a) <= 0.01 for a in angles):
                continue
            area = geom.area()
            if area > best_area:
                best_area = area
                best_feat = feat

        return best_feat or fallback_feat

    def _layer_source_path(self, layer):
        """Normalized on-disk path from a QgsMapLayer source (strip layername suffix)."""
        if not self._layer_cpp_alive(layer):
            return None
        try:
            src = (layer.source() or "").split("|")[0].strip()
            return self._normalize_path(src) if src else None
        except Exception:
            return None

    def _mca_measure_layer_area_m2(self, layer):
        """Sum polygon areas in square metres using QgsDistanceArea."""
        if not layer or not layer.isValid():
            return 0.0
        distance_area = QgsDistanceArea()
        distance_area.setSourceCrs(layer.crs(), QgsProject.instance().transformContext())
        if layer.crs().isValid():
            distance_area.setEllipsoid(layer.crs().ellipsoidAcronym())
        total = 0.0
        for feat in layer.getFeatures():
            geom = feat.geometry()
            if geom and not geom.isEmpty():
                total += distance_area.measureArea(geom)
        return float(total)

    def _mca_grid_geometry_stats(self, layer, label="layer"):
        """Feature count, total area, CRS, and source path for audit logging."""
        stats = {
            "label": label,
            "name": layer.name() if layer else None,
            "valid": bool(layer and layer.isValid()),
            "feature_count": 0,
            "total_area_m2": 0.0,
            "crs": None,
            "source_path": None,
        }
        if not stats["valid"]:
            return stats
        stats["feature_count"] = int(layer.featureCount())
        stats["total_area_m2"] = self._mca_measure_layer_area_m2(layer)
        stats["crs"] = layer.crs().authid() if layer.crs().isValid() else None
        stats["source_path"] = self._layer_source_path(layer)
        return stats

    def _mca_snapshot_geometries_by_grid_id(self, layer):
        """Capture grid_id -> QgsGeometry for geometry-equality audits."""
        out = {}
        if not layer or not layer.isValid():
            return out
        gid_idx = layer.fields().indexFromName("grid_id")
        for feat in layer.getFeatures():
            geom = feat.geometry()
            if not geom or geom.isEmpty():
                continue
            if gid_idx != -1:
                gid = feat.attribute(gid_idx)
            else:
                gid = feat.id()
            if gid is None:
                continue
            try:
                gid = int(gid)
            except (TypeError, ValueError):
                gid = feat.id()
            out[gid] = QgsGeometry(geom)
        return out

    def _mca_compare_geometry_snapshots(self, snap_a, snap_b):
        """
        Compare two grid_id geometry maps.
        Returns dict with identical/mismatch/missing counts and sample mismatches.
        """
        result = {
            "ids_a": len(snap_a),
            "ids_b": len(snap_b),
            "identical": 0,
            "mismatch": 0,
            "missing_in_b": 0,
            "missing_in_a": 0,
            "sample_mismatches": [],
        }
        for gid, geom_a in snap_a.items():
            geom_b = snap_b.get(gid)
            if geom_b is None:
                result["missing_in_b"] += 1
                continue
            if geom_a.equals(geom_b):
                result["identical"] += 1
            else:
                result["mismatch"] += 1
                if len(result["sample_mismatches"]) < 5:
                    result["sample_mismatches"].append(int(gid))
        for gid in snap_b:
            if gid not in snap_a:
                result["missing_in_a"] += 1
        return result

    def _log_mca_scoring_geometry_audit(self, snap_before, layer_after, stage_label):
        """Log geometry proof: feature count, total area, per-grid_id geometry equality."""
        self.log_mca_message("")
        self.log_mca_message("=" * 50)
        self.log_mca_message("MCA SCORING GEOMETRY AUDIT — {}".format(stage_label))
        self.log_mca_message("=" * 50)

        stats_before = {
            "feature_count": len(snap_before),
            "total_area_m2": 0.0,
        }
        distance_area = None
        if layer_after and layer_after.isValid():
            distance_area = QgsDistanceArea()
            distance_area.setSourceCrs(layer_after.crs(), QgsProject.instance().transformContext())
            if layer_after.crs().isValid():
                distance_area.setEllipsoid(layer_after.crs().ellipsoidAcronym())
        if distance_area:
            for geom in snap_before.values():
                if geom and not geom.isEmpty():
                    stats_before["total_area_m2"] += distance_area.measureArea(geom)

        stats_after = self._mca_grid_geometry_stats(layer_after, label=stage_label)
        cmp_result = self._mca_compare_geometry_snapshots(snap_before, self._mca_snapshot_geometries_by_grid_id(layer_after))

        self.log_mca_message("Before scoring (in-memory snapshot):")
        self.log_mca_message("  feature_count: {}".format(stats_before["feature_count"]))
        self.log_mca_message("  total_area_m2: {:.2f}".format(stats_before["total_area_m2"]))

        self.log_mca_message("After '{}':".format(stage_label))
        self.log_mca_message("  layer_name: {}".format(stats_after.get("name")))
        self.log_mca_message("  source_path: {}".format(stats_after.get("source_path") or "N/A"))
        self.log_mca_message("  feature_count: {}".format(stats_after.get("feature_count")))
        self.log_mca_message("  total_area_m2: {:.2f}".format(stats_after.get("total_area_m2", 0.0)))
        self.log_mca_message("  crs: {}".format(stats_after.get("crs")))

        self.log_mca_message("Geometry comparison (by grid_id, QgsGeometry.equals):")
        self.log_mca_message("  identical: {}".format(cmp_result["identical"]))
        self.log_mca_message("  mismatch: {}".format(cmp_result["mismatch"]))
        self.log_mca_message("  missing_in_after: {}".format(cmp_result["missing_in_b"]))
        self.log_mca_message("  missing_in_before: {}".format(cmp_result["missing_in_a"]))
        if cmp_result["mismatch"] == 0 and cmp_result["missing_in_b"] == 0 and cmp_result["missing_in_a"] == 0:
            self.log_mca_message("  => GEOMETRIES IDENTICAL (no clip/intersection/dissolve in this step)")
        else:
            self.log_mca_message("  => GEOMETRY CHANGE DETECTED at stage '{}'".format(stage_label))
            if cmp_result["sample_mismatches"]:
                self.log_mca_message("  sample mismatched grid_id(s): {}".format(
                    ", ".join(str(g) for g in cmp_result["sample_mismatches"])
                ))
        self.log_mca_message("=" * 50)

    def _log_mca_project_layers_audit(self):
        """List every project layer that may be confused with MCA scored output."""
        self.log_mca_message("")
        self.log_mca_message("=" * 50)
        self.log_mca_message("MCA PROJECT LAYERS AUDIT (map canvas)")
        self.log_mca_message("=" * 50)
        keywords = ("mca", "ranked", "prospect shape", "analysis grid", "final_suitable", "suitable")
        found = 0
        for layer in QgsProject.instance().mapLayers().values():
            name_lower = (layer.name() or "").lower()
            if not any(k in name_lower for k in keywords):
                continue
            found += 1
            kind = type(layer).__name__
            src = self._layer_source_path(layer) if hasattr(layer, "source") else None
            fc = layer.featureCount() if hasattr(layer, "featureCount") else "N/A"
            self.log_mca_message("  [{}] name='{}' id={}".format(kind, layer.name(), layer.id()))
            self.log_mca_message("       source: {}".format(src or "N/A"))
            if hasattr(layer, "featureCount"):
                self.log_mca_message("       feature_count: {}".format(fc))
            if hasattr(layer, "renderer") and layer.renderer():
                self.log_mca_message("       renderer: {}".format(type(layer.renderer()).__name__))
        if found == 0:
            self.log_mca_message("  (no MCA-related layers found in project)")
        self.log_mca_message("=" * 50)

    def _log_mca_grid_alignment_diagnostics(self, aoi_layer, grid_layer):
        """
        Log CRS, extent, and edge-angle diagnostics to distinguish native geometry
        misalignment from on-the-fly reprojection display effects.
        """
        self.log_mca_message("")
        self.log_mca_message("=" * 50)
        self.log_mca_message("MCA GRID ALIGNMENT DIAGNOSTICS")
        self.log_mca_message("=" * 50)

        project_crs = QgsProject.instance().crs()
        aoi_crs = aoi_layer.crs() if aoi_layer else QgsCoordinateReferenceSystem()
        grid_crs = grid_layer.crs() if grid_layer else QgsCoordinateReferenceSystem()

        self.log_mca_message(f"Project CRS: {project_crs.authid() if project_crs.isValid() else 'invalid'}")
        self.log_mca_message(f"AOI CRS:     {aoi_crs.authid() if aoi_crs.isValid() else 'invalid'}")
        self.log_mca_message(f"Grid CRS:    {grid_crs.authid() if grid_crs.isValid() else 'invalid'}")

        if aoi_layer and aoi_layer.isValid():
            self.log_mca_message(f"AOI extent:  {aoi_layer.extent().toString()}")
        else:
            self.log_mca_message("AOI extent:  n/a")

        if grid_layer and grid_layer.isValid():
            self.log_mca_message(f"Grid extent: {grid_layer.extent().toString()}")
        else:
            self.log_mca_message("Grid extent: n/a")

        aoi_angles = []
        grid_angles = []
        aoi_max_dev = None
        grid_max_dev = None
        grid_feat_is_interior = False
        try:
            aoi_feat = next(aoi_layer.getFeatures(), None) if aoi_layer and aoi_layer.isValid() else None
            grid_feat = self._find_interior_grid_cell_feature(grid_layer)

            if aoi_feat and aoi_feat.geometry() and not aoi_feat.geometry().isEmpty():
                aoi_angles = self._edge_angles_deg_from_ring(
                    self._geometry_exterior_ring(aoi_feat.geometry())
                )
                if aoi_angles:
                    aoi_max_dev = max(self._deviation_from_cardinal(a) for a in aoi_angles)
            if grid_feat and grid_feat.geometry() and not grid_feat.geometry().isEmpty():
                grid_angles = self._edge_angles_deg_from_ring(
                    self._geometry_exterior_ring(grid_feat.geometry())
                )
                if grid_angles:
                    grid_max_dev = max(self._deviation_from_cardinal(a) for a in grid_angles)
                    grid_feat_is_interior = all(self._deviation_from_cardinal(a) <= 0.01 for a in grid_angles)
        except Exception as e:
            self.log_mca_message(f"⚠ Could not compute edge angles: {e}")

        self.log_mca_message(f"AOI edge angles (native CRS):        {self._format_edge_angles(aoi_angles)}")
        if aoi_max_dev is not None:
            self.log_mca_message(f"AOI max deviation from E/N axes:   {aoi_max_dev:.4f}°")
        grid_label = "Interior grid cell edge angles (native)" if grid_feat_is_interior else "Grid cell edge angles (native, may be clipped)"
        self.log_mca_message(f"{grid_label}: {self._format_edge_angles(grid_angles)}")
        if grid_max_dev is not None:
            self.log_mca_message(f"Grid max deviation from E/N axes:    {grid_max_dev:.4f}°")

        crs_match = (
            aoi_crs.isValid()
            and grid_crs.isValid()
            and aoi_crs.authid() == grid_crs.authid()
        )
        if crs_match:
            self.log_mca_message("✓ AOI CRS matches Grid CRS")
        else:
            self.log_mca_message("⚠ AOI CRS does NOT match Grid CRS")

        if project_crs.isValid() and grid_crs.isValid() and project_crs.authid() != grid_crs.authid():
            self.log_mca_message(
                f"⚠ Project CRS ({project_crs.authid()}) differs from Grid CRS ({grid_crs.authid()}) "
                "— map display uses on-the-fly reprojection"
            )
        elif project_crs.isValid() and grid_crs.isValid():
            self.log_mca_message("✓ Project CRS matches Grid CRS (display is not reprojecting the grid)")

        if aoi_angles and grid_angles and aoi_max_dev is not None and grid_max_dev is not None:
            grid_axis_aligned = grid_max_dev <= 0.01
            aoi_axis_aligned = aoi_max_dev <= 0.01
            if grid_axis_aligned and not aoi_axis_aligned:
                self.log_mca_message(
                    f"→ Interpretation: Grid is axis-aligned in native CRS (max dev {grid_max_dev:.4f}°); "
                    f"AOI is rotated ~{aoi_max_dev:.2f}° from E/N axes. "
                    "This is a real geometric difference (map-drawn rectangle reprojected to EPSG:3035)."
                )
                if project_crs.isValid() and grid_crs.isValid() and project_crs.authid() != grid_crs.authid():
                    self.log_mca_message(
                        "→ Display note: Project CRS differs from grid CRS — on-screen skew is amplified "
                        "by on-the-fly reprojection. Set Project CRS to the Grid CRS to verify."
                    )
            elif grid_axis_aligned and aoi_axis_aligned:
                self.log_mca_message(
                    "→ Interpretation: AOI and grid are both axis-aligned in native CRS."
                )
            elif not grid_axis_aligned and grid_feat_is_interior:
                self.log_mca_message(
                    f"→ Interpretation: Unexpected — interior grid cell deviates {grid_max_dev:.4f}° from E/N. "
                    "Investigate creategrid output."
                )
            else:
                self.log_mca_message(
                    "→ Interpretation: Grid sample may be a clipped boundary cell; "
                    "interior cells should still be axis-aligned in native CRS."
                )
        else:
            self.log_mca_message("→ Interpretation: Could not compute edge angles (missing geometry).")

        self.log_mca_message("=" * 50)

    def validate_and_prepare_aoi(self, aoi_layer):
        """
        Validate and prepare AOI polygon layer for grid generation.
        
        This function performs comprehensive validation and preparation:
        1. CRS Check: Reprojects to the unified analysis CRS (get_analysis_crs_for_geometry)
        2. Geometry Validation: Detects and fixes invalid geometries
        3. Extent Validation: Verifies AOI has valid extent (width/height > 0)
        4. Logging: Records all corrections and validation results
        
        Args:
            aoi_layer (QgsVectorLayer): The AOI polygon layer to validate
            
        Returns:
            tuple: (validated_layer: QgsVectorLayer or None, error_message: str or None)
                   Returns (None, error_message) if validation fails
                   Returns (validated_layer, None) if validation succeeds
        """
        if not aoi_layer:
            return None, "AOI layer is None"
        
        if not aoi_layer.isValid():
            return None, "AOI layer is invalid"
        
        self.log_mca_message("=" * 50)
        self.log_mca_message("AOI VALIDATION AND PREPARATION")
        self.log_mca_message("=" * 50)
        
        original_crs = aoi_layer.crs()
        original_feature_count = aoi_layer.featureCount()
        
        self.log_mca_message(f"Original AOI Layer: {aoi_layer.name()}")
        self.log_mca_message(f"Original CRS: {original_crs.authid()} - {original_crs.description()}")
        self.log_mca_message(f"Original Features: {original_feature_count}")
        
        current_layer = aoi_layer
        temp_files = []  # Track temporary files for cleanup
        
        try:
            # ====================================================================
            # Step 1: CRS Validation and Reprojection
            # ====================================================================
            self.log_mca_message("")
            self.log_mca_message("Step 1: Checking CRS...")

            target_crs, crs_error = self._resolve_analysis_crs_for_aoi_layer(current_layer)
            if crs_error:
                self.log_mca_message(f"  ❌ {crs_error}")
                return None, crs_error

            current_crs = current_layer.crs()
            current_authid = current_crs.authid() if current_crs.isValid() else ""
            target_authid = target_crs.authid()
            needs_reprojection = (
                not current_crs.isValid()
                or current_crs.isGeographic()
                or current_crs.mapUnits() != QgsUnitTypes.DistanceMeters
                or current_authid != target_authid
            )

            if original_crs.isGeographic():
                self.log_mca_message("  ⚠️ Geographic CRS detected (units: degrees)")
                self.log_mca_message("  → Reprojecting to unified analysis CRS (units: meters)")
            elif current_authid == target_authid and current_crs.mapUnits() == QgsUnitTypes.DistanceMeters:
                self.log_mca_message(f"  ✓ CRS already matches analysis CRS: {target_authid}")
            else:
                self.log_mca_message(
                    f"  → Target analysis CRS: {target_authid} - {target_crs.description()}"
                )
                if current_authid and current_authid != target_authid:
                    self.log_mca_message(f"  → Current CRS ({current_authid}) differs from analysis CRS")

            self.log_mca_message(f"  → Analysis CRS: {target_authid} - {target_crs.description()}")

            # Perform reprojection if needed
            if needs_reprojection:
                temp_dir = tempfile.gettempdir()
                reprojected_output = os.path.join(temp_dir, f"aoi_reprojected_{uuid.uuid4().hex[:8]}.gpkg")
                temp_files.append(reprojected_output)
                
                self.log_mca_message(f"  → Reprojecting layer...")
                result = processing.run("native:reprojectlayer", {
                    'INPUT': current_layer,
                    'TARGET_CRS': target_crs,
                    'OUTPUT': reprojected_output
                })
                
                if 'OUTPUT' not in result:
                    return None, "Failed to reproject AOI layer"
                
                # CRITICAL: Reload reprojected layer from disk (hidden from TOC)
                reprojected_path = result['OUTPUT']
                reprojected_layer = self.reload_layer_from_path(reprojected_path, "AOI Reprojected", hide_from_toc=True)
                if not reprojected_layer or not reprojected_layer.isValid():
                    return None, "Reprojected AOI layer is invalid"
                
                current_layer = reprojected_layer
                self.log_mca_message(f"  ✓ Reprojection complete")
                self.log_mca_message(f"    New CRS: {current_layer.crs().authid()}")
            
            # ====================================================================
            # Step 2: Geometry Validation and Fixing
            # ====================================================================
            self.log_mca_message("")
            self.log_mca_message("Step 2: Checking geometry validity...")
            
            # Check for invalid geometries
            invalid_count = 0
            null_count = 0
            
            for feature in current_layer.getFeatures():
                geom = feature.geometry()
                if geom is None or geom.isEmpty():
                    null_count += 1
                elif not geom.isGeosValid():
                    invalid_count += 1
            
            if invalid_count > 0 or null_count > 0:
                self.log_mca_message(f"  ⚠️ Found {invalid_count} invalid geometries and {null_count} null geometries")
                self.log_mca_message(f"  → Fixing geometries...")
                
                temp_dir = tempfile.gettempdir()
                fixed_output = os.path.join(temp_dir, f"aoi_fixed_{uuid.uuid4().hex[:8]}.gpkg")
                temp_files.append(fixed_output)
                
                result = processing.run("native:fixgeometries", {
                    'INPUT': current_layer,
                    'OUTPUT': fixed_output
                })
                
                if 'OUTPUT' not in result:
                    return None, "Failed to fix geometries"
                
                # CRITICAL: Reload fixed layer from disk (hidden from TOC - intermediate processing layer)
                fixed_path = result['OUTPUT']
                fixed_layer = self.reload_layer_from_path(fixed_path, "AOI Fixed", hide_from_toc=True)
                if not fixed_layer or not fixed_layer.isValid():
                    return None, "Fixed AOI layer is invalid"
                
                # Verify fix
                fixed_invalid = 0
                fixed_null = 0
                for feature in fixed_layer.getFeatures():
                    geom = feature.geometry()
                    if geom is None or geom.isEmpty():
                        fixed_null += 1
                    elif not geom.isGeosValid():
                        fixed_invalid += 1
                
                if fixed_invalid == 0 and fixed_null == 0:
                    self.log_mca_message(f"  ✓ All geometries fixed successfully")
                    current_layer = fixed_layer
                else:
                    self.log_mca_message(f"  ⚠️ Some geometries remain invalid after fix")
                    current_layer = fixed_layer
            else:
                self.log_mca_message(f"  ✓ All geometries are valid")

            # ====================================================================
            # Step 2b: Axis-align rotated rectangular AOIs (map-drawn rectangles)
            # ====================================================================
            self.log_mca_message("")
            self.log_mca_message("Step 2b: Checking AOI/grid axis alignment...")
            current_layer, was_aligned = self._maybe_axis_align_aoi_layer(current_layer)
            if was_aligned:
                if (
                    self._layer_cpp_alive(getattr(self, "user_aoi_layer", None))
                    and current_layer.id() == self.user_aoi_layer.id()
                ):
                    self._update_aoi_display_from_layer(current_layer)
            else:
                self.log_mca_message("  ✓ No axis-alignment correction needed")
            
            # ====================================================================
            # Step 3: Extent Validation
            # ====================================================================
            self.log_mca_message("")
            self.log_mca_message("Step 3: Validating extent...")
            
            extent = current_layer.extent()
            width = extent.xMaximum() - extent.xMinimum()
            height = extent.yMaximum() - extent.yMinimum()
            
            self.log_mca_message(f"  Extent: X=[{extent.xMinimum():.2f}, {extent.xMaximum():.2f}]")
            self.log_mca_message(f"          Y=[{extent.yMinimum():.2f}, {extent.yMaximum():.2f}]")
            unit_name = "meters" if current_layer.crs().mapUnits() == QgsUnitTypes.DistanceMeters else "units"
            self.log_mca_message(f"  Width: {width:.2f} {unit_name}")
            self.log_mca_message(f"  Height: {height:.2f} {unit_name}")
            
            if width <= 0 or height <= 0:
                error_msg = f"AOI extent is invalid: width={width:.2f}, height={height:.2f}"
                self.log_mca_message(f"  ❌ {error_msg}")
                return None, error_msg
            
            self.log_mca_message(f"  ✓ Extent is valid")
            
            # ====================================================================
            # Step 4: Final Validation Summary
            # ====================================================================
            self.log_mca_message("")
            self.log_mca_message("=" * 50)
            self.log_mca_message("VALIDATION SUMMARY")
            self.log_mca_message("=" * 50)
            self.log_mca_message(f"Final CRS: {current_layer.crs().authid()} - {current_layer.crs().description()}")
            self.log_mca_message(f"Final Features: {current_layer.featureCount()}")
            self.log_mca_message(f"Extent Width: {width:.2f} m")
            self.log_mca_message(f"Extent Height: {height:.2f} m")
            
            if needs_reprojection:
                self.log_mca_message(f"✓ CRS reprojected: {original_crs.authid()} → {current_layer.crs().authid()}")
            
            if invalid_count > 0 or null_count > 0:
                self.log_mca_message(f"✓ Geometries fixed: {invalid_count + null_count} issues resolved")
            
            self.log_mca_message(f"✓ AOI layer is ready for grid generation")
            self.log_mca_message("")
            
            # CRITICAL: Save final AOI layer to stable disk location and reload
            # This prevents "wrapped C/C++ object has been deleted" errors
            self.log_mca_message("Saving final AOI layer to stable location...")
            # Save final AOI layer (hidden from TOC - it's only for internal processing)
            final_aoi_saved = self.save_and_reload_layer(
                current_layer,
                "Final AOI (Validated)",
                "final_aoi_validated.gpkg",
                hide_from_toc=True  # Hide intermediate processing layer
            )
            
            if not final_aoi_saved:
                return None, "Failed to save final AOI layer to stable location"
            
            # Store as final_aoi_layer for use in grid generation
            self.final_aoi_layer = final_aoi_saved
            # Only mark as final output if no other final output exists
            # (to avoid overwriting user's final exclusion/inclusion result)
            existing_final = self.get_final_polygon_layer()
            if not existing_final:
                self.mark_layer_as_final_output(final_aoi_saved)
            self.log_mca_message("✓ Final AOI layer saved and stored for grid generation")
            
            # CRITICAL: Create reference raster from AOI ONLY (not from existing rasters)
            self.log_mca_message("")
            self.log_mca_message("Creating reference raster from AOI...")
            grid_size = self.dlg.spin_grid_size.value() if hasattr(self.dlg, 'spin_grid_size') else 100.0
            
            # Ensure MCA output directory exists
            if not self.mca_output_dir:
                self.mca_output_dir = self.get_mca_output_directory()
            
            reference_path = os.path.join(self.mca_output_dir, "mca_reference_grid.tif")
            ref_raster, ref_error = self.create_reference_raster_from_aoi(final_aoi_saved, reference_path, pixel_size=grid_size)
            if ref_raster:
                self.log_mca_message(f"✓ Reference raster created: {ref_raster.width()} x {ref_raster.height()} pixels")
                self.log_mca_message(f"  Pixel size: {ref_raster.rasterUnitsPerPixelX():.2f} m")
                self.log_mca_message(f"  CRS: {ref_raster.crs().authid()}")
            else:
                self.log_mca_message(f"❌ Failed to create reference raster: {ref_error}")
                return None, f"Failed to create reference raster: {ref_error}"
            
            return final_aoi_saved, None
        
        except Exception as e:
            error_msg = f"Error during AOI validation: {str(e)}"
            self.log_mca_message(f"❌ {error_msg}")
            return None, error_msg

    def create_reference_raster_from_aoi(self, aoi_layer, output_path, pixel_size=None):
        """
        Create an immutable MCA reference raster using ONLY:
          - AOI extent
          - AOI CRS
          - pixel_size (or MCA_RESOLUTION if not provided)
        This raster is the SINGLE source of truth grid.
        
        MCA SPATIAL CONTRACT (IMMUTABLE INVARIANTS):
        - Resolution is FIXED (never inferred or recalculated after creation)
        - Extent comes from AOI (never modified after creation)
        - CRS must be projected (geographic CRS auto-reprojected to UTM)
        - Rasterization only occurs against validated reference grid
        - Attribute-based rasterization must use FIELD parameter
        - Presence/absence rasterization must use BURN parameter
        - Reference raster parameters (width, height, extent, CRS, pixel size) are IMMUTABLE
        
        This function creates the reference raster ONCE per MCA analysis run.
        The reference raster MUST NOT be modified after creation.
        """
        if not aoi_layer or not aoi_layer.isValid():
            return None, "Invalid AOI layer for reference raster"

        analysis_crs = QgsCoordinateReferenceSystem(PROJECT_CRS_METRIC)
        if not analysis_crs.isValid():
            return None, f"Invalid analysis CRS: {PROJECT_CRS_METRIC}"
        layer_for_grid = aoi_layer
        temp_reproj = None
        try:
            if (not aoi_layer.crs().isValid()) or (aoi_layer.crs().authid() != analysis_crs.authid()):
                temp_reproj = self._normalize_path(
                    os.path.join(tempfile.gettempdir(), "aoi_ref_crs_{}.gpkg".format(uuid.uuid4().hex[:8]))
                )
                processing.run("native:reprojectlayer", {
                    'INPUT': aoi_layer,
                    'TARGET_CRS': analysis_crs,
                    'OUTPUT': temp_reproj
                })
                if not os.path.exists(temp_reproj):
                    return None, "Failed to reproject AOI to analysis CRS"
                reproj_layer = QgsVectorLayer(temp_reproj, "AOI_ANALYSIS_CRS", "ogr")
                if not reproj_layer.isValid() or reproj_layer.featureCount() == 0:
                    return None, "AOI reprojection produced an invalid/empty layer"
                layer_for_grid = reproj_layer
            extent = layer_for_grid.extent()
            crs = layer_for_grid.crs()
        finally:
            pass

        if extent.width() <= 0 or extent.height() <= 0:
            return None, "AOI extent collapsed – cannot build reference raster"

        # Use provided pixel_size or default to MCA_RESOLUTION
        if pixel_size is None:
            pixel_size = MCA_RESOLUTION

        width = int(extent.width() / pixel_size)
        height = int(extent.height() / pixel_size)

        if width <= 0 or height <= 0:
            return None, (
                f"Reference raster grid invalid: width={width}, height={height}, "
                f"pixel_size={pixel_size}"
            )

        # STEP 4: Protect Reference Grid Lifecycle
        # Ensure any existing reference raster layer is removed from QgsProject before overwriting file
        if os.path.exists(output_path):
            # Remove existing layer from project if it exists (prevents Windows file lock)
            existing_layers = QgsProject.instance().mapLayers().values()
            for layer in existing_layers:
                if isinstance(layer, QgsRasterLayer):
                    layer_source = layer.source()
                    if layer_source and os.path.normpath(layer_source) == os.path.normpath(output_path):
                        QgsProject.instance().removeMapLayer(layer.id())
                        layer = None  # Explicitly release reference
                        import time
                        time.sleep(0.1)  # Brief pause to allow Windows to release file handle
                        break
            
            # Remove existing file
            try:
                os.remove(output_path)
                import time
                time.sleep(0.1)  # Brief pause for file system
            except Exception as e:
                # If removal fails, try with unique filename to avoid overwrite issues
                output_path = output_path.replace('.tif', f'_{uuid.uuid4().hex[:8]}.tif')
                print(f"  Warning: Could not remove existing reference raster, using unique filename: {output_path}")
        
        # Empty reference grid: create GeoTIFF directly (no temporary rectangle vector / aoi_rect_*.gpkg).
        try:
            if not _GDAL_AVAILABLE or not _NUMPY_AVAILABLE:
                return None, "GDAL/numpy required to create MCA reference raster"
            xmin = extent.xMinimum()
            xmax = extent.xMaximum()
            ymin = extent.yMinimum()
            ymax = extent.yMaximum()
            xres = (xmax - xmin) / float(width)
            yres = (ymax - ymin) / float(height)
            geotransform = (xmin, xres, 0.0, ymax, 0.0, -yres)
            driver = gdal.GetDriverByName("GTiff")
            if not driver:
                return None, "GTiff driver not available"
            ds_out = driver.Create(output_path, width, height, 1, gdal.GDT_Float32, ["COMPRESS=LZW", "TILED=YES"])
            if not ds_out:
                return None, "Failed to create MCA reference raster file"
            ds_out.SetGeoTransform(geotransform)
            if crs.isValid():
                ds_out.SetProjection(crs.toWkt())
            arr = np.full((height, width), MCA_NODATA, dtype=np.float32)
            band = ds_out.GetRasterBand(1)
            band.SetNoDataValue(MCA_NODATA)
            band.WriteArray(arr)
            band.FlushCache()
            ds_out.FlushCache()
            ds_out = None
            if not os.path.exists(output_path):
                return None, "Failed to create reference raster file"
            
            # Load and validate reference raster
            raster = QgsRasterLayer(output_path, "MCA_REFERENCE_GRID", "gdal")
            if not raster.isValid():
                return None, "Reference raster file created but is invalid"
            
            # Validate raster parameters
            actual_width = raster.width()
            actual_height = raster.height()
            if actual_width != width or actual_height != height:
                # Try to fix with gdal:warpreproject to exact dimensions
                fixed_path = output_path.replace('.tif', '_fixed.tif')
                try:
                    processing.run("gdal:warpreproject", {
                        'INPUT': output_path,
                        'SOURCE_CRS': crs,
                        'TARGET_CRS': crs,
                        'RESAMPLING': 0,  # Nearest neighbor
                        'NODATA': MCA_NODATA,
                        'TARGET_RESOLUTION': [pixel_size, pixel_size],
                        'TARGET_EXTENT': f"{extent.xMinimum()},{extent.xMaximum()},{extent.yMinimum()},{extent.yMaximum()}",
                        'TARGET_EXTENT_CRS': crs,
                        'OUTPUT': fixed_path
                    })
                    if os.path.exists(fixed_path):
                        # Replace original with fixed version
                        try:
                            os.remove(output_path)
                            os.rename(fixed_path, output_path)
                            raster = QgsRasterLayer(output_path, "MCA_REFERENCE_GRID", "gdal")
                            if raster.isValid():
                                actual_width = raster.width()
                                actual_height = raster.height()
                        except Exception as _be_exc:
                            _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L17656")
                except Exception as _be_exc:
                    _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L17658")
                
                if actual_width != width or actual_height != height:
                    return None, (
                        f"Reference raster dimensions mismatch: "
                        f"expected {width}x{height}, got {actual_width}x{actual_height}. "
                        f"Extent: {extent.toString()}, Pixel size: {pixel_size}m"
                    )
            
            return raster, None
            
        except Exception as e:
            return None, f"Error creating reference raster: {str(e)}"
        finally:
            try:
                if temp_reproj and os.path.exists(temp_reproj):
                    os.remove(temp_reproj)
            except Exception as _be_exc:
                _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L17676")

    def generate_mca_grid(self):
        """
        Generate a regular fishnet grid covering AOI extent and clip to AOI boundary.
        
        Process:
        1. Get prospect polygon layer (AOI) from previous analysis steps
        2. Read grid cell size from spin_grid_size widget
        3. Generate regular rectangular grid using native:creategrid
        4. Clip grid to AOI boundary using native:clip
        5. Add grid_id attribute to each grid cell
        6. Calculate and display grid statistics in lbl_grid_info
        7. Automatically add grid layer to map canvas
        
        The grid serves as the analysis unit for MCA, with each cell representing
        a spatial unit that will be evaluated against all criteria.
        
        Grid statistics include:
        - Number of grid cells
        - AOI area (km²)
        - Grid cell size (meters)
        - Cell area (km²)
        - Approximate resolution (km)
        """
        if not hasattr(self.dlg, 'spin_grid_size'):
            QMessageBox.warning(self.dlg, "Error", "Grid size spinbox not found.")
            return
        
        if not hasattr(self.dlg, 'lbl_grid_info'):
            QMessageBox.warning(self.dlg, "Error", "Grid info label not found.")
            return
        
        # Clear previous log
        if hasattr(self.dlg, 'txt_mca_log'):
            self.dlg.txt_mca_log.clear()
        
        self.log_mca_message("Starting grid generation...")
        
        # Get grid cell size
        grid_size = self.dlg.spin_grid_size.value()
        if grid_size <= 0:
            QMessageBox.warning(self.dlg, "Invalid Grid Size", "Grid cell size must be greater than 0.")
            return
        
        self.log_mca_message(f"Grid cell size: {grid_size} meters")
        
        # Grid AOI: prefer current user AOI; fallback to marked final / prospect for older workflows
        aoi_layer = self.get_user_aoi_layer()
        if not aoi_layer:
            aoi_layer = self.get_prospect_polygon_layer()
        if not aoi_layer:
            QMessageBox.warning(
                self.dlg,
                "No AOI Found",
                "Define an Area of Interest (rectangle, polygon, or file), or run spatial analysis "
                "so a final prospect polygon is available for MCA.",
            )
            self.log_mca_message("ERROR: No AOI layer found for grid (user AOI or prospect).")
            return
        
        # Log which layer is being used
        self.log_mca_message(f"Using AOI layer: '{aoi_layer.name()}'")
        self.log_mca_message(f"AOI layer ID: {aoi_layer.id()}")
        
        # Validate and prepare AOI layer before grid generation
        validated_aoi, error = self.validate_and_prepare_aoi(aoi_layer)
        if error:
            QMessageBox.critical(self.dlg, "AOI Validation Failed", error)
            self.log_mca_message(f"ERROR: {error}")
            return
        
        # Use validated AOI layer - ensure it's still valid
        aoi_layer = validated_aoi
        self.log_mca_message(f"Using validated AOI layer: '{aoi_layer.name()}'")
        
        # Safety check: Verify layer is still valid
        if not aoi_layer or not aoi_layer.isValid():
            error_msg = "Validated AOI layer is missing or invalid"
            QMessageBox.critical(self.dlg, "AOI Error", error_msg)
            self.log_mca_message(f"ERROR: {error_msg}")
            return
        
        # Log layer details for verification
        self.log_mca_message(f"AOI features: {aoi_layer.featureCount()}")
        self.log_mca_message(f"AOI CRS: {aoi_layer.crs().authid()}")
        
        # Get AOI extent - CRITICAL: Use the actual geometry extent
        # This ensures we use the correct polygon boundaries
        aoi_extent = aoi_layer.extent()
        self.log_mca_message(f"AOI extent: {aoi_extent.toString()}")
        
        # Verify extent is valid
        if aoi_extent.isEmpty() or aoi_extent.width() <= 0 or aoi_extent.height() <= 0:
            QMessageBox.critical(
                self.dlg,
                "Invalid AOI Extent",
                f"AOI layer has invalid extent:\n{aoi_extent.toString()}\n\n"
                f"Please check that the final polygon layer has valid geometry."
            )
            self.log_mca_message(f"ERROR: Invalid AOI extent")
            return
        
        if aoi_layer.featureCount() == 0:
            QMessageBox.critical(
                self.dlg,
                "Empty AOI",
                "The final polygon layer has no features.\n\n"
                "Please check that your exclusion/inclusion analysis produced a valid result."
            )
            self.log_mca_message(f"ERROR: AOI layer has no features")
            return
        
        # Calculate AOI area
        crs = aoi_layer.crs()
        distance_area = QgsDistanceArea()
        distance_area.setSourceCrs(crs, QgsProject.instance().transformContext())
        distance_area.setEllipsoid(crs.ellipsoidAcronym())
        
        total_area = 0
        for feature in aoi_layer.getFeatures():
            geom = feature.geometry()
            if geom:
                area = distance_area.measureArea(geom)
                total_area += area
        
        area_km2 = total_area / 1000000  # Convert to km²
        
        try:
            # Create temporary output path for grid
            temp_dir = tempfile.gettempdir()
            grid_output = os.path.join(temp_dir, f"mca_grid_{uuid.uuid4().hex[:8]}.gpkg")
            
            # Generate regular grid using native:creategrid
            self.log_mca_message("Generating regular grid...")
            grid_result = processing.run("native:creategrid", {
                'TYPE': 2,  # Rectangle (polygon)
                'EXTENT': aoi_extent,
                'HSPACING': grid_size,
                'VSPACING': grid_size,
                'HOVERLAY': 0,
                'VOVERLAY': 0,
                'CRS': crs,
                'OUTPUT': grid_output
            })
            
            if 'OUTPUT' not in grid_result:
                QMessageBox.critical(self.dlg, "Error", "Failed to generate grid.")
                self.log_mca_message("ERROR: Failed to generate grid.")
                return
            
            grid_path = grid_result['OUTPUT']
            self.log_mca_message(f"Grid generated: {grid_path}")
            
            # CRITICAL: Add grid_id to grid BEFORE clipping to ensure it's preserved
            # Load the initial grid, add grid_id, save it, then clip
            temp_grid_layer = QgsVectorLayer(grid_path, "Temp Grid", "ogr")
            if temp_grid_layer.isValid():
                # Add grid_id attribute
                if temp_grid_layer.fields().indexFromName('grid_id') == -1:
                    temp_grid_layer.dataProvider().addAttributes([QgsField('grid_id', QVariant.Int)])
                    temp_grid_layer.updateFields()
                
                # Populate grid_id
                temp_grid_layer.startEditing()
                for idx, feature in enumerate(temp_grid_layer.getFeatures(), 1):
                    feature.setAttribute('grid_id', idx)
                    temp_grid_layer.updateFeature(feature)
                temp_grid_layer.commitChanges()
                
                # Save grid with grid_id
                grid_with_id_path = os.path.join(temp_dir, f"mca_grid_with_id_{uuid.uuid4().hex[:8]}.gpkg")
                processing.run("native:savefeatures", {
                    'INPUT': temp_grid_layer,
                    'OUTPUT': grid_with_id_path
                })
                grid_path = grid_with_id_path
                self.log_mca_message(f"✓ Added grid_id to {temp_grid_layer.featureCount()} cells before clipping")
            
            # Clip grid to AOI boundary (grid_id will be preserved)
            self.log_mca_message("Clipping grid to AOI boundary...")
            clipped_output = os.path.join(temp_dir, f"mca_grid_clipped_{uuid.uuid4().hex[:8]}.gpkg")
            
            clip_result = processing.run("native:clip", {
                'INPUT': grid_path,
                'OVERLAY': aoi_layer,
                'OUTPUT': clipped_output
            })
            
            if 'OUTPUT' not in clip_result:
                QMessageBox.critical(self.dlg, "Error", "Failed to clip grid to AOI.")
                self.log_mca_message("ERROR: Failed to clip grid.")
                return
            
            clipped_path = clip_result['OUTPUT']
            self.log_mca_message(f"Grid clipped: {clipped_path}")
            
            # CRITICAL: Reload clipped grid layer from disk (hidden from TOC - will be replaced by final grid)
            grid_layer = self.reload_layer_from_path(clipped_path, "MCA Grid (Clipped)", hide_from_toc=True)
            if not grid_layer or not grid_layer.isValid():
                QMessageBox.critical(self.dlg, "Error", "Failed to reload clipped grid layer.")
                self.log_mca_message("ERROR: Failed to reload grid layer.")
                return
            
            # Verify grid_id attribute exists after clipping
            grid_id_idx = grid_layer.fields().indexFromName('grid_id')
            if grid_id_idx == -1:
                self.log_mca_message("WARNING: grid_id attribute missing after clipping - adding it now...")
                grid_layer.dataProvider().addAttributes([QgsField('grid_id', QVariant.Int)])
                grid_layer.updateFields()
                grid_id_idx = grid_layer.fields().indexFromName('grid_id')
                
                # Populate grid_id
                grid_layer.startEditing()
                for idx, feature in enumerate(grid_layer.getFeatures(), 1):
                    feature.setAttribute('grid_id', idx)
                    grid_layer.updateFeature(feature)
                grid_layer.commitChanges()
                self.log_mca_message(f"✓ Added grid_id to {grid_layer.featureCount()} cells after clipping")
            else:
                self.log_mca_message(f"✓ grid_id attribute preserved after clipping (index: {grid_id_idx})")
            
            # Verify grid_id was set correctly
            verify_count = 0
            null_count = 0
            for feature in grid_layer.getFeatures():
                grid_id_val = feature.attribute('grid_id')
                if grid_id_val is not None:
                    verify_count += 1
                else:
                    null_count += 1
            self.log_mca_message(f"✓ Verified: {verify_count} cells have grid_id, {null_count} cells missing grid_id")
            
            if null_count > 0:
                self.log_mca_message(f"  WARNING: {null_count} cells are missing grid_id - this may cause MCA to fail")
            
            # CRITICAL: Save grid layer to stable location and reload
            # This prevents "wrapped C/C++ object has been deleted" errors
            self.log_mca_message("Saving grid layer to stable location...")
            grid_layer_saved = self.save_and_reload_layer(
                grid_layer,
                "MCA Analysis Grid",
                "mca_analysis_grid.gpkg"
            )
            
            if not grid_layer_saved:
                QMessageBox.critical(self.dlg, "Error", "Failed to save grid layer to stable location.")
                self.log_mca_message("ERROR: Failed to save grid layer.")
                return
            
            # Store stable grid layer
            self.mca_grid_layer = grid_layer_saved
            self.log_mca_message(f"✓ Grid layer saved and stored: {grid_layer_saved.name()}")

            try:
                self._log_mca_grid_alignment_diagnostics(aoi_layer, grid_layer_saved)
            except Exception as diag_err:
                self.log_mca_message(f"WARNING: Alignment diagnostics failed: {diag_err}")

            # Calculate grid statistics
            grid_cell_count = grid_layer.featureCount()
            cell_area_m2 = grid_size * grid_size
            cell_area_km2 = cell_area_m2 / 1000000
            total_grid_area_km2 = grid_cell_count * cell_area_km2
            resolution_km = grid_size / 1000
            
            # Update grid info label
            info_text = (
                f"Grid Cells: {grid_cell_count:,}\n"
                f"AOI Area: {area_km2:.2f} km²\n"
                f"Grid Size: {grid_size} m\n"
                f"Cell Area: {cell_area_km2:.4f} km²\n"
                f"Resolution: ~{resolution_km:.2f} km"
            )
            self.dlg.lbl_grid_info.setText(info_text)
            
            self.log_mca_message("=" * 50)
            self.log_mca_message("GRID GENERATION COMPLETE")
            self.log_mca_message("=" * 50)
            self.log_mca_message(f"Grid cells: {grid_cell_count:,}")
            self.log_mca_message(f"AOI area: {area_km2:.2f} km²")
            self.log_mca_message(f"Grid size: {grid_size} m")
            self.log_mca_message(f"Cell area: {cell_area_km2:.4f} km²")
            self.log_mca_message(f"Approximate resolution: ~{resolution_km:.2f} km")
            
            QMessageBox.information(
                self.dlg,
                "Grid Generated",
                f"Successfully generated {grid_cell_count:,} grid cells.\n\n"
                f"Grid size: {grid_size} m\n"
                f"AOI area: {area_km2:.2f} km²"
            )
        
        except Exception as e:
            QMessageBox.critical(
                self.dlg,
                "Grid Generation Error",
                f"An error occurred during grid generation:\n{str(e)}"
            )
            self.log_mca_message(f"ERROR: {str(e)}")

    def prepare_mca_data_matrix(self):
        """
        Prepare data matrix for MCA calculation.
        
        This method processes all included criteria from Phase 2 validation.
        Grid value extraction is controlled by self.grid_sampling_method:
        - "mean": zonal statistics (mean raster value per grid cell), e.g. native:zonalstatisticsfb
        - "centroid": sample raster value at each grid cell centroid
        
        Criteria values are computed only inside each cell's intersection with the
        Final Suitable Area (after hard constraints). Full fishnet geometry is unchanged.
        
        For each criterion, extracts:
        - grid_id: Unique identifier for each grid cell
        - criterion_name: Name of the criterion layer
        - raw_value: Extracted raster value (mean or sampled)
        - weight: Criterion weight from Phase 1 (percentage)
        - role: "Beneficial" or "Penalizing" from Phase 2
        
        Returns: 
            tuple: (data_matrix: list of dicts, error_message: str or None)
        """
        # Safety check: Verify grid layer is still valid
        if not self.mca_grid_layer or not self.mca_grid_layer.isValid():
            return None, "Grid layer not generated or invalid. Please generate grid first."
        
        # Clear previous matrix
        self.mca_data_matrix = []
        
        # Get criteria from Phase 2
        criteria_list = self.extract_criteria_data()
        
        if not criteria_list:
            return None, "No criteria found in the weights table. Please add criteria in Phase 1."
        
        self.log_mca_message(f"Found {len(criteria_list)} criteria in table")
        
        included_criteria = [c for c in criteria_list if c.get('include', False)]
        
        if not included_criteria:
            return None, f"No included criteria found. Found {len(criteria_list)} total criteria, but none are marked as 'Include=True'. Please check the Include checkboxes in Phase 1."
        
        self.log_mca_message(f"Found {len(included_criteria)} included criteria")
        
        # Verify layer objects exist for included criteria
        valid_criteria = []
        for crit in included_criteria:
            if crit.get('layer') and isinstance(crit.get('layer'), QgsRasterLayer):
                if crit.get('layer').isValid():
                    valid_criteria.append(crit)
                else:
                    self.log_mca_message(f"  WARNING: Layer '{crit['layer_name']}' is invalid")
            else:
                self.log_mca_message(f"  WARNING: Layer '{crit['layer_name']}' object not found")
        
        if not valid_criteria:
            return None, f"No valid raster layers found for included criteria. Please ensure:\n1. Layers are loaded in QGIS project\n2. Layers are valid raster layers\n3. Re-add layers to weights table if needed"
        
        self.log_mca_message(f"Found {len(valid_criteria)} criteria with valid raster layers")
        included_criteria = valid_criteria
        
        # Grid value extraction: "mean" = zonal statistics (mean per cell), "centroid" = sample at cell centroid
        method = getattr(self, 'grid_sampling_method', 'mean')
        use_continuous = (method == 'mean')
        
        self.log_mca_message("=" * 50)
        self.log_mca_message("PREPARING MCA DATA MATRIX")
        self.log_mca_message("=" * 50)
        self.log_mca_message(f"Grid value extraction: {'Mean value (zonal statistics)' if use_continuous else 'Cell centroid sampling'}")
        self.log_mca_message(f"Processing {len(included_criteria)} criteria...")
        self.log_mca_message("")
        
        total_cells = self.mca_grid_layer.featureCount()
        master_ref_layer, master_ref_path, master_name = self.get_master_reference_raster_for_decision_making()
        if not master_ref_layer or not master_ref_path:
            return None, (
                "No master reference raster found. Complete Spatial Filtering first so criteria "
                "can be aligned to the current analysis grid, then generate the MCA grid and run the analysis."
            )
        self.log_mca_message(
            "Master analysis grid: {} ({})".format(master_name or "unknown", master_ref_path)
        )

        if not self._resolve_final_suitable_mask_raster_path():
            return None, (
                "Final Suitable Area raster (spatial_filtered.tif) not found. "
                "Complete Spatial Filtering before MCA."
            )

        self.log_mca_message("")
        self.log_mca_message("Computing per-cell suitable coverage (grid ∩ Final Suitable Area)...")
        coverage, cov_err = self._compute_mca_grid_suitable_coverage()
        if cov_err:
            return None, cov_err
        self.mca_grid_suitable_coverage = coverage

        processed_criteria = 0
        
        for criterion in included_criteria:
            criterion_name = criterion['layer_name']
            weight = criterion['weight']
            role = criterion['role']
            layer_obj = criterion.get('layer')
            aligned_temp = None
            unit_clamped_temp = None
            masked_temp = None
            
            processed_criteria += 1
            self.log_mca_message(f"[{processed_criteria}/{len(included_criteria)}] Processing: {criterion_name}")
            
            if not layer_obj:
                self.log_mca_message(f"  ERROR: Layer object not found for '{criterion_name}'")
                self.log_mca_message(f"  → Try: Re-add the layer to the weights table in Phase 1")
                continue
            
            if not isinstance(layer_obj, QgsRasterLayer):
                self.log_mca_message(f"  ERROR: Layer '{criterion_name}' is not a raster layer (type: {type(layer_obj).__name__})")
                continue
            
            if not layer_obj.isValid():
                self.log_mca_message(f"  ERROR: Layer '{criterion_name}' is invalid")
                self.log_mca_message(f"  → Check: Layer exists in QGIS project and is loaded correctly")
                continue
            
            # Align each criterion raster to the immutable master grid to guarantee comparable coverage.
            # This prevents edge/border under-coverage (e.g., slope smaller than AOI) from silently biasing scores.
            working_layer = layer_obj
            layer_path = self._file_path_from_raster_layer(layer_obj)
            if layer_path:
                try:
                    aligned_temp = self._normalize_path(
                        os.path.join(tempfile.gettempdir(), "mca_aligned_{}_{}.tif".format(processed_criteria, uuid.uuid4().hex[:8]))
                    )
                    self._release_and_remove_path(aligned_temp)
                    master_grid, master_src = self._require_analysis_master_grid_path()
                    if self._rasters_have_identical_grid(layer_path, master_grid):
                        self.log_mca_message(
                            "  ✓ Criterion already on master analysis grid ({}) (warp skipped)".format(master_src)
                        )
                    else:
                        if self._warp_raster_to_reference_grid(master_grid, layer_path, aligned_temp, nodata_value=MCA_NODATA):
                            aligned_layer = QgsRasterLayer(aligned_temp, "{}_aligned".format(criterion_name), "gdal")
                            if aligned_layer.isValid():
                                working_layer = aligned_layer
                                self.log_mca_message(
                                    "  ✓ Criterion aligned to master analysis grid ({})".format(master_src)
                                )
                            else:
                                self.log_mca_message("  ERROR: aligned raster is invalid")
                                continue
                        else:
                            self.log_mca_message("  ERROR: could not align criterion to master grid")
                            continue
                except Exception as e:
                    self.log_mca_message(f"  ERROR: alignment failed: {str(e)}")
                    continue

            # Only hard-clamp layers that are already on [0,1] suitability scale.
            # Physical rasters (wind m/s, power density W/m²) must keep full range so
            # normalize_mca_values() can min-max the zonal means across grid cells.
            aligned_path_for_trace = aligned_temp
            clamp_input = self._file_path_from_raster_layer(working_layer)
            unit_clamped_temp = None
            try:
                if clamp_input and os.path.exists(clamp_input):
                    if self._raster_appears_unit_interval(clamp_input):
                        unit_clamped_temp = self._normalize_path(
                            os.path.join(tempfile.gettempdir(), "mca_unit_{}_{}.tif".format(processed_criteria, uuid.uuid4().hex[:8]))
                        )
                        self._release_and_remove_path(unit_clamped_temp)
                        if self._clamp_raster_to_unit_interval(clamp_input, unit_clamped_temp):
                            clamped_layer = QgsRasterLayer(unit_clamped_temp, "{}_unit".format(criterion_name), "gdal")
                            if clamped_layer.isValid():
                                working_layer = clamped_layer
                                self.log_mca_message("  ✓ Suitability layer clamped to [0,1] before MCA scoring")
                    else:
                        pre = self._get_raster_value_distribution(clamp_input)
                        self.log_mca_message(
                            "  ⚠ Skipping [0,1] clamp — physical raster detected "
                            "(max={:.4f}); values would collapse to 1.0".format(float(pre.get("max") or 0))
                        )
            except Exception as clamp_err:
                self.log_mca_message("  WARNING: clamp check failed: {}".format(clamp_err))

            extract_source_path = self._file_path_from_raster_layer(working_layer)
            ex_scale, ex_offset = self._get_scale_offset_for_path(extract_source_path)
            if ex_scale not in (1, 1.0) or ex_offset not in (0, 0.0):
                self.log_mca_message(
                    "  MCA extraction scale/offset: scale={} offset={} "
                    "(stored raw_value = pixel*scale+offset)".format(ex_scale, ex_offset)
                )

            mca_raster_path = extract_source_path
            crit_layer_path = self._file_path_from_raster_layer(layer_obj)
            try:
                self._trace_wind_or_density_mca_pipeline(
                    criterion_name,
                    crit_layer_path,
                    aligned_path=aligned_path_for_trace,
                    clamped_path=unit_clamped_temp,
                    mca_sampling_path=mca_raster_path,
                )
            except Exception as trace_err:
                self.log_mca_message("  WARNING: pipeline trace failed: {}".format(trace_err))
            if mca_raster_path:
                self._log_raster_band_debug(
                    mca_raster_path,
                    f"MCA sampling layer '{criterion_name}' (suitability/scored)",
                )

            # Mask criterion to Final Suitable Area so zonal means / samples ignore excluded pixels.
            masked_temp = self._normalize_path(
                os.path.join(
                    tempfile.gettempdir(),
                    "mca_suitable_masked_{}_{}.tif".format(processed_criteria, uuid.uuid4().hex[:8]),
                )
            )
            self._release_and_remove_path(masked_temp)
            mask_source = self._file_path_from_raster_layer(working_layer)
            if not mask_source or not self._multiply_raster_by_final_suitable_mask(mask_source, masked_temp):
                self.log_mca_message("  ERROR: Could not mask criterion to Final Suitable Area")
                continue
            masked_layer = QgsRasterLayer(masked_temp, "{}_suitable_masked".format(criterion_name), "gdal")
            if not masked_layer.isValid():
                self.log_mca_message("  ERROR: Suitable-masked raster is invalid")
                continue
            working_layer = masked_layer
            mca_raster_path = masked_temp
            self.log_mca_message("  ✓ Criterion masked to Final Suitable Area (feasible pixels only)")

            physical_sources = self._get_physical_raster_sources_for_report()
            for phys_key, phys_path in physical_sources.items():
                crit_lower = criterion_name.lower()
                linked = (
                    (phys_key == "wind_speed" and "wind" in crit_lower and "density" not in crit_lower)
                    or (phys_key == "wind_density" and self._criterion_name_matches_wind_density(criterion_name))
                    or (phys_key == "bathymetry" and any(t in crit_lower for t in ("bathymetry", "depth", "dem")))
                    or (phys_key == "slope" and "slope" in crit_lower)
                    or (phys_key == "powerline_distance" and ("distance" in crit_lower or "proximity" in crit_lower))
                )
                if linked:
                    self._log_raster_band_debug(phys_path, f"Physical source for '{criterion_name}' ({phys_key})")

            # Check CRS compatibility between raster and grid
            raster_crs = working_layer.crs()
            grid_crs = self.mca_grid_layer.crs()
            
            self.log_mca_message(f"  Raster CRS: {raster_crs.authid()} - {raster_crs.description()}")
            self.log_mca_message(f"  Grid CRS: {grid_crs.authid()} - {grid_crs.description()}")
            
            # Check if CRS match
            crs_mismatch = raster_crs != grid_crs
            if crs_mismatch:
                self.log_mca_message(f"  ⚠️ CRS mismatch detected - will transform coordinates during sampling")
            
            # Check if raster overlaps with grid (transform extents if CRS differ)
            raster_extent = working_layer.extent()
            grid_extent = self.mca_grid_layer.extent()
            
            # Transform grid extent to raster CRS for comparison
            try:
                transform_ext = QgsCoordinateTransform(grid_crs, raster_crs, QgsProject.instance().transformContext())
                grid_extent_transformed = transform_ext.transformBoundingBox(grid_extent)
            except Exception as e:
                self.log_mca_message(f"  WARNING: Could not transform extents for comparison: {str(e)}")
                grid_extent_transformed = grid_extent
            
            if not raster_extent.intersects(grid_extent_transformed):
                self.log_mca_message(f"  WARNING: Raster extent does not overlap with grid extent")
                self.log_mca_message(f"  → Raster: {raster_extent.toString()}")
                self.log_mca_message(f"  → Grid (transformed to raster CRS): {grid_extent_transformed.toString()}")
                # Continue anyway - but likely will get NoData
            
            try:
                if use_continuous:
                    # Use zonal statistics (mean per grid cell)
                    self.log_mca_message(f"  Computing zonal statistics...")
                    
                    # Create temporary output layer with statistics
                    temp_dir = tempfile.gettempdir()
                    stats_output = os.path.join(temp_dir, f"zonal_stats_{uuid.uuid4().hex[:8]}.gpkg")
                    
                    result = processing.run("native:zonalstatisticsfb", {
                        'INPUT': self.mca_grid_layer,
                        'INPUT_RASTER': working_layer,
                        'RASTER_BAND': 1,
                        'COLUMN_PREFIX': 'zonal_',
                        'STATISTICS': [2],  # Mean only
                        'OUTPUT': stats_output
                    })
                    
                    if 'OUTPUT' not in result:
                        self.log_mca_message(f"  ERROR: Zonal statistics failed")
                        continue
                    
                    # CRITICAL: Reload layer from disk (hidden from TOC - intermediate processing layer)
                    stats_path = result['OUTPUT']
                    stats_layer = self.reload_layer_from_path(stats_path, f"Zonal Stats {criterion_name}", hide_from_toc=True)
                    if not stats_layer or not stats_layer.isValid():
                        self.log_mca_message(f"  ERROR: Failed to reload statistics layer")
                        continue
                    
                    # Extract values
                    # NOTE: zonal statistics may suffix fields when names already exist
                    # (e.g., zonal_mean, zonal_mean_1, zonal_mean_2).
                    # Pick the most recent mean-like field robustly.
                    mean_field = 'zonal_mean'
                    extracted_count = 0
                    skipped_no_grid_id = 0
                    skipped_no_value = 0
                    
                    # Check if grid_id field exists
                    grid_id_idx = stats_layer.fields().indexFromName('grid_id')
                    mean_field_idx = stats_layer.fields().indexFromName(mean_field)
                    if mean_field_idx == -1:
                        try:
                            field_names = [f.name() for f in stats_layer.fields()]
                            mean_candidates = [
                                n for n in field_names
                                if n.startswith('zonal_') and ('mean' in n.lower())
                            ]
                            if mean_candidates:
                                # choose last candidate (typically newest suffixed field)
                                mean_field = mean_candidates[-1]
                                mean_field_idx = stats_layer.fields().indexFromName(mean_field)
                        except Exception:
                            mean_field_idx = -1
                    
                    if grid_id_idx == -1:
                        self.log_mca_message(f"  ERROR: grid_id field not found in zonal statistics layer")
                        self.log_mca_message(f"  → Available fields: {[f.name() for f in stats_layer.fields()]}")
                        continue
                    
                    if mean_field_idx == -1:
                        self.log_mca_message(f"  ERROR: {mean_field} field not found in zonal statistics layer")
                        self.log_mca_message(f"  → Available fields: {[f.name() for f in stats_layer.fields()]}")
                        continue
                    
                    for feature in stats_layer.getFeatures():
                        grid_id = feature.attribute('grid_id')
                        if grid_id is None:
                            skipped_no_grid_id += 1
                            continue
                        if not self._mca_grid_id_is_scorable(grid_id):
                            skipped_no_value += 1
                            continue
                        
                        raw_value = feature.attribute(mean_field)
                        if raw_value is None:
                            skipped_no_value += 1
                            continue
                        raw_value_f = self._safe_to_float(raw_value)
                        if raw_value_f is None:
                            skipped_no_value += 1
                            continue
                        if not np.isfinite(raw_value_f) or np.isclose(raw_value_f, float(MCA_NODATA), rtol=0.0, atol=1e-8):
                            skipped_no_value += 1
                            continue
                        physical_value = self._apply_raster_scale_offset(raw_value_f, ex_scale, ex_offset)
                        if physical_value is None:
                            skipped_no_value += 1
                            continue
                        
                        self.mca_data_matrix.append({
                            'grid_id': int(grid_id),
                            'criterion_name': criterion_name,
                            'raw_value': float(physical_value),
                            'weight': weight,
                            'role': role
                        })
                        extracted_count += 1
                    
                    self.log_mca_message(f"  ✓ Zonal statistics: {extracted_count} records extracted")
                    if skipped_no_grid_id > 0:
                        self.log_mca_message(f"  ⚠️ Skipped {skipped_no_grid_id} features (no grid_id)")
                    if skipped_no_value > 0:
                        self.log_mca_message(f"  ⚠️ Skipped {skipped_no_value} features (no value)")
                    if extracted_count == 0:
                        self.log_mca_message("  ⚠️ Zonal stats produced 0 rows; trying centroid sampling fallback...")
                        try:
                            centroids_output = os.path.join(tempfile.gettempdir(), f"centroids_fallback_{uuid.uuid4().hex[:8]}.gpkg")
                            c_result = processing.run("native:centroids", {
                                'INPUT': self.mca_grid_layer,
                                'ALL_ATTRIBUTES': True,
                                'OUTPUT': centroids_output
                            })
                            if 'OUTPUT' in c_result:
                                sampled_output = os.path.join(tempfile.gettempdir(), f"sampled_fallback_{uuid.uuid4().hex[:8]}.gpkg")
                                s_result = processing.run("native:rastersampling", {
                                    'INPUT': c_result['OUTPUT'],
                                    'RASTERCOPY': working_layer,
                                    'COLUMN_PREFIX': 'sample_',
                                    'OUTPUT': sampled_output
                                })
                                if 'OUTPUT' in s_result:
                                    sampled_layer = QgsVectorLayer(s_result['OUTPUT'], "SampledFallback", "ogr")
                                    if sampled_layer.isValid():
                                        sample_field = 'sample_1'
                                        for feature in sampled_layer.getFeatures():
                                            grid_id = feature.attribute('grid_id')
                                            if grid_id is None:
                                                continue
                                            if not self._mca_grid_id_is_scorable(grid_id):
                                                continue
                                            rv = self._safe_to_float(feature.attribute(sample_field))
                                            if rv is None or not np.isfinite(rv) or np.isclose(rv, float(MCA_NODATA), rtol=0.0, atol=1e-8):
                                                continue
                                            pv = self._apply_raster_scale_offset(rv, ex_scale, ex_offset)
                                            if pv is None:
                                                continue
                                            self.mca_data_matrix.append({
                                                'grid_id': int(grid_id),
                                                'criterion_name': criterion_name,
                                                'raw_value': float(pv),
                                                'weight': weight,
                                                'role': role
                                            })
                                            extracted_count += 1
                                    self.log_mca_message(f"  ✓ Fallback sampling added {extracted_count} records total")
                        except Exception as fb_ex:
                            self.log_mca_message(f"  ⚠️ Fallback sampling failed: {fb_ex}")
                
                else:
                    # Sample raster at grid centroids
                    self.log_mca_message(f"  Sampling at centroids...")
                    
                    # Create centroids layer - IMPORTANT: Preserve all attributes including grid_id
                    temp_dir = tempfile.gettempdir()
                    centroids_output = os.path.join(temp_dir, f"centroids_{uuid.uuid4().hex[:8]}.gpkg")
                    
                    result = processing.run("native:centroids", {
                        'INPUT': self.mca_grid_layer,
                        'ALL_ATTRIBUTES': True,  # Preserve all attributes including grid_id
                        'OUTPUT': centroids_output
                    })
                    
                    if 'OUTPUT' not in result:
                        self.log_mca_message(f"  ERROR: Failed to create centroids")
                        continue
                    
                    # CRITICAL: Reload centroids layer from disk (hidden from TOC - intermediate processing layer)
                    centroids_path = result['OUTPUT']
                    centroids_layer = self.reload_layer_from_path(centroids_path, f"Centroids {criterion_name}", hide_from_toc=True)
                    if not centroids_layer or not centroids_layer.isValid():
                        self.log_mca_message(f"  ERROR: Failed to reload centroids layer")
                        continue
                    
                    # Verify grid_id attribute exists
                    grid_id_idx = centroids_layer.fields().indexFromName('grid_id')
                    if grid_id_idx == -1:
                        self.log_mca_message(f"  ERROR: grid_id attribute missing in centroids layer")
                        self.log_mca_message(f"  → This is required for MCA calculation")
                        continue
                    
                    # Sample raster values at centroids
                    # Use direct sampling approach for reliability
                    centroids_layer.startEditing()
                    
                    # Add sample field
                    sample_field_name = 'sample_1'
                    if centroids_layer.fields().indexFromName(sample_field_name) == -1:
                        centroids_layer.dataProvider().addAttributes([QgsField(sample_field_name, QVariant.Double)])
                        centroids_layer.updateFields()
                    
                    # Sample raster values at each point
                    # CRITICAL: Transform coordinates if CRS mismatch
                    provider = working_layer.dataProvider()
                    sample_field_idx = centroids_layer.fields().indexFromName(sample_field_name)
                    
                    # Create coordinate transform if CRS differ
                    transform = None
                    centroids_crs = centroids_layer.crs()
                    if centroids_crs != raster_crs:
                        transform = QgsCoordinateTransform(
                            centroids_crs, 
                            raster_crs, 
                            QgsProject.instance().transformContext()
                        )
                        self.log_mca_message(f"  → Transforming centroids from {centroids_crs.authid()} to {raster_crs.authid()}")
                    
                    sampled_count = 0
                    no_data_count = 0
                    error_count = 0
                    
                    for feature in centroids_layer.getFeatures():
                        geom = feature.geometry()
                        if not geom:
                            continue

                        grid_id = feature.attribute('grid_id')
                        if grid_id is None or not self._mca_grid_id_is_scorable(grid_id):
                            no_data_count += 1
                            continue
                        
                        point = geom.asPoint()

                        suitable_union = getattr(self, "_mca_final_suitable_union", None)
                        if suitable_union and not suitable_union.isEmpty():
                            try:
                                if not suitable_union.contains(geom):
                                    no_data_count += 1
                                    continue
                            except Exception as _be_exc:
                                _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L18480")
                        
                        # Transform point to raster CRS if needed
                        if transform:
                            try:
                                point = transform.transform(point)
                            except Exception as e:
                                error_count += 1
                                if error_count <= 3:  # Log first few errors
                                    self.log_mca_message(f"  → Transform error: {str(e)}")
                                continue
                        
                        # Sample raster value at point (point is now in raster CRS)
                        try:
                            value = provider.sample(point, 1)[0]  # Band 1
                            # Check for valid numeric value (not None, not NaN, not NoData)
                            if value is not None:
                                # Check for common NoData values
                                if isinstance(value, float):
                                    if value != value:  # NaN check
                                        no_data_count += 1
                                        continue
                                    if value == -9999 or value == -3.4028234663852886e+38:  # Common NoData values
                                        no_data_count += 1
                                        continue
                                
                                feature.setAttribute(sample_field_idx, float(value))
                                centroids_layer.updateFeature(feature)
                                sampled_count += 1
                            else:
                                no_data_count += 1
                        except Exception as e:
                            error_count += 1
                            if error_count <= 3:  # Log first few errors
                                self.log_mca_message(f"  → Sampling error at ({point.x():.2f}, {point.y():.2f}): {str(e)}")
                    
                    if sampled_count > 0:
                        self.log_mca_message(f"  ✓ Successfully sampled {sampled_count} cells")
                    if no_data_count > 0:
                        self.log_mca_message(f"  ⚠️ {no_data_count} cells had NoData/Null values")
                    if error_count > 0:
                        self.log_mca_message(f"  ⚠️ {error_count} cells had sampling/transform errors")
                    
                    centroids_layer.commitChanges()
                    
                    # CRITICAL: Save sampled centroids layer and reload
                    sampled_layer = self.save_and_reload_layer(
                        centroids_layer,
                        f"Sampled {criterion_name}",
                        f"sampled_{criterion_name.replace(' ', '_')}_{uuid.uuid4().hex[:8]}.gpkg"
                    )
                    
                    if not sampled_layer:
                        self.log_mca_message(f"  ERROR: Failed to save sampled layer")
                        continue
                    
                    # Extract values
                    sample_field = 'sample_1'  # First band
                    extracted_count = 0
                    skipped_no_grid_id = 0
                    skipped_no_value = 0
                    
                    # Verify grid_id field exists
                    grid_id_idx = sampled_layer.fields().indexFromName('grid_id')
                    sample_field_idx = sampled_layer.fields().indexFromName(sample_field)
                    
                    if grid_id_idx == -1:
                        self.log_mca_message(f"  ERROR: grid_id field not found in sampled layer")
                        self.log_mca_message(f"  → Available fields: {[f.name() for f in sampled_layer.fields()]}")
                        continue
                    
                    if sample_field_idx == -1:
                        self.log_mca_message(f"  ERROR: {sample_field} field not found in sampled layer")
                        self.log_mca_message(f"  → Available fields: {[f.name() for f in sampled_layer.fields()]}")
                        continue
                    
                    for feature in sampled_layer.getFeatures():
                        grid_id = feature.attribute('grid_id')
                        if grid_id is None:
                            skipped_no_grid_id += 1
                            continue
                        if not self._mca_grid_id_is_scorable(grid_id):
                            skipped_no_value += 1
                            continue
                        
                        raw_value = feature.attribute(sample_field)
                        if raw_value is None:
                            skipped_no_value += 1
                            continue
                        
                        # Handle QVariant conversion properly
                        raw_value_conv = self._safe_to_float(raw_value)
                        if raw_value_conv is None:
                            self.log_mca_message(f"  ⚠️ Skipped non-numeric value for grid_id {grid_id}")
                            skipped_no_value += 1
                            continue
                        raw_value = raw_value_conv
                        physical_value = self._apply_raster_scale_offset(raw_value, ex_scale, ex_offset)
                        if physical_value is None:
                            skipped_no_value += 1
                            continue
                        
                        self.mca_data_matrix.append({
                            'grid_id': int(grid_id),
                            'criterion_name': criterion_name,
                            'raw_value': float(physical_value),
                            'weight': weight,
                            'role': role
                        })
                        extracted_count += 1
                    
                    self.log_mca_message(f"  ✓ Sampling: {extracted_count} records extracted (sampled {sampled_count} cells)")
                    if skipped_no_grid_id > 0:
                        self.log_mca_message(f"  ⚠️ Skipped {skipped_no_grid_id} features (no grid_id)")
                    if skipped_no_value > 0:
                        self.log_mca_message(f"  ⚠️ Skipped {skipped_no_value} features (no value)")
            
            except Exception as e:
                self.log_mca_message(f"  ERROR: Exception during processing: {str(e)}")
                import traceback
                self.log_mca_message(f"  Traceback: {traceback.format_exc()}")
                continue
            finally:
                try:
                    if aligned_temp and os.path.exists(aligned_temp):
                        os.remove(aligned_temp)
                except Exception as _be_exc:
                    _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L18607")
                try:
                    if unit_clamped_temp and os.path.exists(unit_clamped_temp):
                        os.remove(unit_clamped_temp)
                except Exception as _be_exc:
                    _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L18612")
                try:
                    if masked_temp and os.path.exists(masked_temp):
                        os.remove(masked_temp)
                except Exception as _be_exc:
                    _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L18617")
        if not self.mca_data_matrix:
            error_details = []
            error_details.append("No data could be extracted from criteria.")
            error_details.append("")
            error_details.append("Possible causes:")
            error_details.append("1. Criteria layers are not valid raster layers")
            error_details.append("2. Grid layer missing 'grid_id' attribute")
            error_details.append("3. Raster layers do not overlap with grid extent")
            error_details.append("4. All raster values are NULL/NoData")
            error_details.append("5. CRS mismatch between raster and grid")
            error_details.append("")
            error_details.append(f"Processed {processed_criteria} criteria, but extracted 0 data records.")
            
            # Check grid_id attribute
            if self.mca_grid_layer:
                grid_id_idx = self.mca_grid_layer.fields().indexFromName('grid_id')
                if grid_id_idx == -1:
                    error_details.append("")
                    error_details.append("⚠️ Grid layer is missing 'grid_id' attribute!")
            
            error_msg = "\n".join(error_details)
            self.log_mca_message("")
            self.log_mca_message("=" * 50)
            self.log_mca_message("ERROR: NO DATA EXTRACTED")
            self.log_mca_message("=" * 50)
            for line in error_details:
                self.log_mca_message(line)
            
            return None, error_msg
        
        self.log_mca_message("")
        self.log_mca_message(f"✓ Data matrix prepared: {len(self.mca_data_matrix)} records")
        self.log_mca_message(f"  Grid cells: {total_cells}")
        self.log_mca_message(f"  Criteria processed: {processed_criteria}/{len(included_criteria)}")
        self.log_mca_message(f"  Records per criterion: ~{len(self.mca_data_matrix) // len(included_criteria) if included_criteria else 0}")
        
        return self.mca_data_matrix, None

    def normalize_mca_values(self):
        """
        Normalize values in the MCA data matrix using min-max normalization.
        
        Process:
        1. Group values by criterion to calculate min/max per criterion
        2. Apply min-max normalization: (value - min) / (max - min)
        3. If role = "Penalizing": invert normalized score (1 - score)
        4. Multiply normalized score by weight (convert percentage to decimal)
        
        This ensures:
        - All criterion values are on the same scale (0-1)
        - Beneficial criteria: higher values = higher scores
        - Penalizing criteria: higher values = lower scores (inverted)
        - Weights from Phase 1 are properly applied
        
        Returns:
            tuple: (success: bool, error_message: str or None)
        """
        if not self.mca_data_matrix:
            return False, "Data matrix is empty. Please prepare data first."
        
        self.log_mca_message("=" * 50)
        self.log_mca_message("NORMALIZING VALUES")
        self.log_mca_message("=" * 50)
        
        # Group by criterion to calculate min/max per criterion
        criteria_groups = {}
        for record in self.mca_data_matrix:
            criterion_name = record['criterion_name']
            if criterion_name not in criteria_groups:
                criteria_groups[criterion_name] = []
            criteria_groups[criterion_name].append(record)

        self._mca_criterion_norm_meta = {}
        
        # Normalize each criterion
        total_weighted_sum = 0.0
        for criterion_name, records in criteria_groups.items():
            # Calculate min and max
            values = [r.get('raw_value', 0.0) for r in records if r.get('raw_value') is not None]
            
            if not values:
                self.log_mca_message(f"WARNING: Criterion '{criterion_name}' has no valid values")
                continue
            
            min_val = min(values)
            max_val = max(values)
            
            # Detect binary/excluded layers (values are mostly 0 and 1)
            unique_values = set(values)
            is_binary = len(unique_values) <= 2 and all(v in [0, 1] for v in unique_values)
            
            # Handle constant values
            if min_val == max_val:
                range_val = 1.0
                self.log_mca_message(f"WARNING: Criterion '{criterion_name}' has constant value {min_val:.6f}")
            else:
                range_val = max_val - min_val
            
            # Get weight and role from first record (should be same for all)
            sample_record = records[0]
            weight = sample_record.get('weight', 0.0)
            role = sample_record.get('role', 'Beneficial')

            self._mca_criterion_norm_meta[criterion_name] = {
                'min': min_val,
                'max': max_val,
                'range': range_val,
                'weight': weight,
                'role': role,
                'is_binary': is_binary,
            }

            self._log_criterion_variability_warnings(criterion_name, values)
            
            self.log_mca_message(f"Criterion: {criterion_name}")
            self.log_mca_message(f"  Range: [{min_val:.6f}, {max_val:.6f}]")
            self.log_mca_message(f"  Weight: {weight:.2f}%")
            self.log_mca_message(f"  Role: {role}")
            self.log_mca_message(f"  Records: {len(records)}")
            
            # Warn if binary layer is used as beneficial (should be penalizing)
            if is_binary and role == "Beneficial":
                self.log_mca_message(f"  ⚠️ WARNING: '{criterion_name}' appears to be a binary/excluded layer (values: 0, 1)")
                self.log_mca_message(f"     Consider setting Role to 'Penalizing' for excluded areas")
            
            # Warn if binary layer has very high weight (might dominate results)
            if is_binary and weight > 50:
                self.log_mca_message(f"  ⚠️ WARNING: Binary/excluded layer has high weight ({weight:.2f}%)")
                self.log_mca_message(f"     This may cause excluded areas to have very low final scores")
            
            # Normalize each record
            criterion_weighted_sum = 0.0
            for record in records:
                raw_value = record.get('raw_value', 0.0)
                if raw_value is None:
                    raw_value = 0.0
                
                # Min-max normalization
                if range_val == 0:
                    norm_before_invert = 0.5
                else:
                    norm_before_invert = (raw_value - min_val) / range_val
                
                # Invert if penalizing
                normalized = 1.0 - norm_before_invert if role == "Penalizing" else norm_before_invert
                
                # Multiply by weight (convert percentage to decimal)
                weight_decimal = weight / 100.0 if weight > 0 else 0.0
                weighted_score = normalized * weight_decimal
                
                record['norm_before_invert'] = norm_before_invert
                record['normalized_score'] = normalized
                record['weighted_score'] = weighted_score
                criterion_weighted_sum += abs(weighted_score)
            
            total_weighted_sum += criterion_weighted_sum
            self.log_mca_message(f"  Total weighted score sum for this criterion: {criterion_weighted_sum:.6f}")
        
        self.log_mca_message("")
        self.log_mca_message(f"Normalization complete")
        self.log_mca_message(f"Total weighted score sum across all criteria: {total_weighted_sum:.6f}")
        
        if total_weighted_sum == 0.0:
            self.log_mca_message("")
            self.log_mca_message("⚠️ WARNING: All weighted scores are zero after normalization!")
            self.log_mca_message("This indicates either:")
            self.log_mca_message("  1. All criterion weights are zero")
            self.log_mca_message("  2. All raw values are the same (no variation)")
            self.log_mca_message("  3. Data extraction produced invalid values")
        
        return True, None

    def _validate_mca_run_prerequisites(self):
        """
        Return (ok, actionable_message).
        Uses existing resolvers only — never invents or silently substitutes stale aliases.
        """
        self._clear_stale_mca_layer_refs()
        if not self._layer_cpp_alive(self.mca_grid_layer):
            self.mca_grid_layer = None
            return False, self.tr(
                "Grid layer is missing or invalid. Generate the MCA analysis grid first."
            )

        master_layer, master_path, _name = self.get_master_reference_raster_for_decision_making()
        if not master_layer or not master_path:
            return False, self.tr(
                "No master reference raster found. Complete Spatial Filtering first so criteria "
                "can be aligned to the current analysis grid, then generate the MCA grid and run the analysis."
            )

        if not self._resolve_final_suitable_mask_raster_path():
            return False, self.tr(
                "Final Suitable Area raster (spatial_filtered.tif) not found. "
                "Complete Spatial Filtering before running MCA."
            )

        criteria = self.extract_criteria_data() if hasattr(self, "extract_criteria_data") else []
        included = [c for c in (criteria or []) if c.get("include")]
        if not included:
            return False, self.tr(
                "No included criteria found. On the Decision Making tab, add criteria "
                "(Add Layer / Add Raster Criterion / Load Criteria Setup) and mark Include."
            )
        return True, ""

    def run_mca_calculation(self):
        """
        Run the complete Grid-based Multi-Criteria Analysis (MCA) calculation.
        
        Workflow:
        1. Prepare data matrix: Extract raster values for all criteria per grid cell
           - Uses zonal statistics if continuous criteria enabled
           - Otherwise samples at grid centroids
        2. Normalize values: Apply min-max normalization per criterion
           - Handles Beneficial/Penalizing roles
           - Applies weights from Phase 1
        3. Calculate final MCA scores: Sum weighted scores per grid cell
           - Formula: mca_score = Σ(weighted_score for all criteria)
        4. Update grid layer: Add mca_score attribute to each grid cell
        5. Update UI: Progress bar and log messages
        
        The final MCA score represents the overall suitability/priority for each grid cell,
        with higher scores indicating better suitability based on all weighted criteria.
        """
        if not hasattr(self.dlg, 'txt_mca_log'):
            QMessageBox.warning(self.dlg, "Error", "MCA log text area not found.")
            return

        # Clear previous log
        self.dlg.txt_mca_log.clear()

        # Validate prerequisites with actionable messages (does not weaken resolvers)
        ok_pre, pre_err = self._validate_mca_run_prerequisites()
        if not ok_pre:
            QMessageBox.warning(self.dlg, self.tr("MCA Prerequisites"), pre_err)
            self.log_mca_message("ERROR: {}".format(pre_err))
            return

        self.log_mca_message("=" * 50)
        self.log_mca_message("MCA CALCULATION STARTED")
        self.log_mca_message("=" * 50)

        if not self.ensure_included_weights_normalized_for_mca():
            return
        
        # Initialize progress
        self.update_mca_progress(0, 100)
        
        # Step 1: Prepare data matrix
        self.log_mca_message("Step 1: Preparing data matrix...")
        self.update_mca_progress(10)
        
        data_matrix, error = self.prepare_mca_data_matrix()
        if error:
            QMessageBox.critical(self.dlg, "Error", error)
            self.log_mca_message(f"ERROR: {error}")
            return
        
        if not data_matrix:
            QMessageBox.warning(self.dlg, "No Data", "No data could be extracted from criteria.")
            return
        
        # Step 2: Normalize values
        self.log_mca_message("")
        self.log_mca_message("Step 2: Normalizing values...")
        self.update_mca_progress(50)
        
        success, error = self.normalize_mca_values()
        if not success:
            QMessageBox.critical(self.dlg, "Error", error)
            self.log_mca_message(f"ERROR: {error}")
            return
        
        # Step 3: Calculate final MCA scores
        self.log_mca_message("")
        self.log_mca_message("Step 3: Calculating final MCA scores...")
        self.update_mca_progress(70)
        
        # Debug: Check data matrix content
        if not self.mca_data_matrix:
            QMessageBox.critical(self.dlg, "Error", "Data matrix is empty after normalization.")
            self.log_mca_message("ERROR: Data matrix is empty")
            return
        
        # Debug: Log sample records
        sample_records = self.mca_data_matrix[:5] if len(self.mca_data_matrix) >= 5 else self.mca_data_matrix
        self.log_mca_message(f"Sample records (first {len(sample_records)}):")
        for rec in sample_records:
            self.log_mca_message(f"  Grid ID: {rec.get('grid_id')}, "
                               f"Criterion: {rec.get('criterion_name')}, "
                               f"Raw: {rec.get('raw_value', 0):.6f}, "
                               f"Normalized: {rec.get('normalized_score', 0):.6f}, "
                               f"Weight: {rec.get('weight', 0):.2f}%, "
                               f"Weighted: {rec.get('weighted_score', 0):.6f}")
        
        # Group by grid_id and sum weighted scores
        # Also track criterion coverage per cell so cells missing any criterion become NoData.
        expected_criteria = set()
        try:
            for c in self.extract_criteria_data():
                if c.get("include", False):
                    nm = c.get("layer_name")
                    if nm:
                        expected_criteria.add(nm)
        except Exception as _be_exc:
            _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L18924")
        if not expected_criteria:
            expected_criteria = set(r.get("criterion_name") for r in self.mca_data_matrix if r.get("criterion_name"))
        expected_criteria_count = len(expected_criteria)
        grid_scores = {}
        grid_criteria_seen = {}
        total_weighted = 0.0
        for record in self.mca_data_matrix:
            grid_id = record.get('grid_id')
            weighted_score = record.get('weighted_score', 0.0)
            crit_name = record.get('criterion_name')
            
            if grid_id is None:
                self.log_mca_message(f"WARNING: Record missing grid_id: {record}")
                continue
            
            # Ensure grid_id is integer
            try:
                grid_id = int(grid_id)
            except (ValueError, TypeError):
                self.log_mca_message(f"WARNING: Invalid grid_id type: {grid_id} (type: {type(grid_id)})")
                continue
            
            if grid_id not in grid_scores:
                grid_scores[grid_id] = 0.0
                grid_criteria_seen[grid_id] = set()
            
            grid_scores[grid_id] += weighted_score
            if crit_name:
                grid_criteria_seen[grid_id].add(crit_name)
            total_weighted += abs(weighted_score)
        
        self.log_mca_message(f"Calculated scores for {len(grid_scores)} grid cells")
        self.log_mca_message(f"Total weighted score sum: {total_weighted:.6f}")

        debug_grids = getattr(self, "MCA_SCORE_DEBUG_GRID_IDS", [53, 10])
        try:
            self._log_mca_scoring_breakdown(debug_grids, grid_scores)
        except Exception as audit_err:
            self.log_mca_message("WARNING: MCA scoring audit failed: {}".format(audit_err))
        
        # Debug: Check if all scores are zero
        if total_weighted == 0.0:
            self.log_mca_message("WARNING: All weighted scores are zero!")
            self.log_mca_message("This could indicate:")
            self.log_mca_message("  1. All criterion weights are zero")
            self.log_mca_message("  2. All normalized scores are zero")
            self.log_mca_message("  3. Data extraction failed")
            
            # Check weights
            criteria_weights = {}
            for record in self.mca_data_matrix:
                crit_name = record.get('criterion_name', 'Unknown')
                weight = record.get('weight', 0.0)
                if crit_name not in criteria_weights:
                    criteria_weights[crit_name] = weight
            
            self.log_mca_message("Criterion weights:")
            for crit_name, weight in criteria_weights.items():
                self.log_mca_message(f"  {crit_name}: {weight:.2f}%")
        
        # Step 4: Update grid layer with mca_score attribute
        self.log_mca_message("")
        self.log_mca_message("Step 4: Updating grid layer...")
        self.update_mca_progress(85)

        # Geometry audit: snapshot fishnet before any scoring edits (proof baseline).
        fishnet_path_before_score = self._layer_source_path(self.mca_grid_layer)
        geom_snap_before_scoring = self._mca_snapshot_geometries_by_grid_id(self.mca_grid_layer)
        pre_stats = self._mca_grid_geometry_stats(self.mca_grid_layer, label="pre-scoring fishnet")
        self.log_mca_message("")
        self.log_mca_message("Pre-scoring fishnet snapshot:")
        self.log_mca_message("  layer_name: {}".format(pre_stats.get("name")))
        self.log_mca_message("  source_path: {}".format(pre_stats.get("source_path") or fishnet_path_before_score or "N/A"))
        self.log_mca_message("  feature_count: {}".format(pre_stats.get("feature_count")))
        self.log_mca_message("  total_area_m2: {:.2f}".format(pre_stats.get("total_area_m2", 0.0)))
        self.log_mca_message("  NOTE: boundary cells may be partial squares (AOI clip at grid generation); interior cells are full fishnet cells.")
        
        # Add mca_score field if it doesn't exist
        new_fields = []
        if self.mca_grid_layer.fields().indexFromName('mca_score') == -1:
            new_fields.append(QgsField('mca_score', QVariant.Double))
        if self.mca_grid_layer.fields().indexFromName('Suitable_Area_km2') == -1:
            new_fields.append(QgsField('Suitable_Area_km2', QVariant.Double))
        if self.mca_grid_layer.fields().indexFromName('Suitable_Percentage') == -1:
            new_fields.append(QgsField('Suitable_Percentage', QVariant.Double))
        if new_fields:
            self.mca_grid_layer.dataProvider().addAttributes(new_fields)
            self.mca_grid_layer.updateFields()
        
        coverage = getattr(self, 'mca_grid_suitable_coverage', {}) or {}
        # Update features
        self.mca_grid_layer.startEditing()
        updated_count = 0
        missing_count = 0
        
        # Get grid_id field index
        grid_id_idx = self.mca_grid_layer.fields().indexFromName('grid_id')
        mca_score_idx = self.mca_grid_layer.fields().indexFromName('mca_score')
        
        if grid_id_idx == -1:
            QMessageBox.critical(self.dlg, "Error", "Grid layer is missing 'grid_id' attribute!")
            self.mca_grid_layer.rollBack()
            return
        
        for feature in self.mca_grid_layer.getFeatures():
            grid_id_attr = feature.attribute('grid_id')
            
            if grid_id_attr is None:
                missing_count += 1
                continue
            
            # Convert to integer safely
            try:
                grid_id = int(grid_id_attr)
            except (ValueError, TypeError):
                self.log_mca_message(f"WARNING: Invalid grid_id in feature {feature.id()}: {grid_id_attr}")
                missing_count += 1
                continue
            
            cov = coverage.get(grid_id, {})
            suitable_km2 = float(cov.get('suitable_area_km2', 0.0) or 0.0)
            suitable_pct = float(cov.get('suitable_percentage', 0.0) or 0.0)
            feature.setAttribute('Suitable_Area_km2', suitable_km2)
            feature.setAttribute('Suitable_Percentage', suitable_pct)

            if suitable_pct <= 0:
                feature.setAttribute('mca_score', float(MCA_NODATA))
                self.mca_grid_layer.updateFeature(feature)
                missing_count += 1
                continue

            has_complete_coverage = (
                grid_id in grid_criteria_seen and
                len(grid_criteria_seen.get(grid_id, set())) >= expected_criteria_count
            )
            if grid_id in grid_scores and has_complete_coverage:
                feature.setAttribute('mca_score', grid_scores[grid_id])
                self.mca_grid_layer.updateFeature(feature)
                updated_count += 1
            else:
                # Missing one or more criteria for this cell -> mark NoData (not rank 0).
                feature.setAttribute('mca_score', float(MCA_NODATA))
                self.mca_grid_layer.updateFeature(feature)
                missing_count += 1
        
        self.mca_grid_layer.commitChanges()

        try:
            self._log_mca_scoring_geometry_audit(
                geom_snap_before_scoring,
                self.mca_grid_layer,
                "after attribute edit (commitChanges, before save/reload)",
            )
        except Exception as audit_err:
            self.log_mca_message("WARNING: Geometry audit after commit failed: {}".format(audit_err))
        
        if missing_count > 0:
            self.log_mca_message(
                f"WARNING: {missing_count} grid cells excluded (0% suitable area and/or missing criteria → NoData)"
            )
        
        # CRITICAL: Save grid layer with scores to stable location and reload
        # This prevents "wrapped C/C++ object has been deleted" errors
        self.log_mca_message("Saving grid layer with MCA scores to stable location...")
        grid_with_scores = self.save_and_reload_layer(
            self.mca_grid_layer,
            MCA_GRID_SCORE_MAP_LAYER_NAME,
            "mca_grid_with_scores.gpkg"
        )
        
        if not grid_with_scores:
            self.log_mca_message("ERROR: Failed to save grid layer with scores")
            QMessageBox.warning(self.dlg, "Save Error", "Failed to save grid layer with scores.")
        else:
            # Update reference to saved layer
            self._register_mca_grid_layer(grid_with_scores)
            self.log_mca_message(f"✓ MCA scores applied to grid successfully")
            self.log_mca_message(f"Updated {updated_count} grid cells with MCA scores")

        try:
            self._log_mca_scoring_geometry_audit(
                geom_snap_before_scoring,
                self.mca_grid_layer,
                "after save_and_reload ({})".format(MCA_GRID_SCORE_MAP_LAYER_NAME),
            )
            scored_path = self._layer_source_path(self.mca_grid_layer)
            fishnet_disk = self._normalize_path(
                os.path.join(self.get_mca_output_directory(), "mca_analysis_grid.gpkg")
            )
            if (
                fishnet_disk
                and os.path.exists(fishnet_disk)
                and scored_path
                and os.path.normpath(fishnet_disk) != os.path.normpath(scored_path)
            ):
                disk_fishnet = QgsVectorLayer(fishnet_disk, "FishnetOnDisk", "ogr")
                if disk_fishnet.isValid():
                    self._log_mca_scoring_geometry_audit(
                        self._mca_snapshot_geometries_by_grid_id(disk_fishnet),
                        self.mca_grid_layer,
                        "on-disk mca_analysis_grid.gpkg vs mca_grid_with_scores.gpkg",
                    )
        except Exception as audit_err:
            self.log_mca_message("WARNING: Geometry audit after save/reload failed: {}".format(audit_err))
        
        # Calculate statistics
        scores = list(grid_scores.values())
        min_score = min(scores) if scores else 0
        max_score = max(scores) if scores else 0
        mean_score = sum(scores) / len(scores) if scores else 0
        
        # Step 5: Apply graduated symbology
        self.log_mca_message("")
        self.log_mca_message("Step 5: Applying graduated symbology...")
        self.update_mca_progress(90)
        
        symbology_success = self.apply_mca_symbology()
        if symbology_success:
            self.log_mca_message("✓ Graduated symbology applied")
        else:
            self.log_mca_message("⚠ Warning: Symbology application had issues")
        
        # Step 6: Generate MCA report table
        self.log_mca_message("")
        self.log_mca_message("Step 6: Generating MCA report table...")
        self.update_mca_progress(95)
        
        report_path = self.generate_mca_report_table()
        if report_path:
            self.log_mca_message(f"✓ MCA report table exported to: {report_path}")
        else:
            self.log_mca_message("⚠ Warning: Report table generation skipped or failed")
        
        # Step 7: Primary map = scored grid ∩ Final Suitable Area; fishnet kept as debug layer.
        self.log_mca_message("")
        self.log_mca_message("Step 7: Building MCA Suitability Map (scored grid ∩ Final Suitable Area)...")
        self.update_mca_progress(98)

        self.mca_grid_scores_path = self._mca_grid_scores_disk_path()
        scored_for_viz = self._ensure_mca_grid_layer()
        if not scored_for_viz:
            self.log_mca_message("ERROR: Scored MCA grid layer is unavailable for visualization.")
            QMessageBox.warning(
                self.dlg,
                "MCA Visualization Error",
                "Could not resolve the scored MCA grid layer after saving.\n"
                "Check that mca_grid_with_scores.gpkg exists in the MCA output folder.",
            )
            self.update_mca_progress(100)
            return

        valid_scores = self._collect_valid_mca_scores(scored_for_viz)
        sym_min = min(valid_scores) if valid_scores else min_score
        sym_max = max(valid_scores) if valid_scores else max_score

        if not symbology_success:
            symbology_success = self.apply_mca_symbology(scored_for_viz)

        suitability_layer, viz_err = self._create_mca_suitability_map_layer(
            scored_for_viz,
            min_score=sym_min,
            max_score=sym_max,
        )
        if suitability_layer and self._layer_cpp_alive(suitability_layer):
            self.mca_suitability_map_path = (
                self._layer_source_path(suitability_layer) or self._mca_suitability_map_disk_path()
            )

        self._remove_mca_map_layers_except()
        self._clear_stale_mca_layer_refs()

        grid_layer = self._load_mca_grid_score_map_layer()
        if grid_layer and self._layer_cpp_alive(grid_layer):
            grid_layer.setName(MCA_GRID_SCORE_MAP_LAYER_NAME)
            if not symbology_success:
                symbology_success = self.apply_mca_symbology(grid_layer)
            QgsProject.instance().addMapLayer(grid_layer, addToLegend=False)
            grid_layer.setCustomProperty("wind_plugin_hidden", True)
            grid_layer.setCustomProperty("wind_plugin_mca_debug", True)
            self._register_mca_grid_layer(grid_layer)
            self.log_mca_message(
                "✓ {} saved (full fishnet, hidden from legend — debug/calculation view)".format(
                    MCA_GRID_SCORE_MAP_LAYER_NAME
                )
            )
        else:
            self.log_mca_message("⚠ Could not reload {} from disk".format(MCA_GRID_SCORE_MAP_LAYER_NAME))

        suitability_layer = self._load_mca_suitability_map_layer()
        if suitability_layer and self._layer_cpp_alive(suitability_layer):
            if not self.apply_mca_symbology(suitability_layer):
                try:
                    if grid_layer and self._layer_cpp_alive(grid_layer) and grid_layer.renderer():
                        suitability_layer.setRenderer(grid_layer.renderer().clone())
                        suitability_layer.triggerRepaint()
                except Exception as _be_exc:
                    _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L19221")
            QgsProject.instance().addMapLayer(suitability_layer)
            self._register_mca_suitability_map_layer(suitability_layer)
            self.log_mca_message(
                "✓ {} added to map ({} suitable fragments, graduated symbology)".format(
                    MCA_SUITABILITY_MAP_LAYER_NAME,
                    suitability_layer.featureCount(),
                )
            )
            self.log_mca_message("  displayed_layer_name: '{}'".format(suitability_layer.name()))
            self.log_mca_message("  displayed_source_path: {}".format(
                self._layer_source_path(suitability_layer) or "N/A"
            ))
            self.log_mca_message("  symbology_renderer: {}".format(
                type(suitability_layer.renderer()).__name__
                if suitability_layer.renderer() else "none"
            ))
        else:
            self.mca_suitability_map_layer = None
            self.mca_suitability_map_layer_id = None
            self.log_mca_message(
                "⚠ Could not build {}: {}".format(
                    MCA_SUITABILITY_MAP_LAYER_NAME,
                    viz_err or "unknown error",
                )
            )
            if grid_layer and self._layer_cpp_alive(grid_layer):
                QgsProject.instance().addMapLayer(grid_layer, addToLegend=True)
                grid_layer.setCustomProperty("wind_plugin_hidden", False)
                self.log_mca_message("  Fallback: showing full fishnet {}".format(MCA_GRID_SCORE_MAP_LAYER_NAME))

        try:
            self._log_mca_project_layers_audit()
        except Exception as audit_err:
            self.log_mca_message("WARNING: Project layers audit failed: {}".format(audit_err))
        
        # Update current_run.json only after successful MCA outputs exist.
        try:
            self._update_manifest_after_successful_mca()
        except Exception as man_err:
            self.log_mca_message("WARNING: current_run manifest update failed: {}".format(man_err))

        self.log_mca_message("")
        self.log_mca_message("=" * 50)
        self.log_mca_message("MCA CALCULATION COMPLETE")
        self.log_mca_message("=" * 50)
        self.log_mca_message(f"Grid cells processed: {updated_count}")
        self.log_mca_message(f"Score range: [{min_score:.6f}, {max_score:.6f}]")
        self.log_mca_message(f"Mean score: {mean_score:.6f}")
        
        self.update_mca_progress(100)
        
        QMessageBox.information(
            self.dlg,
            "MCA Complete",
            f"MCA calculation completed successfully!\n\n"
            f"Processed: {updated_count} grid cells\n"
            f"Score range: [{min_score:.4f}, {max_score:.4f}]\n"
            f"Mean score: {mean_score:.4f}\n\n"
            f"Primary map: {MCA_SUITABILITY_MAP_LAYER_NAME} (scored grid ∩ Final Suitable Area).\n"
            f"Debug layer: {MCA_GRID_SCORE_MAP_LAYER_NAME} (full fishnet, hidden in legend)."
        )

    def _remove_mca_map_layers_except(self, keep_layer_ids=None):
        """Remove MCA visualization layers from the project (optional keep one or more layer ids)."""
        keep = set()
        if keep_layer_ids is not None:
            if isinstance(keep_layer_ids, (list, tuple, set)):
                keep = set(keep_layer_ids)
            else:
                keep = {keep_layer_ids}
        for name in MCA_LEGACY_MAP_LAYER_NAMES:
            for layer in QgsProject.instance().mapLayersByName(name):
                if not self._layer_cpp_alive(layer):
                    continue
                if layer.id() in keep:
                    continue
                QgsProject.instance().removeMapLayer(layer.id())
        self._clear_stale_mca_layer_refs()

    @staticmethod
    def _mca_score_from_feature_attribute(score):
        """Parse mca_score attribute to float, or None if missing/invalid."""
        if score is None:
            return None
        try:
            if isinstance(score, QVariant):
                if score.isNull():
                    return None
                score = score.toDouble()[0] if score.canConvert(QVariant.Double) else float(str(score))
            else:
                score = float(score)
        except (ValueError, TypeError):
            return None
        if not np.isfinite(score):
            return None
        if np.isclose(score, float(MCA_NODATA), rtol=0.0, atol=1e-8):
            return None
        return score

    def _collect_valid_mca_scores(self, layer):
        """Return list of valid (non-NoData) mca_score values from a vector layer."""
        if not layer or not layer.isValid():
            return []
        if layer.fields().indexFromName("mca_score") == -1:
            return []
        scores = []
        for feature in layer.getFeatures():
            score = self._mca_score_from_feature_attribute(feature.attribute("mca_score"))
            if score is not None:
                scores.append(score)
        return scores

    @staticmethod
    def _mca_equal_interval_breaks(min_score, max_score, class_count=6):
        """Equal-interval class breaks aligned with MCA report suitability categories."""
        if class_count < 1:
            return [min_score, max_score]
        if max_score <= min_score:
            upper = min_score + 1e-9
            return [min_score] + [upper] * class_count
        span = max_score - min_score
        return [min_score + span * (i / class_count) for i in range(class_count + 1)]

    @staticmethod
    def _mca_suitability_category_for_score(score, min_score, max_score):
        """Map mca_score to a suitability class label (matches graduated symbology breaks)."""
        if score is None:
            return None
        try:
            score = float(score)
        except (TypeError, ValueError):
            return None
        if not np.isfinite(score) or np.isclose(score, float(MCA_NODATA), rtol=0.0, atol=1e-8):
            return None
        if max_score <= min_score:
            return MCA_SUITABILITY_CLASS_LABELS[2]
        breaks = WindSuitability._mca_equal_interval_breaks(
            min_score, max_score, len(MCA_SUITABILITY_CLASS_LABELS)
        )
        class_count = len(MCA_SUITABILITY_CLASS_LABELS)
        for i in range(class_count):
            lower = breaks[i]
            upper = breaks[i + 1] if i < class_count - 1 else max_score + 1e-9
            if lower <= score <= upper or (i == class_count - 1 and score >= lower):
                return MCA_SUITABILITY_CLASS_LABELS[i]
        return MCA_SUITABILITY_CLASS_LABELS[-1]

    def _intersect_scored_grid_with_final_suitable_area(self, scored_layer, output_gpkg_path):
        """
        Vector intersection: scored MCA fishnet ∩ Final Suitable Area polygons.
        Scores are not recomputed; geometries come from the intersection only.

        Writes to a staging GPKG first, then publishes atomically so a previous
        valid suitability map is preserved on failure.
        """
        if not scored_layer or not scored_layer.isValid():
            return None
        suitable_layer = self._get_final_suitable_area_layer_for_mca(scored_layer.crs())
        if not suitable_layer:
            self.log_mca_message("  Final Suitable Area vector not found for intersection.")
            return None

        final_path = self._normalize_path(output_gpkg_path)
        staging_dir = _rl.create_staging_directory(self.get_canonical_results_root(), kind="mca_suit")
        staging_path = self._normalize_path(
            os.path.join(staging_dir, os.path.basename(final_path) or MCA_SUITABILITY_MAP_FILENAME)
        )
        input_field_names = [f.name() for f in scored_layer.fields()]
        staged = None
        try:
            res = processing.run("native:intersection", {
                "INPUT": scored_layer,
                "OVERLAY": suitable_layer,
                "INPUT_FIELDS": input_field_names,
                "OVERLAY_FIELDS": [],
                "OUTPUT": staging_path,
            })
            out = res.get("OUTPUT") if isinstance(res, dict) else None
            if out and os.path.exists(out):
                staged = self._normalize_path(out)
        except Exception as e:
            self.log_mca_message("  native:intersection failed: {} — retrying minimal params.".format(e))
            try:
                res = processing.run("native:intersection", {
                    "INPUT": scored_layer,
                    "OVERLAY": suitable_layer,
                    "OUTPUT": staging_path,
                })
                out = res.get("OUTPUT") if isinstance(res, dict) else None
                if out and os.path.exists(out):
                    staged = self._normalize_path(out)
            except Exception as e2:
                self.log_mca_message("  native:intersection failed: {}".format(e2))
        if not staged:
            _rl.safe_remove_tree(staging_dir, protected_paths=self._protected_manifest_paths())
            return None
        ok, err = self._publish_gpkg_to_path(staged, final_path, min_features=0)
        _rl.safe_remove_tree(staging_dir, protected_paths=self._protected_manifest_paths())
        if not ok:
            self.log_mca_message(
                "  Suitability map publication failed (previous file left unchanged): {}".format(err)
            )
            return None
        return final_path

    def _create_mca_suitability_map_layer(self, scored_grid_layer, min_score=None, max_score=None):
        """
        Build the primary MCA map: scored grid intersected with Final Suitable Area.

        Transfers grid attributes (grid_id, mca_score, suitable metrics, etc.) and applies
        the same QgsGraduatedSymbolRenderer used on the fishnet. Does not alter MCA scores.
        """
        if not self._layer_cpp_alive(scored_grid_layer):
            return None, "Scored MCA grid layer is invalid."

        valid_scores = self._collect_valid_mca_scores(scored_grid_layer)
        if min_score is None:
            min_score = min(valid_scores) if valid_scores else 0.0
        if max_score is None:
            max_score = max(valid_scores) if valid_scores else 1.0

        output_path = self._normalize_path(
            os.path.join(self.get_mca_output_directory(), MCA_SUITABILITY_MAP_FILENAME)
        )
        intersected_path = self._intersect_scored_grid_with_final_suitable_area(
            scored_grid_layer, output_path
        )
        if not intersected_path:
            return None, "Could not intersect scored grid with Final Suitable Area."

        layer = QgsVectorLayer(intersected_path, MCA_SUITABILITY_MAP_LAYER_NAME, "ogr")
        if not layer.isValid():
            return None, "Failed to load intersected MCA Suitability Map layer."

        layer.startEditing()
        if layer.fields().indexFromName("Suitability_Category") == -1:
            layer.dataProvider().addAttributes([
                QgsField("Suitability_Category", QVariant.String),
            ])
            layer.updateFields()
        cat_idx = layer.fields().indexFromName("Suitability_Category")

        to_delete = []
        for feature in layer.getFeatures():
            score = self._mca_score_from_feature_attribute(feature.attribute("mca_score"))
            if score is None:
                to_delete.append(feature.id())
                continue
            category = self._mca_suitability_category_for_score(score, min_score, max_score)
            if cat_idx >= 0:
                feature.setAttribute(cat_idx, category or "")
                layer.updateFeature(feature)

        for fid in to_delete:
            layer.deleteFeature(fid)
        layer.commitChanges()

        if not self.apply_mca_symbology(layer):
            try:
                if scored_grid_layer.renderer():
                    layer.setRenderer(scored_grid_layer.renderer().clone())
                    layer.triggerRepaint()
            except Exception as _be_exc:
                _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L19485")

        self.log_mca_message(
            "  ✓ {}: {} polygons (scores from fishnet, geometry from intersection)".format(
                MCA_SUITABILITY_MAP_LAYER_NAME,
                layer.featureCount(),
            )
        )
        self.mca_suitability_map_path = intersected_path
        return layer, None

    def apply_mca_symbology(self, layer=None):
        """
        Apply QgsGraduatedSymbolRenderer on mca_score with six suitability classes.

        Classes: Very Weak, Weak, Fair, Moderate, Good, Excellent (equal intervals).
        One full grid cell = one class color; cell outlines remain visible.

        Returns:
            bool: True if symbology applied successfully, False otherwise
        """
        layer = layer or self.mca_grid_layer
        try:
            if not self._layer_cpp_alive(layer):
                return False

            if layer.fields().indexFromName("mca_score") == -1:
                self.log_mca_message("  ERROR: mca_score field not found")
                return False

            scores = self._collect_valid_mca_scores(layer)
            if not scores:
                self.log_mca_message("  ERROR: No valid MCA scores found for symbology")
                return False

            min_score = min(scores)
            max_score = max(scores)
            breaks = self._mca_equal_interval_breaks(min_score, max_score, len(MCA_SUITABILITY_CLASS_LABELS))
            ranges = []
            class_count = len(MCA_SUITABILITY_CLASS_LABELS)

            for i in range(class_count):
                lower = breaks[i]
                upper = breaks[i + 1] if i < class_count - 1 else max_score + 1e-9
                range_symbol = QgsSymbol.defaultSymbol(layer.geometryType())
                range_symbol.setColor(MCA_SUITABILITY_CLASS_COLORS[i])
                stroke = range_symbol.symbolLayer(0)
                if stroke:
                    stroke.setStrokeColor(QColor(0, 0, 0))
                    stroke.setStrokeWidth(0.1)
                label = "{} ({:.4f} - {:.4f})".format(
                    MCA_SUITABILITY_CLASS_LABELS[i],
                    lower,
                    max_score if i == class_count - 1 else breaks[i + 1],
                )
                ranges.append(QgsRendererRange(lower, upper, range_symbol, label))

            renderer = QgsGraduatedSymbolRenderer("mca_score", ranges)
            layer.setRenderer(renderer)
            layer.triggerRepaint()
            return True

        except Exception as e:
            self.log_mca_message(f"  ERROR applying symbology: {str(e)}")
            return False

    @staticmethod
    def _wind_power_density_w_m2(wind_speed_ms):
        """Estimate wind power density (W/m²) from mean wind speed at hub height."""
        try:
            v = float(wind_speed_ms)
            if not np.isfinite(v) or v < 0:
                return None
            return 0.5 * 1.225 * (v ** 3)
        except Exception:
            return None

    REPORT_DEBUG_GRID_ID = 10
    MCA_SCORE_DEBUG_GRID_IDS = [53, 10]

    def _apply_raster_scale_offset(self, raw_value, scale, offset):
        """Convert stored pixel value to physical value using GDAL/QGIS band scale and offset."""
        try:
            v = float(raw_value)
        except (TypeError, ValueError):
            return None
        s = 1.0 if scale in (None, 0, 0.0) else float(scale)
        o = 0.0 if offset is None else float(offset)
        return v * s + o

    def _get_scale_offset_for_path(self, raster_path):
        """Return (scale, offset) for a raster file path."""
        meta = self._get_raster_band_metadata(raster_path) if raster_path else {}
        return meta.get("scale", 1.0), meta.get("offset", 0.0)

    def _pixel_to_physical_value(self, pixel_raw, raster_path):
        """Apply physical = pixel * scale + offset (same rule as MCA report zonal stats)."""
        scale, offset = self._get_scale_offset_for_path(raster_path)
        physical = self._apply_raster_scale_offset(pixel_raw, scale, offset)
        if physical is None:
            return None
        return float(physical)

    def _get_plugin_version(self):
        """Read plugin version from metadata.txt for report metadata."""
        try:
            meta_path = os.path.join(self.plugin_dir, "metadata.txt")
            if os.path.isfile(meta_path):
                with open(meta_path, encoding="utf-8") as f:
                    for line in f:
                        if line.strip().lower().startswith("version="):
                            return line.split("=", 1)[1].strip()
        except Exception as _be_exc:
            _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L19598")
        return "unknown"

    def _criterion_name_matches_wind_density(self, criterion_name):
        crit_lower = (criterion_name or "").lower()
        return (
            "density" in crit_lower
            or "power-density" in crit_lower
            or "power density" in crit_lower
        )

    def _resolve_wind_density_raster_path(self):
        """
        Single source of truth for wind density: included weights-table criterion layer.
        Matches the raster used in MCA when DEU_power-density (or similar) is in criteria.
        """
        for crit in self.extract_criteria_data():
            if not crit.get("include"):
                continue
            if not self._criterion_name_matches_wind_density(crit.get("layer_name")):
                continue
            path = crit.get("layer_path")
            if not path and crit.get("layer"):
                path = self._file_path_from_raster_layer(crit.get("layer"))
            if path:
                p = self._normalize_path(path)
                if os.path.exists(p):
                    return p
        return None

    def _log_criterion_variability_warnings(self, criterion_name, values):
        """Warn when a criterion has almost no spread across grid cells."""
        if not values:
            return
        rounded = [round(float(v), 8) for v in values if v is not None]
        if not rounded:
            return
        unique_values = set(rounded)
        min_val = min(rounded)
        max_val = max(rounded)
        range_val = max_val - min_val
        unique_count = len(unique_values)
        min_unique = getattr(self, "MCA_MIN_UNIQUE_ZONAL_VALUES", MCA_MIN_UNIQUE_ZONAL_VALUES)

        reasons = []
        if min_val == max_val:
            reasons.append("All zonal values are identical (min == max).")
        if unique_count < min_unique:
            reasons.append(
                "Only {} unique zonal value(s) detected.".format(unique_count)
            )
        ref = max(abs(max_val), abs(min_val), 1e-9)
        if range_val > 0 and (range_val / ref) < 1e-4:
            reasons.append(
                "Very small value range relative to magnitude ({:.6g}).".format(range_val)
            )
        if not reasons:
            return
        self.log_mca_message("[WARNING]")
        self.log_mca_message("Criterion '{}'".format(criterion_name))
        for reason in reasons:
            self.log_mca_message(reason)
        self.log_mca_message("Criterion contributes almost no ranking power.")

    def _get_slope_thresholds_for_metadata(self):
        """Current slope suitability thresholds (degrees) for report metadata."""
        good_deg = GOOD_SLOPE_THRESHOLD
        moderate_deg = MODERATE_SLOPE_THRESHOLD
        max_deg = MAX_SLOPE_THRESHOLD
        if hasattr(self.dlg, "spinSlopeGood") and self.dlg.spinSlopeGood is not None:
            good_deg = self.dlg.spinSlopeGood.value()
        if hasattr(self.dlg, "spinSlopeModerate") and self.dlg.spinSlopeModerate is not None:
            moderate_deg = self.dlg.spinSlopeModerate.value()
        if hasattr(self.dlg, "spinSlopeMax") and self.dlg.spinSlopeMax is not None:
            max_deg = self.dlg.spinSlopeMax.value()
        return good_deg, moderate_deg, max_deg

    def _get_wind_speed_thresholds_for_metadata(self):
        """Wind speed suitability thresholds from UI (m/s)."""
        min_wind = max_wind = None
        if hasattr(self.dlg, "txtMinWindSpeed") and hasattr(self.dlg, "txtMaxWindSpeed"):
            try:
                min_txt = (self.dlg.txtMinWindSpeed.text() or "").strip()
                max_txt = (self.dlg.txtMaxWindSpeed.text() or "").strip()
                if min_txt and max_txt:
                    min_wind = float(min_txt)
                    max_wind = float(max_txt)
                    if not (math.isfinite(min_wind) and math.isfinite(max_wind)):
                        return None, None
                    if min_wind > max_wind:
                        min_wind, max_wind = max_wind, min_wind
            except ValueError as _be_exc:
                _rl.best_effort_ignore(_be_exc, "wind_suitability.py:L19690")
        return min_wind, max_wind

